def _legacy_failure_response(message: str, data: object | None = None) -> dict:
    return {"IsSuccess": False, "Data": data, "Message": message}


def _legacy_customer_business_failure_response(exc: HTTPException) -> dict:
    if exc.status_code in {status.HTTP_409_CONFLICT, status.HTTP_422_UNPROCESSABLE_ENTITY}:
        return _legacy_failure_response(str(exc.detail or "操作失败"))
    raise exc


def _legacy_contract_business_failure_response(exc: HTTPException) -> dict:
    if exc.status_code in {status.HTTP_409_CONFLICT, status.HTTP_422_UNPROCESSABLE_ENTITY}:
        return _legacy_failure_response(str(exc.detail or "操作失败"))
    raise exc


def _legacy_finance_business_failure_response(exc: HTTPException) -> dict:
    if exc.status_code in {status.HTTP_409_CONFLICT, status.HTTP_422_UNPROCESSABLE_ENTITY}:
        return _legacy_failure_response(str(exc.detail or "操作失败"))
    raise exc


FIELD_PERMISSION_DATA_KEYS = {
    "customer.billing": {"invoice_title", "taxpayer_id", "invoice_address", "invoice_phone"},
    "customer.bank": {"bank_name", "bank_account"},
    "customer.legal": {"credit_code", "legal_representative", "registered_address"},
    "contract.amount": {"amount"},
    "finance.amount": {"amount", "paid_amount", "invoice_amount", "refund_amount"},
    "hr.identity": {"id_no"},
}


def _customer_guid(record: BusinessRecord) -> str:
    """Return a stable customer GUID, including for legacy rows without one."""
    stored = str((record.data or {}).get("customer_guid") or "").strip()
    return stored or str(uuid5(NAMESPACE_URL, f"customer:{record.id}"))


def _customer_contact_dict(contact: dict) -> dict:
    """Project legacy contacts with explicit independent boolean state fields."""
    projected = dict(contact or {})
    projected.setdefault("is_received_email", True)
    projected.setdefault("is_contacted", True)
    projected.setdefault("is_people_base", True)
    return projected


def _record_dict(record: BusinessRecord, allowed_fields: set[str] | None = None) -> dict:
    data = dict(record.data or {})
    if record.module == "customer":
        data["contacts"] = [_customer_contact_dict(item) for item in list(data.get("contacts") or [])]
    if allowed_fields is not None:
        for permission, keys in FIELD_PERMISSION_DATA_KEYS.items():
            if permission not in allowed_fields:
                for key in keys: data.pop(key, None)
    result = {
        "id": record.id, "module": record.module, "serial_no": record.serial_no,
        "title": record.title, "customer": record.customer, "status": record.status,
        "owner": record.owner, "department": record.department,
        "description": record.description, "data": data,
        "created_at": record.created_at, "updated_at": record.updated_at,
    }
    if record.module == "ipr_case":
        result.update({
            "case_phase": data.get("case_phase", ""),
            "acceptance_date": data.get("accepted_at") or data.get("acceptance_date") or data.get("register_date") or "",
            "case_source": data.get("case_source") or data.get("case_origin_people_name") or data.get("origin_people_name") or "",
            "source_date": data.get("case_origin_date") or data.get("origin_date") or data.get("source_date") or "",
            "agent": data.get("agent") or data.get("procurator_name") or "",
            "writer": data.get("copywriter_name") or data.get("writer") or "",
            "handler": data.get("case_officer_name") or data.get("case_manager") or record.owner,
            "submitter": data.get("case_submitter_name") or data.get("submitter_name") or data.get("submitter") or "",
            "submit_date": data.get("case_submit_date") or data.get("submit_date") or "",
            "inventor": data.get("case_inventor") or data.get("inventor") or "",
            "deadline": data.get("deadline", ""),
            "contract_no": data.get("contract_no", ""),
            "contract_record_id": data.get("contract_record_id"),
        })
    if record.module == "customer":
        result["customer_guid"] = _customer_guid(record)
    return result


CONTRACT_PERSON_NAME_PLACEHOLDER = "姓名待维护"
CONTRACT_PERSON_NAME_PATTERN = re.compile(r"[\u3400-\u9fff]")
CONTRACT_NON_PERSON_NAME_MARKERS = PERSON_NAME_NON_PERSON_MARKERS


def _valid_contract_person_name(value: object, username: object = "") -> str:
    name = unicodedata.normalize("NFKC", str(value or "")).strip()
    compact_name = re.sub(r"\s+", "", name)
    if not compact_name:
        return ""
    return name


def _valid_contract_chinese_person_name(value: object) -> str:
    name = _valid_contract_person_name(value)
    return name if CONTRACT_PERSON_NAME_PATTERN.search(name) else ""


def _contract_person_display_name(value: object, names_by_username: dict[str, str] | None = None) -> str:
    raw = unicodedata.normalize("NFKC", str(value or "")).strip()
    direct = _valid_contract_chinese_person_name(raw)
    if direct:
        return direct
    mapped = _valid_contract_person_name((names_by_username or {}).get(raw.lower(), ""), raw)
    return mapped or CONTRACT_PERSON_NAME_PLACEHOLDER


def _contract_person_values(value: object) -> list[str]:
    if isinstance(value, list):
        return [str(item or "").strip() for item in value if str(item or "").strip()]
    return [item.strip() for item in re.split(r"[、,，;；]", str(value or "")) if item.strip()]


def _contract_customer_manager_values(
    contract: BusinessRecord,
    customer: BusinessRecord | None,
) -> list[str]:
    """Use the linked customer's current manager roster for contract presentation.

    Contract records retain the manager snapshot captured when they were created,
    but list/detail responses must follow later customer-manager maintenance.  The
    snapshot remains the fallback only when the customer relation cannot be
    resolved, so this projection never rewrites historical contract data.
    """
    if customer:
        customer_data = customer.data or {}
        return list(dict.fromkeys(_contract_person_values(
            customer_data.get("customer_managers") or [customer.owner]
        )))
    contract_data = contract.data or {}
    return list(dict.fromkeys(_contract_person_values(
        contract_data.get("customer_managers") or contract_data.get("customer_manager")
    )))


def _contract_investigation_source_data(
    contract: BusinessRecord,
    customer: BusinessRecord | None,
) -> dict[str, object]:
    """Build immutable source identifiers for a contract-created investigation."""
    contract_data = contract.data or {}
    return {
        "contract_id": contract.id,
        "contract_record_id": contract.id,
        "contract_no": contract.serial_no,
        "contract_name": contract.title,
        "customer_id": customer.id if customer else _positive_record_id(
            contract_data.get("customer_id") or contract_data.get("customer_record_id")
        ) or None,
        "customer_record_id": customer.id if customer else _positive_record_id(
            contract_data.get("customer_id") or contract_data.get("customer_record_id")
        ) or None,
        "customer_no": customer.serial_no if customer else str(contract_data.get("customer_no") or ""),
        "customer_name": customer.title if customer else contract.customer,
    }


def _positive_record_id(value: object) -> int:
    try:
        parsed = int(value or 0)
    except (TypeError, ValueError):
        return 0
    return parsed if parsed > 0 else 0


def _normalized_customer_name(value: object) -> str:
    return " ".join(unicodedata.normalize("NFKC", str(value or "")).strip().casefold().split())


def _customer_reference_from_maps(
    customer_name: object,
    data: dict,
    customers_by_id: dict[int, BusinessRecord],
    customers_by_no: dict[str, list[BusinessRecord]],
    customers_by_name: dict[str, list[BusinessRecord]],
) -> tuple[BusinessRecord | None, str]:
    """Resolve ID, then customer number, then an unambiguous legacy name."""
    name = _normalized_customer_name(customer_name)
    customer_id = _positive_record_id(data.get("customer_id") or data.get("customer_record_id"))
    customer_no = str(data.get("customer_no") or "").strip()
    if customer_id:
        customer = customers_by_id.get(customer_id)
        if not customer:
            return None, "missing_id"
        if customer_no and customer.serial_no != customer_no:
            return None, "mismatched_reference"
        if name and _normalized_customer_name(customer.title) != name:
            return None, "mismatched_reference"
        return customer, "customer_id"
    if customer_no:
        candidates = customers_by_no.get(customer_no, [])
        if len(candidates) != 1:
            return None, "missing_number" if not candidates else "ambiguous_number"
        customer = candidates[0]
        if name and _normalized_customer_name(customer.title) != name:
            return None, "mismatched_reference"
        return customer, "customer_no"
    candidates = customers_by_name.get(name, []) if name else []
    if len(candidates) == 1:
        return candidates[0], "unique_name"
    return None, "missing_name" if not candidates else "ambiguous_name"


async def _contract_customer_projection_context(records: list[BusinessRecord], db: AsyncSession) -> dict:
    contracts = [record for record in records if record.module == "contract"]
    if not contracts:
        return {"customers_by_id": {}, "customers_by_no": {}, "customers_by_name": {}, "current_steps": {}}
    customer_ids = {_positive_record_id((record.data or {}).get("customer_id") or (record.data or {}).get("customer_record_id")) for record in contracts}
    customer_ids.discard(0)
    customer_nos = {str((record.data or {}).get("customer_no") or "").strip() for record in contracts}
    customer_nos.discard("")
    customer_names = {_normalized_customer_name(record.customer) for record in contracts}
    customer_names.discard("")
    legacy_customer_names = {
        _normalized_customer_name(record.customer)
        for record in contracts
        if not _positive_record_id((record.data or {}).get("customer_id") or (record.data or {}).get("customer_record_id"))
        and not str((record.data or {}).get("customer_no") or "").strip()
        and _normalized_customer_name(record.customer)
    }
    customer_conditions = [BusinessRecord.module == "customer", BusinessRecord.status.not_in({"已回收"})]
    lookup_conditions = []
    if customer_ids:
        lookup_conditions.append(BusinessRecord.id.in_(customer_ids))
    if customer_nos:
        lookup_conditions.append(BusinessRecord.serial_no.in_(customer_nos))
    if customer_names:
        lookup_conditions.append(BusinessRecord.title.in_([record.customer for record in contracts if _normalized_customer_name(record.customer) in customer_names]))
    customers = list((await db.scalars(select(BusinessRecord).where(*customer_conditions, or_(*lookup_conditions)))).all()) if lookup_conditions else []
    if legacy_customer_names:
        # Historical contracts may contain full-width characters or irregular
        # whitespace. SQL equality cannot reproduce the NFKC key, so fetch the
        # bounded customer directory once and resolve only unambiguous keys.
        legacy_candidates = list((await db.scalars(select(BusinessRecord).where(*customer_conditions))).all())
        seen_customer_ids = {customer.id for customer in customers}
        customers.extend(
            customer for customer in legacy_candidates
            if customer.id not in seen_customer_ids and _normalized_customer_name(customer.title) in legacy_customer_names
        )
    customers_by_id = {customer.id: customer for customer in customers}
    customers_by_no: dict[str, list[BusinessRecord]] = {}
    customers_by_name: dict[str, list[BusinessRecord]] = {}
    for customer in customers:
        customers_by_no.setdefault(str(customer.serial_no or "").strip(), []).append(customer)
        customers_by_name.setdefault(_normalized_customer_name(customer.title), []).append(customer)
    contract_ids = [contract.id for contract in contracts]
    steps = list((await db.scalars(select(ContractApprovalStep).where(
        ContractApprovalStep.contract_record_id.in_(contract_ids),
        ContractApprovalStep.status == "待审批",
    ).order_by(ContractApprovalStep.contract_record_id, ContractApprovalStep.step_order))).all())
    current_steps: dict[int, ContractApprovalStep] = {}
    for step in steps:
        current_steps.setdefault(step.contract_record_id, step)
    return {
        "customers_by_id": customers_by_id,
        "customers_by_no": customers_by_no,
        "customers_by_name": customers_by_name,
        "current_steps": current_steps,
    }


RECORD_PERSON_FIELDS_BY_MODULE: dict[str, tuple[str, ...]] = {
    "case": (
        "source_person", "customer_manager", "hearing_lawyer", "assistant", "assistant_username",
        "handler", "case_manager", "case_officer", "initiator", "submitted_by", "created_by", "updated_by",
        "investigator_username", "archive_submitter", "archive_internal_reviewer", "archive_reviewer",
    ),
    "seal": (
        "applicant", "requester", "submitted_by", "approver", "stamped_by", "archived_by", "created_by", "updated_by",
    ),
    "finance": (
        "applicant", "requester", "submitted_by", "approver", "payer", "claimant", "operator", "created_by", "updated_by",
    ),
    "hr": (
        "username", "created_by", "updated_by", "resigned_by", "login_status_updated_by", "contract_approval_updated_by",
    ),
    "warehouse": (
        "borrower", "borrowed_by", "return_requested_by", "returned_by", "checked_in_by", "checked_out_by",
        "recipient", "rechecked_in_by", "destroyed_by", "scrapped_by", "created_by", "updated_by",
    ),
    "document": (
        "handler", "register_operator", "signer", "archived_by", "submitted_by", "created_by", "updated_by",
    ),
}

RECORD_PERSON_LIST_FIELDS_BY_MODULE: dict[str, tuple[str, ...]] = {
    "case": ("handling_usernames", "handling_lawyers", "handling_lawyer_usernames", "assistant_usernames", "assistants", "case_team_usernames", "collaborators"),
    "seal": ("approvers",),
    "finance": ("approvers",),
    "document": ("recipients",),
}


def _record_person_usernames(record: BusinessRecord) -> set[str]:
    data = record.data or {}
    usernames = {str(record.owner or "").strip()}
    for key in RECORD_PERSON_FIELDS_BY_MODULE.get(record.module, ()):
        value = str(data.get(key) or "").strip()
        if value:
            if record.module == "case" and key == "assistant_username":
                usernames.update(_contract_person_values(value))
            else:
                usernames.add(value)
    for key in RECORD_PERSON_LIST_FIELDS_BY_MODULE.get(record.module, ()):
        usernames.update(_contract_person_values(data.get(key)))
    if record.module == "case":
        hearing_username = str(data.get("hearing_lawyer_username") or "").strip()
        if hearing_username:
            usernames.add(hearing_username)
    # `Legal_Case_Participant` is a real case membership relation from the
    # legacy database.  It is separate from the case's role fields and must
    # participate in both display-name resolution and case visibility.
    if record.module == "case":
        for participant in data.get("legacy_participants") or []:
            if isinstance(participant, dict):
                username = str(participant.get("staff_name") or "").strip()
                if username:
                    usernames.add(username)
    return {value for value in usernames if value}


def _case_assistant_display(data: dict, users_by_username: dict[str, User]) -> tuple[str, bool]:
    legacy = data.get("legacy_record") if isinstance(data.get("legacy_record"), dict) else {}
    usernames = _contract_person_values(
        data.get("assistant_usernames") or data.get("assistant_username") or legacy.get("CaseAssistant")
    )
    stored_names = _contract_person_values(
        data.get("assistants") or data.get("assistant") or legacy.get("CaseAssistantName")
    )
    if not usernames and not stored_names:
        return "—", False
    username = usernames[0] if usernames else ""
    stored_name = stored_names[0] if stored_names else ""
    label = ""
    unresolved = False
    if username:
        label, unresolved = _person_reference_display(username, users_by_username)
    elif stored_name:
        label, unresolved = _person_reference_display(stored_name, users_by_username)
    if (not label or unresolved) and stored_name and stored_name != PERSON_NAME_PLACEHOLDER:
        label = stored_name
        unresolved = False
    if not label or label == PERSON_NAME_PLACEHOLDER:
        return CONTRACT_PERSON_NAME_PLACEHOLDER, True
    return label, unresolved


def _apply_record_person_displays(
    result: dict,
    record: BusinessRecord,
    users_by_username: dict[str, User],
) -> dict:
    if record.module not in RECORD_PERSON_FIELDS_BY_MODULE:
        return result
    result["owner_display_name"], result["owner_display_name_missing"] = _person_reference_display(record.owner, users_by_username)
    data = result.get("data") or {}
    for key in RECORD_PERSON_FIELDS_BY_MODULE[record.module]:
        if key not in data:
            continue
        reference = data.get(key)
        if record.module == "case" and key == "hearing_lawyer":
            reference = data.get("hearing_lawyer_username") or reference
        if record.module == "case" and key in {"assistant", "assistant_username"}:
            display_name, missing = _case_assistant_display(data, users_by_username)
        else:
            display_name, missing = _person_reference_display(reference, users_by_username)
        data[f"{key}_display_name"] = display_name
        data[f"{key}_display_name_missing"] = missing
    for key in RECORD_PERSON_LIST_FIELDS_BY_MODULE.get(record.module, ()):
        if key not in data:
            continue
        values = _contract_person_values(data.get(key))
        labels = [_person_reference_display(value, users_by_username)[0] for value in values]
        data[f"{key}_display_names"] = labels
        data[f"{key}_display_name"] = "、".join(labels)
    if record.module == "case" and isinstance(data.get("legacy_participants"), list):
        displayed_participants: list[dict] = []
        participant_names: list[str] = []
        participant_usernames: list[str] = []
        seen_usernames: set[str] = set()
        for raw_participant in data["legacy_participants"]:
            if not isinstance(raw_participant, dict):
                continue
            username = str(raw_participant.get("staff_name") or "").strip()
            if not username or username.lower() in seen_usernames:
                continue
            seen_usernames.add(username.lower())
            display_name, missing = _person_reference_display(username, users_by_username)
            displayed_participants.append({
                **raw_participant,
                "display_name": display_name,
                "display_name_missing": missing,
            })
            participant_usernames.append(username)
            participant_names.append(display_name)
        data["legacy_participants"] = displayed_participants
        data["legacy_participant_usernames"] = participant_usernames
        data["legacy_participant_display_names"] = participant_names
        data["legacy_participant_display_name"] = "、".join(participant_names)
    result["data"] = data
    return result


async def _contract_customer_record_dict(
    record: BusinessRecord,
    allowed_fields: set[str] | None,
    db: AsyncSession,
    *,
    investigations_by_id: dict[int, BusinessRecord] | None = None,
    names_by_username: dict[str, str] | None = None,
    users_by_username: dict[str, User] | None = None,
    contract_context: dict | None = None,
    identity: dict | None = None,
) -> dict:
    result = _record_dict(record, allowed_fields)
    if record.module not in {"case", "contract", "customer", "investigation", "task", "clue", "notary", "evidence"}:
        return result
    data = result["data"]
    if record.module == "case":
        phase_changed_date = _case_phase_changed_date(record)
        phase_changed_days = _case_phase_changed_days(record)
        data["phase_changed_at"] = phase_changed_date.isoformat()
        data["phase_changed_days"] = phase_changed_days
        data["phase_duration"] = f"{phase_changed_days}天"
    if record.module == "contract":
        context = contract_context or await _contract_customer_projection_context([record], db)
        customer, relation_status = _customer_reference_from_maps(
            record.customer,
            record.data or {},
            context["customers_by_id"],
            context["customers_by_no"],
            context["customers_by_name"],
        )
        current_step = context["current_steps"].get(record.id)
        current_approver = current_step.approver if current_step else ""
        if customer:
            customer_data = customer.data or {}
            data["customer_id"] = customer.id
            data["customer_record_id"] = customer.id
            data["customer_no"] = customer.serial_no
            data["customer_name"] = customer.title
            # A contract may contain an old creation-time manager snapshot.  The
            # current linked customer is authoritative for list/detail display.
            data["customer_managers"] = _contract_customer_manager_values(record, customer)
            data.pop("customer_manager_display_names", None)
            data.pop("customer_manager_display_name", None)
        data["customer_relation_status"] = relation_status
        data["signed_at"] = str(
            data.get("signed_at") or data.get("signed_date") or data.get("sign_date") or data.get("contract_date") or ""
        )
        data["current_approver"] = current_approver
        result.update({
            "customer_id": customer.id if customer else None,
            "customer_no": customer.serial_no if customer else str(data.get("customer_no") or ""),
            "customer_name": customer.title if customer else record.customer,
            "signed_at": data["signed_at"],
            "current_approver": current_approver,
        })
        can_approve_current = bool(
            identity
            and record.status == "审批中"
            and current_step
            and await _can_act_on_contract_approval_step(
                current_step,
                identity,
                CONTRACT_APPROVAL_ACTION_CODE,
                db,
            )
        )
        approval_capabilities = {
            "can_approve_current": can_approve_current,
            "current_approver": current_approver,
        }
        data["approval_capabilities"] = approval_capabilities
        result["approval_capabilities"] = approval_capabilities
    if record.module == "task" and data.get("investigation_record_id"):
        try:
            investigation_id = int(data.get("investigation_record_id") or 0)
        except (TypeError, ValueError):
            investigation_id = 0
        investigation = (
            investigations_by_id.get(investigation_id)
            if investigations_by_id is not None
            else await db.get(BusinessRecord, investigation_id) if investigation_id else None
        )
        if investigation and investigation.module == "investigation":
            investigation_data = investigation.data or {}
            for key in ("right_type", "region", "authorized_from", "authorized_to", "source_owner", "assigner", "assigned_by"):
                if not data.get(key) and investigation_data.get(key):
                    data[key] = investigation_data[key]
            data.setdefault("investigation_no", investigation.serial_no)
    usernames = [record.owner]
    for key in ("source_person", "customer_source", "submitted_by", "current_approver", "customer_manager", "reviewer", "customer_reviewer", "investigator", "investigation_assistant", "handler", "source_owner", "assigner", "assigned_by"):
        usernames.extend(_contract_person_values(data.get(key)))
    usernames.extend(_contract_person_values(data.get("customer_managers")))
    usernames.extend(_contract_person_values(data.get("contact_accounts") or data.get("contact")))
    usernames.extend(_record_person_usernames(record))
    if names_by_username is None:
        normalized_usernames = list(dict.fromkeys(value.lower() for value in usernames if value))
        users = list((await db.scalars(select(User).where(func.lower(User.username).in_(normalized_usernames)))).all()) if normalized_usernames else []
        names_by_username = {user.username.lower(): user.display_name for user in users}
    result["owner_display_name"] = _contract_person_display_name(record.owner, names_by_username)
    for key in ("source_person", "customer_source", "submitted_by", "current_approver", "investigator", "investigation_assistant", "handler", "source_owner", "assigner", "assigned_by"):
        if key in data:
            data[f"{key}_display_name"] = _contract_person_display_name(data.get(key), names_by_username)
    managers = _contract_person_values(data.get("customer_managers") or data.get("customer_manager"))
    if managers:
        manager_names = [_contract_person_display_name(value, names_by_username) for value in managers]
        data["customer_manager_display_names"] = manager_names
        data["customer_manager_display_name"] = "、".join(manager_names)
    contact_accounts = _contract_person_values(data.get("contact_accounts") or data.get("contact"))
    if contact_accounts:
        contact_names = [_contract_person_display_name(value, names_by_username) for value in contact_accounts]
        data["contact_account_display_names"] = contact_names
        data["contact_account_display_name"] = "、".join(contact_names)
    if record.module in {"investigation", "task", "clue", "notary", "evidence"}:
        people = _contract_person_values(data.get("customer_managers") or data.get("customer_manager"))
        manager_label = ""
        if people:
            # Usernames remain the authorization keys; UI receives display labels.
            manager_label = "、".join(str(names_by_username.get(value.lower()) or value) for value in people)
            data["customer_manager_display_name"] = manager_label
            data["customer_manager"] = manager_label
        for key in ("reviewer", "customer_reviewer"):
            value = str(data.get(key) or "").strip()
            if value:
                label = str(names_by_username.get(value.lower()) or value)
                data[f"{key}_display_name"] = label
                data[key] = label
        reviewer_label = str(data.get("customer_reviewer_display_name") or data.get("reviewer_display_name") or "")
        if record.module == "clue" and manager_label and reviewer_label:
            data["customer_manager"] = f"{manager_label}（审核人：{reviewer_label}）"
    if record.module in RECORD_PERSON_FIELDS_BY_MODULE:
        if users_by_username is None:
            users_by_username = await _user_display_map(_record_person_usernames(record), db)
        _apply_record_person_displays(result, record, users_by_username)
    return result


async def _contract_customer_record_dicts(
    records: list[BusinessRecord], allowed_fields: set[str] | None, db: AsyncSession,
    identity: dict | None = None,
) -> list[dict]:
    investigation_ids: set[int] = set()
    for record in records:
        if record.module != "task":
            continue
        try:
            investigation_id = int((record.data or {}).get("investigation_record_id") or 0)
        except (TypeError, ValueError):
            investigation_id = 0
        if investigation_id:
            investigation_ids.add(investigation_id)
    investigations = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "investigation", BusinessRecord.id.in_(investigation_ids),
    ))).all()) if investigation_ids else []
    investigations_by_id = {item.id: item for item in investigations}

    contract_context = await _contract_customer_projection_context(records, db)
    usernames: set[str] = set()
    person_keys = (
        "source_person", "customer_source", "submitted_by", "current_approver", "customer_manager",
        "reviewer", "customer_reviewer", "investigator", "investigation_assistant", "handler", "source_owner", "assigner", "assigned_by",
    )
    for record in records:
        usernames.add(str(record.owner or "").lower())
        data = record.data or {}
        investigation = investigations_by_id.get(int(data.get("investigation_record_id") or 0)) if record.module == "task" and str(data.get("investigation_record_id") or "").isdigit() else None
        inherited_data = investigation.data or {} if investigation else {}
        for key in person_keys:
            usernames.update(value.lower() for value in _contract_person_values(data.get(key) or inherited_data.get(key)))
        usernames.update(value.lower() for value in _contract_person_values(data.get("customer_managers")))
        usernames.update(value.lower() for value in _contract_person_values(data.get("contact_accounts") or data.get("contact")))
        usernames.update(value.lower() for value in _record_person_usernames(record))
        if record.module == "contract":
            customer, _ = _customer_reference_from_maps(
                record.customer,
                data,
                contract_context["customers_by_id"],
                contract_context["customers_by_no"],
                contract_context["customers_by_name"],
            )
            usernames.update(
                value.lower()
                for value in _contract_customer_manager_values(record, customer)
            )
    usernames.discard("")
    users = list((await db.scalars(select(User).where(func.lower(User.username).in_(usernames)))).all()) if usernames else []
    names_by_username = {user.username.lower(): user.display_name for user in users}
    users_by_username = {user.username.lower(): user for user in users}
    results = [
        await _contract_customer_record_dict(
            record, allowed_fields, db,
            investigations_by_id=investigations_by_id,
            names_by_username=names_by_username,
            users_by_username=users_by_username,
            contract_context=contract_context,
            identity=identity,
        )
        for record in records
    ]
    return results


def _receivable_dict(plan: ReceivablePlan, contract: BusinessRecord, users_by_username: dict[str, User] | None = None) -> dict:
    remaining = max(plan.amount - plan.received_amount, 0)
    effective_status = plan.status
    if remaining > 0 and plan.due_date < date.today() and plan.status != "已收款":
        effective_status = "已逾期"
    return {
        "id": plan.id, "contract_record_id": plan.contract_record_id,
        "contract_no": contract.serial_no, "contract_title": contract.title,
        "customer": contract.customer, "phase": plan.phase, "due_date": plan.due_date,
        "amount": plan.amount, "received_amount": plan.received_amount,
        "remaining_amount": remaining, "status": effective_status,
        "payer": plan.payer, "owner": contract.owner,
        "owner_display_name": _person_reference_display(contract.owner, users_by_username or {})[0], "remark": plan.remark,
        "updated_at": plan.updated_at,
    }


_OFFICIAL_RECEIVABLE_FEE_WORDS = (
    "官方", "官费", "差旅费", "诉讼费", "公证费", "调解金额", "判决金额",
    "保全费", "公告费", "担保费", "鉴定费", "执行费", "公证服务费",
)
_INVALID_RECEIVABLE_FEE_STATUSES = {"已驳回", "已拒绝", "已作废"}


def _receivable_number(value: object) -> float:
    try:
        return round(float(value or 0), 2)
    except (TypeError, ValueError):
        return 0.0


def _receivable_relation_id(data: dict, *keys: str) -> int:
    for key in keys:
        try:
            value = int(data.get(key) or 0)
        except (TypeError, ValueError):
            value = 0
        if value:
            return value
    return 0


def _receivable_fee_category(value: object) -> str:
    label = str(value or "").strip()
    return "official" if any(word in label for word in _OFFICIAL_RECEIVABLE_FEE_WORDS) else "agency"


async def _receivable_detail_projection(
    identity: dict, db: AsyncSession, records: list[BusinessRecord] | None = None,
) -> list[dict]:
    """Project the legacy contract-object receivable detail from visible data."""
    if records is None:
        records = list((await db.scalars(select(BusinessRecord).where(
            *(await _record_scope_conditions(identity, db)),
        ))).all())

    contracts = [item for item in records if item.module == "contract"]
    cases = [item for item in records if item.module == "case"]
    finances = [item for item in records if item.module == "finance"]
    contracts_by_id = {item.id: item for item in contracts}
    contracts_by_no = {item.serial_no: item for item in contracts if item.serial_no}
    cases_by_id = {item.id: item for item in cases}
    cases_by_no = {item.serial_no: item for item in cases if item.serial_no}

    objects = list((await db.scalars(select(ContractObject).where(
        ContractObject.contract_record_id.in_(set(contracts_by_id)),
        ContractObject.case_record_id.in_(set(cases_by_id)),
    ).order_by(ContractObject.contract_record_id, ContractObject.case_record_id, ContractObject.id))).all()) if contracts_by_id and cases_by_id else []

    # A case/contract owner is allowed to see the receivable even when the
    # linked finance record is operated by a cashier.  The ordinary record
    # scope filters that finance row out, so resolve only finance records that
    # are explicitly linked to the already-visible contract/case/object set.
    relation_conditions = []
    contract_ids = set(contracts_by_id)
    case_ids = set(cases_by_id)
    object_ids = {item.id for item in objects}
    contract_nos = set(contracts_by_no)
    case_nos = set(cases_by_no)
    for key, values in (
        ("contract_object_id", object_ids),
        ("contract_id", contract_ids),
        ("contract_record_id", contract_ids),
        ("case_id", case_ids),
        ("case_record_id", case_ids),
    ):
        if values:
            relation_conditions.append(BusinessRecord.data[key].as_integer().in_(values))
            relation_conditions.append(BusinessRecord.data[key].as_string().in_({str(value) for value in values}))
    if contract_nos:
        relation_conditions.append(BusinessRecord.data["contract_no"].as_string().in_(contract_nos))
    if case_nos:
        relation_conditions.append(BusinessRecord.data["case_no"].as_string().in_(case_nos))
    if relation_conditions:
        related_finances = list((await db.scalars(select(BusinessRecord).where(
            BusinessRecord.module == "finance", or_(*relation_conditions),
        ))).all())
        finances = list({item.id: item for item in [*finances, *related_finances]}.values())

    finance_ids = {item.id for item in finances}
    finance_rows = await _invoice_case_fee_rows(
        identity, db, scope="company", ids=finance_ids, include_all_fee_types=True,
        scope_authorized_fee_ids=finance_ids,
        force_amount_projection=True,
    ) if finance_ids else []
    finance_data_by_id = {
        int(item["id"]): dict(item.get("data") or {}) for item in finance_rows
    }
    rows: list[dict] = []

    def relation(fee_data: dict) -> tuple[BusinessRecord | None, BusinessRecord | None]:
        case_record = cases_by_id.get(_receivable_relation_id(fee_data, "case_id", "case_record_id"))
        if case_record is None:
            case_record = cases_by_no.get(str(fee_data.get("case_no") or "").strip())
        contract = contracts_by_id.get(_receivable_relation_id(fee_data, "contract_id", "contract_record_id"))
        if contract is None:
            contract = contracts_by_no.get(str(fee_data.get("contract_no") or "").strip())
        if contract is None and case_record is not None:
            case_data = case_record.data or {}
            contract = contracts_by_id.get(_receivable_relation_id(case_data, "contract_id", "contract_record_id"))
            if contract is None:
                contract = contracts_by_no.get(str(case_data.get("contract_no") or "").strip())
        return contract, case_record

    matched_fee_ids: set[int] = set()
    for item in objects:
        contract = contracts_by_id[item.contract_record_id]
        case_record = cases_by_id[item.case_record_id]
        amount = _receivable_number(item.amount)
        if amount <= 0:
            continue
        linked_fees = [
            fee for fee in finances if _fee_matches_contract_object(fee, item, case_record)
        ]
        matched_fee_ids.update(fee.id for fee in linked_fees)
        paid = 0.0
        received = 0.0
        for fee in linked_fees:
            raw = fee.data or {}
            projected = finance_data_by_id.get(fee.id, {})
            paid += max(
                _receivable_number(projected.get("paid_amount")),
                _receivable_number(raw.get("paid_amount")),
            )
            received += max(
                _receivable_number(projected.get("cashed_amount")),
                _receivable_number(raw.get("cashed_amount")),
                _receivable_number(raw.get("received_amount")),
            )
        paid = min(_receivable_number(paid), amount)
        received = min(_receivable_number(received), amount)
        remaining = max(round(amount - received, 2), 0)
        case_data = case_record.data or {}
        contract_data = contract.data or {}
        rows.append({
            "id": f"object:{item.id}", "source_type": "contract_object",
            "contract_object_id": item.id, "fee_record_id": None,
            "contract_record_id": contract.id, "contract_no": contract.serial_no,
            "contract_title": contract.title,
            "contract_body": str(contract_data.get("contract_body") or "律所"),
            "contract_date": str(contract_data.get("signed_at") or "")[:10],
            "customer": contract.customer, "owner": contract.owner,
            "source_person": str(contract_data.get("source_person") or contract.owner),
            "case_record_id": case_record.id, "case_no": case_record.serial_no,
            "case_stage": str(case_data.get("case_stage") or case_data.get("business_stage") or case_record.status),
            "case_type": str(case_data.get("case_type") or ""),
            "phase": str(case_data.get("case_stage") or case_data.get("business_stage") or case_record.status),
            "fee_type": item.fee_type, "fee_category": _receivable_fee_category(item.fee_type),
            "due_date": "", "amount": amount, "paid_amount": paid,
            "received_amount": received, "remaining_amount": remaining,
            "status": case_record.status, "payer": contract.customer,
            "remark": item.remark, "updated_at": item.updated_at,
        })

    # Historical rows may predate contract-object migration. Keep only
    # unmatched, contract-resolvable fees so the contract-centric page remains
    # usable without duplicating modern object-backed rows.
    for fee in finances:
        if fee.id in matched_fee_ids:
            continue
        data = fee.data or {}
        if fee.status in _INVALID_RECEIVABLE_FEE_STATUSES:
            continue
        projected = finance_data_by_id.get(fee.id, {})
        fee_type = str(projected.get("fee_type") or data.get("fee_type") or fee.title or "案件费用").strip()
        fee_category = _receivable_fee_category(fee_type)
        contract, case_record = relation(data)
        if contract is None:
            continue
        amount = _receivable_number(data.get("amount"))
        paid = max(
            _receivable_number(projected.get("paid_amount")),
            _receivable_number(data.get("paid_amount")),
        )
        received = max(
            _receivable_number(projected.get("cashed_amount")),
            _receivable_number(data.get("cashed_amount")),
            _receivable_number(data.get("received_amount")),
        )
        paid = min(paid, amount)
        received = min(received, amount)
        remaining = max(round(amount - received, 2), 0)
        if amount <= 0:
            continue
        case_data = case_record.data or {} if case_record else {}
        contract_data = contract.data or {} if contract else {}
        rows.append({
            "id": f"fee:{fee.id}", "source_type": "case_fee",
            "contract_object_id": None, "fee_record_id": fee.id,
            "contract_record_id": contract.id,
            "contract_no": contract.serial_no,
            "contract_title": contract.title,
            "contract_body": str(contract_data.get("contract_body") or "律所"),
            "contract_date": str(contract_data.get("signed_at") or "")[:10],
            "customer": contract.customer,
            "owner": contract.owner,
            "source_person": str(contract_data.get("source_person") or contract.owner),
            "case_record_id": case_record.id if case_record else None,
            "case_no": case_record.serial_no if case_record else str(data.get("case_no") or ""),
            "case_stage": str(case_data.get("case_stage") or case_data.get("business_stage") or (case_record.status if case_record else "案件费用")),
            "case_type": str(case_data.get("case_type") or ""),
            "phase": str(case_data.get("case_stage") or case_data.get("business_stage") or (case_record.status if case_record else "案件费用")),
            "fee_type": fee_type, "fee_category": fee_category,
            "due_date": str(data.get("deadline") or ""), "amount": amount,
            "paid_amount": paid,
            "received_amount": received, "remaining_amount": remaining,
            "status": fee.status, "payer": fee.customer, "remark": fee.description,
            "updated_at": fee.updated_at,
        })

    aggregates: dict[int, dict[str, float]] = {}
    for row in rows:
        totals = aggregates.setdefault(row["contract_record_id"], {
            "official_paid": 0.0, "official_received": 0.0, "official_unreceived": 0.0,
            "official_loss": 0.0, "agency_total": 0.0, "agency_received": 0.0, "agency_due": 0.0,
        })
        if row["fee_category"] == "official":
            totals["official_paid"] += row["paid_amount"]
            totals["official_received"] += row["received_amount"]
            totals["official_unreceived"] += row["remaining_amount"]
            if "亏损" in row["phase"]:
                totals["official_loss"] += row["remaining_amount"]
        else:
            totals["agency_total"] += row["amount"]
            totals["agency_received"] += row["received_amount"]
            totals["agency_due"] += row["remaining_amount"]
    for row in rows:
        row["contract_totals"] = {key: round(value, 2) for key, value in aggregates[row["contract_record_id"]].items()}
    return sorted(rows, key=lambda row: (row["contract_no"] or "~", row["case_no"] or "~", str(row["id"])))


def _hearing_dict(item: HearingSchedule, case_record: BusinessRecord) -> dict:
    return {
        "id": item.id, "case_record_id": item.case_record_id,
        "case_no": case_record.serial_no, "case_title": case_record.title,
        "customer": case_record.customer, "hearing_date": item.hearing_date,
        "weekday": "星期" + "一二三四五六日"[item.hearing_date.weekday()],
        "hearing_time": item.hearing_time, "court": item.court, "courtroom": item.courtroom,
        "hearing_type": item.hearing_type, "hearing_lawyer": item.hearing_lawyer,
        "status": item.status, "remark": item.remark,
    }


_CASE_HEARING_LEVELS = (
    ("retrial", "再审开庭"),
    ("execution", "执行开庭"),
    ("second", "二审开庭"),
    ("first", "一审开庭"),
)


def _case_hearing_datetime(value: object, fallback_time: object = "") -> datetime | None:
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime.combine(value, datetime.min.time())
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        try:
            parsed = datetime.combine(date.fromisoformat(text[:10]), datetime.min.time())
        except ValueError:
            return None
    if parsed.time() == datetime.min.time():
        time_text = str(fallback_time or "").strip()
        if time_text:
            try:
                parsed = datetime.combine(parsed.date(), datetime.strptime(time_text[:8], "%H:%M:%S").time())
            except ValueError:
                try:
                    parsed = datetime.combine(parsed.date(), datetime.strptime(time_text[:5], "%H:%M").time())
                except ValueError:
                    pass
    return parsed


def _dashboard_case_hearing(case_record: BusinessRecord, today: date, cutoff: date) -> dict | None:
    """Project the legacy case court fields into the dashboard schedule."""
    data = case_record.data or {}
    candidates: list[tuple[str, str, object, object]] = [
        (prefix, hearing_type, data.get(f"{prefix}_court_hearing_date"), "")
        for prefix, hearing_type in _CASE_HEARING_LEVELS
    ]
    candidates.extend((
        ("generic", "开庭", data.get("hearing_date"), data.get("hearing_time")),
        ("generic", "开庭", data.get("next_hearing_date"), data.get("next_hearing_time")),
    ))
    for prefix, hearing_type, raw_date, fallback_time in candidates:
        hearing_at = _case_hearing_datetime(raw_date, fallback_time)
        if hearing_at is None or not today <= hearing_at.date() <= cutoff:
            continue
        if prefix == "first":
            court = data.get("first_court_name") or data.get("first_instance_court") or data.get("court")
            courtroom = data.get("first_court_courtroom") or data.get("courtroom")
        elif prefix == "second":
            court = data.get("second_court_name") or data.get("second_instance_court")
            courtroom = data.get("second_court_courtroom")
        elif prefix in {"execution", "retrial"}:
            court = data.get(f"{prefix}_court_name")
            courtroom = data.get(f"{prefix}_court_courtroom")
        else:
            court = data.get("court") or data.get("first_court_name") or data.get("first_instance_court")
            courtroom = data.get("courtroom") or data.get("first_court_courtroom")
        return {
            "case_record_id": case_record.id,
            "case_no": case_record.serial_no,
            "client": case_record.customer,
            "weekday": "星期" + "一二三四五六日"[hearing_at.weekday()],
            "date": str(hearing_at.date()),
            "time": hearing_at.strftime("%H:%M"),
            "court": str(court or ""),
            "lawyer": str(data.get("hearing_lawyer") or ""),
            "agent": ",".join(data.get("handling_lawyers", [])),
            "assistant": str(data.get("assistant") or ""),
            "hearing_type": hearing_type,
            "courtroom": str(courtroom or ""),
        }
    return None


def _task_creation_mode(data: dict) -> str:
    """Return the user-facing creation mode without conflating it with task origin."""
    explicit_mode = str(data.get("creation_mode") or "").strip()
    if explicit_mode in {"自动", "人工"}:
        return explicit_mode
    task_type = str(data.get("task_type") or "").strip()
    source = str(data.get("source") or "").strip()
    if task_type in {"固定任务", "自动任务"} or data.get("auto_task_type") or source in {"自动", "自动任务"}:
        return "自动"
    return "人工"


def _task_dict(record: BusinessRecord) -> dict:
    data = record.data or {}
    raw_case_nos = data.get("case_nos") if isinstance(data.get("case_nos"), list) else []
    case_nos = [str(value).strip() for value in raw_case_nos if str(value).strip()]
    primary_case_no = str(data.get("case_no") or "").strip()
    if primary_case_no and primary_case_no not in case_nos:
        case_nos.insert(0, primary_case_no)
    raw_case_ids = data.get("case_ids") if isinstance(data.get("case_ids"), list) else []
    case_ids = []
    for value in raw_case_ids:
        try:
            normalized_id = int(value)
        except (TypeError, ValueError):
            continue
        if normalized_id > 0 and normalized_id not in case_ids:
            case_ids.append(normalized_id)
    try:
        # Imported legacy tasks used TaskEndTime/task_end_time; new writes use
        # deadline. Keep one response field while preserving both sources.
        raw_deadline = data.get("deadline") or data.get("task_end_time") or data.get("TaskEndTime") or ""
        deadline = date.fromisoformat(str(raw_deadline))
        days_remaining = (deadline - date.today()).days
    except ValueError:
        deadline = None
        days_remaining = None
    workflow_status = record.status
    # 兼容早期本地数据：旧“待确认”等同于原系统“进行中-已完成”。
    effective_status = "已完成" if record.status == "待确认" else record.status
    if record.status == "处理中" and str(data.get("source") or "").strip() == "案件任务":
        effective_status = "进行中"
    if days_remaining is not None and days_remaining < 0 and record.status in {"待接收", "待处理", "处理中"}:
        effective_status = "已逾期"
    reminder_due = days_remaining in {1, 3} or (days_remaining is not None and days_remaining < 0 and abs(days_remaining) % 3 == 0)
    reminder_text = ""
    if days_remaining in {1, 3}:
        reminder_text = f"{days_remaining} 天后到期"
    elif days_remaining is not None and days_remaining < 0:
        reminder_text = f"已逾期 {abs(days_remaining)} 天" + ("，今日提醒" if reminder_due else "")
    elif days_remaining == 0:
        reminder_text = "今日到期"
    return {
        **_record_dict(record), "status": effective_status, "workflow_status": workflow_status,
        "deadline": deadline, "days_remaining": days_remaining,
        "priority": data.get("priority", "普通"), "source": data.get("source", "日常任务"),
        "creation_mode": _task_creation_mode(data), "task_type": data.get("task_type", ""),
        "initiator": data.get("initiator", ""), "collaborators": data.get("collaborators", []),
        "case_no": primary_case_no, "case_nos": case_nos, "case_ids": case_ids,
        "case_record_id": data.get("case_record_id") or data.get("case_id"),
        "case_module": data.get("case_module", "case" if primary_case_no else ""),
        "start_at": data.get("start_at") or data.get("task_begin_time") or data.get("TaskBeginTime") or "",
        "end_at": data.get("end_at") or data.get("task_end_time") or data.get("TaskEndTime") or "",
        "rejected_reason": data.get("rejected_reason", ""),
        "plaintiff": data.get("plaintiff", ""), "defendant": data.get("defendant", ""),
        "case_stage": data.get("case_stage", ""),
        "accepted_at": data.get("accepted_at", ""),
        "verified_at": data.get("confirmed_at") or data.get("auto_confirmed_at", ""),
        "completion_auto_confirm_at": data.get("completion_auto_confirm_at", ""),
        "reminder_due": reminder_due, "reminder_text": reminder_text,
        "handoff_recipient": data.get("handoff_recipient", ""),
        "handoff_auto_complete_at": data.get("handoff_auto_complete_at", ""),
        "handoff_restarted": bool(data.get("handoff_restarted")),
        "auto_completed": bool(data.get("auto_completed")),
        "performance_impact": data.get("performance_impact", {}),
        "exception_request": data.get("exception_request", {}),
        "parent_task_id": data.get("parent_task_id"),
        "parent_task_no": data.get("parent_task_no", ""),
        "investigation_record_id": data.get("investigation_record_id"),
        "investigation_no": data.get("investigation_no", ""),
        "investigation_module": data.get("investigation_module", ""),
        "contract_no": data.get("contract_no", ""),
        "contract_name": data.get("contract_name", ""),
        "authorization_scope": data.get("authorization_scope", ""),
        "attachment_ids": data.get("attachment_ids", []),
    }


def _task_display_with_users(record: BusinessRecord, users_by_username: dict[str, User]) -> dict:
    result = _task_dict(record)
    data = result.get("data") or {}
    result["owner_display_name"], result["owner_display_name_missing"] = _person_reference_display(record.owner, users_by_username)
    for key in ("initiator", "source_owner", "assigner", "reviewer", "customer_reviewer"):
        if key in data:
            display_name, display_missing = _person_reference_display(data.get(key), users_by_username)
            result[f"{key}_display_name"] = display_name
            result[f"{key}_display_name_missing"] = display_missing
    if data.get("customer_manager") is not None:
        manager_values = _contract_person_values(data.get("customer_manager"))
        manager_names = [_person_reference_display(value, users_by_username)[0] for value in manager_values]
        if manager_names:
            result["customer_manager_display_name"] = "、".join(manager_names)
    collaborator_values = _contract_person_values(data.get("collaborators"))
    result["collaborator_display_names"] = [
        _person_reference_display(value, users_by_username)[0] for value in collaborator_values
    ]
    result["collaborators_display_names"] = result["collaborator_display_names"]
    return result


async def _task_display_dicts(records: list[BusinessRecord], db: AsyncSession) -> list[dict]:
    usernames: set[str] = set()
    case_ids: set[int] = set()
    case_nos: set[str] = set()
    for record in records:
        usernames.add(record.owner)
        data = record.data or {}
        raw_ids = data.get("case_ids") if isinstance(data.get("case_ids"), list) else []
        raw_ids = [data.get("case_record_id") or data.get("case_id"), *raw_ids]
        for raw_case_id in raw_ids:
            try:
                if raw_case_id:
                    case_ids.add(int(raw_case_id))
            except (TypeError, ValueError):
                pass
        raw_nos = data.get("case_nos") if isinstance(data.get("case_nos"), list) else []
        for raw_case_no in [data.get("case_no"), *raw_nos]:
            case_no = str(raw_case_no or "").strip()
            if case_no:
                case_nos.add(case_no)
        for key in ("initiator", "source_owner", "assigner", "reviewer", "customer_reviewer", "customer_manager", "collaborators"):
            usernames.update(_contract_person_values(data.get(key)))
    users_by_username = await _user_display_map(usernames, db)
    employees = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "hr",
        BusinessRecord.status.not_in({"离职", "停用"}),
    ))).all())
    employee_names = {
        str((employee.data or {}).get("username") or employee.owner or "").strip().lower(): str(employee.title or "").strip()
        for employee in employees
        if str((employee.data or {}).get("username") or employee.owner or "").strip()
    }
    case_conditions = []
    if case_ids:
        case_conditions.append(BusinessRecord.id.in_(case_ids))
    if case_nos:
        case_conditions.append(BusinessRecord.serial_no.in_(case_nos))
    linked_cases = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module.in_({"case", "ipr_case"}), or_(*case_conditions),
    ))).all()) if case_conditions else []
    cases_by_id = {item.id: item for item in linked_cases}
    cases_by_no = {item.serial_no: item for item in linked_cases}

    results: list[dict] = []
    for record in records:
        result = _task_display_with_users(record, users_by_username)
        employee_name = employee_names.get(str(record.owner or "").strip().lower())
        if employee_name:
            result["owner_display_name"] = employee_name
            result["owner_display_name_missing"] = False
        data = record.data or {}
        linked_case_rows: list[BusinessRecord] = []
        raw_ids = data.get("case_ids") if isinstance(data.get("case_ids"), list) else []
        raw_ids = [data.get("case_record_id") or data.get("case_id"), *raw_ids]
        for raw_case_id in raw_ids:
            try:
                linked_case = cases_by_id.get(int(raw_case_id)) if raw_case_id else None
            except (TypeError, ValueError):
                linked_case = None
            if linked_case and linked_case not in linked_case_rows:
                linked_case_rows.append(linked_case)
        raw_nos = data.get("case_nos") if isinstance(data.get("case_nos"), list) else []
        for raw_case_no in [data.get("case_no"), *raw_nos]:
            linked_case = cases_by_no.get(str(raw_case_no or "").strip())
            if linked_case and linked_case not in linked_case_rows:
                linked_case_rows.append(linked_case)
        linked_case = linked_case_rows[0] if linked_case_rows else None
        if linked_case:
            case_data = linked_case.data or {}
            result["case_no"] = linked_case.serial_no
            result["plaintiff"] = "、".join(_case_party_values(case_data, CASE_PLAINTIFF_FIELDS)) or result["plaintiff"] or linked_case.customer
            result["defendant"] = "、".join(_case_party_values(case_data, CASE_DEFENDANT_FIELDS)) or result["defendant"]
            result["case_stage"] = str(case_data.get("case_stage") or linked_case.status or result["case_stage"])
        result["cases"] = [
            {"id": item.id, "case_no": item.serial_no, "title": item.title, "customer": item.customer, "status": item.status}
            for item in linked_case_rows
        ]
        result["case_ids"] = [item.id for item in linked_case_rows]
        result["case_nos"] = [item.serial_no for item in linked_case_rows]
        result["case_module"] = linked_case.module if linked_case else str(data.get("case_module") or "")
        results.append(result)
    return results


async def _task_display_dict(record: BusinessRecord, db: AsyncSession) -> dict:
    return (await _task_display_dicts([record], db))[0]



async def _resolve_investigation_task_root(source: BusinessRecord, identity: dict, db: AsyncSession) -> BusinessRecord:
    if source.module == "investigation":
        return source
    candidate_ids: list[int] = []
    source_data = source.data or {}
    for key in ("investigation_record_id", "investigation_id"):
        try:
            candidate_id = int(source_data.get(key) or 0)
        except (TypeError, ValueError):
            candidate_id = 0
        if candidate_id > 0:
            candidate_ids.append(candidate_id)
    try:
        task_id = int(source_data.get("source_task_id") or 0)
    except (TypeError, ValueError):
        task_id = 0
    visited: set[int] = set()
    while task_id and task_id not in visited:
        visited.add(task_id)
        task = await db.get(BusinessRecord, task_id)
        if not task or task.module not in {"task", "investigation"}:
            break
        if task.module == "investigation":
            candidate_ids.insert(0, task.id)
            break
        task_data = task.data or {}
        for key in ("investigation_record_id", "investigation_id"):
            try:
                candidate_id = int(task_data.get(key) or 0)
            except (TypeError, ValueError):
                candidate_id = 0
            if candidate_id > 0:
                candidate_ids.append(candidate_id)
        try:
            task_id = int(task_data.get("parent_task_id") or 0)
        except (TypeError, ValueError):
            task_id = 0
    scope = await _record_scope_conditions(identity, db)
    for candidate_id in candidate_ids:
        root = await db.scalar(select(BusinessRecord).where(BusinessRecord.id == candidate_id, BusinessRecord.module == "investigation", *scope))
        if root:
            return root
    return source

async def _add_task_message_notifications(
    task: BusinessRecord,
    event: WorkflowEvent,
    db: AsyncSession,
    *,
    content: str,
) -> None:
    """Persist one idempotent unread lifecycle/communication message per participant."""
    db.add(event)
    await db.flush()
    data = task.data or {}
    recipients = {
        task.owner,
        str(data.get("initiator") or ""),
        *(str(value) for value in data.get("collaborators", []) if value),
    } - {""}
    if event.operator != "system":
        recipients.discard(event.operator)
    active_recipients = set((await db.scalars(select(User.username).where(
        User.username.in_(recipients), User.is_active.is_(True),
    ))).all()) if recipients else set()
    existing_keys = set((await db.scalars(select(Notification.source_key).where(
        Notification.source_key.in_([
            f"task-message-{task.id}-{event.id}-{recipient}" for recipient in active_recipients
        ])
    ))).all()) if active_recipients else set()
    for recipient in active_recipients:
        source_key = f"task-message-{task.id}-{event.id}-{recipient}"
        if source_key in existing_keys:
            continue
        db.add(Notification(
            source_key=source_key, source_type="task", source_id=task.id,
            sender=event.operator or "system", recipient=recipient,
            notification_type="系统通知", title=f"任务新消息：{task.serial_no}",
            content=content.strip() or event.action, level="info", is_read=False,
        ))


async def _delete_task_notifications(task_id: int, db: AsyncSession) -> None:
    """Delete every notification owned by a task before deleting that task record."""
    await db.execute(delete(Notification).where(
        Notification.source_type == "task", Notification.source_id == task_id,
    ))


