def _effective_job_role_action_keys(role: JobRole) -> list[str]:
    """Resolve a role's action nodes without treating menus as write grants."""
    result: list[str] = []
    for raw_value in role.permissions or []:
        value = str(raw_value or "").strip()
        candidates = (
            (value.removeprefix("action:"),)
            if value.startswith("action:")
            else JOB_ROLE_ACTION_KEY_GRANTS.get(value, ())
        )
        for candidate in candidates:
            if candidate and candidate not in result:
                result.append(candidate)
    return result


def _job_role_menu_permission_keys(permissions: list[str]) -> list[str]:
    """Resolve explicit menu keys and narrow legacy approval-action grants."""
    result: list[str] = []
    for value in permissions:
        key = str(value or "").strip()
        candidates = (key,) if key in SYSTEM_MENU_ROUTE_KEYS else JOB_ACTION_MENU_GRANTS.get(key, ())
        for candidate in candidates:
            if candidate not in result:
                result.append(candidate)
    return result


def _effective_job_role_menu_keys(role: JobRole) -> list[str]:
    """Resolve one HR role's checked tree nodes to real navigation grants."""
    result: list[str] = []
    for raw_value in role.permissions or []:
        value = str(raw_value or "").strip()
        candidates = (value,) if value in SYSTEM_MENU_ROUTE_KEYS else JOB_ROLE_LABEL_MENU_GRANTS.get(value, ())
        for candidate in candidates:
            if candidate not in result:
                result.append(candidate)
    return _expand_menu_permission_keys(result)


SYSTEM_ACTION_OPERATION_LABELS = {
    "query": "查询", "create": "新增", "update": "编辑", "delete": "删除",
    "clear": "清理", "reset": "重置", "permissions": "维护权限",
}


def _system_action_definitions(menu_keys: list[str] | set[str] | None = None) -> list[dict]:
    """Build the M/A catalog from local system menu capabilities.

    The legacy RoleController obtained actions dynamically from ActionService and
    MenuService.GetMenuActionList. The local service has no action table, so its
    endpoint capabilities are the maintainable source of truth.
    """
    keys = sorted(set(menu_keys or SYSTEM_MENU_ROUTE_KEYS))
    definitions: list[dict] = []
    for menu_key in keys:
        if menu_key == "system":
            operations = ("query", "permissions")
        elif menu_key == "system-management-cache":
            operations = ("query", "clear")
        elif menu_key == "system-management-menu":
            operations = ("query", "create", "update", "delete", "reset")
        elif menu_key == "system-management-config":
            operations = ("query", "update")
        elif menu_key == "system-parameters" or menu_key.startswith("system-parameters-"):
            operations = ("query", "create", "update", "delete")
        elif menu_key == "system-law-firms":
            operations = ("query", "create", "update", "delete")
        elif menu_key.startswith("system-"):
            operations = ("query",)
        else:
            continue
        definitions.extend(
            {"code": f"{menu_key}.{operation}", "menu_key": menu_key, "label": SYSTEM_ACTION_OPERATION_LABELS[operation]}
            for operation in operations
        )
    return definitions


SYSTEM_ACTION_DEFINITIONS = _system_action_definitions()
SYSTEM_ACTION_BY_CODE = {item["code"]: item for item in SYSTEM_ACTION_DEFINITIONS}


def _split_role_permission_keys(menu_keys: list[str] | None) -> tuple[list[str], list[str]]:
    menus: list[str] = []
    actions: list[str] = []
    for key in menu_keys or []:
        value = str(key)
        if value.startswith("@action:"):
            actions.append(value.removeprefix("@action:"))
        else:
            menus.append(value)
    return list(dict.fromkeys(menus)), list(dict.fromkeys(actions))


async def _system_audit(db: AsyncSession, identity: dict, action: str, target: str, detail: dict | None = None) -> None:
    """Write system-center audit rows in the caller's transaction."""
    record = BusinessRecord(
        module="system_audit",
        serial_no=f"SYS-AUDIT-{uuid4().hex}",
        title=target,
        status="已完成",
        owner=str(identity.get("username") or "system"),
        department="系统",
        data=detail or {},
    )
    db.add(record)
    await db.flush()
    db.add(WorkflowEvent(
        record_id=record.id,
        action=action,
        from_status="",
        to_status="已完成",
        operator=str(identity.get("username") or "system"),
        comment=json.dumps(detail or {}, ensure_ascii=False, separators=(",", ":")),
    ))


async def _system_permission_tree(db: AsyncSession, permission: RolePermission | None) -> list[dict]:
    menu_keys, action_keys = _split_role_permission_keys(permission.menu_keys if permission else [])
    rows = list((await db.scalars(select(SystemMenu).order_by(SystemMenu.sort_order, SystemMenu.id))).all())
    by_key = {item.key: item for item in rows}
    action_definitions = _system_action_definitions(set(by_key))
    action_by_menu: dict[str, list[dict]] = {}
    for definition in action_definitions:
        action_by_menu.setdefault(definition["menu_key"], []).append(definition)
    children_by_parent: dict[str, list[SystemMenu]] = {}
    for item in rows:
        children_by_parent.setdefault(item.parent_key or "", []).append(item)

    def build(item: SystemMenu) -> dict:
        children = [build(child) for child in children_by_parent.get(item.key, [])]
        for definition in action_by_menu.get(item.key, []):
            children.append({
                "node_type": "A", "node_original_id": f"action:{definition['code']}",
                "node_id": f"action:{definition['code']}",
                "node_code": definition["code"], "text": definition["label"], "title": definition["label"],
                "state": {"checked": definition["code"] in action_keys}, "children": [],
            })
        label = str(item.label or "").strip()
        if not label or label in {"---", "—", "-"}:
            label = DEFAULT_MENU_LABEL_BY_KEY.get(item.key, "未命名菜单")
        return {
            "node_type": "M", "node_original_id": item.id, "node_id": str(item.id),
            "node_code": item.key, "text": label, "title": label,
            "state": {"checked": item.key in menu_keys}, "children": children,
        }

    # Include configured menu rows and synthetic action roots even when an isolated
    # database has not seeded every default menu.
    roots = [build(item) for item in children_by_parent.get("", [])]
    known = {node["node_code"] for node in roots}
    for definition in action_definitions:
        if definition["menu_key"] not in by_key and definition["menu_key"] not in known:
            roots.append({
                "node_type": "M", "node_original_id": f"menu:{definition['menu_key']}",
                "node_id": f"menu:{definition['menu_key']}",
                "node_code": definition["menu_key"], "text": definition["menu_key"], "title": definition["menu_key"],
                "state": {"checked": definition["menu_key"] in menu_keys},
                "children": [{
                    "node_type": "A", "node_original_id": f"action:{definition['code']}",
                    "node_id": f"action:{definition['code']}",
                    "node_code": definition["code"], "text": definition["label"], "title": definition["label"],
                    "state": {"checked": definition["code"] in action_keys}, "children": [],
                }],
            })
    return roots

def _normalize_system_user_role_ids(
    role_ids: list[str] | None,
    role: str | None,
    *,
    fallback_role: str = "user",
) -> list[str]:
    legacy_role = str(role or "").strip()
    if legacy_role and legacy_role not in SYSTEM_USER_ROLE_CODES:
        raise HTTPException(status_code=422, detail="角色值无效")
    requested = role_ids if role_ids is not None else ([legacy_role] if legacy_role else [fallback_role])
    normalized = [str(value or "").strip() for value in requested]
    if not normalized or any(not value for value in normalized):
        raise HTTPException(status_code=422, detail="至少需要保留一个角色")
    invalid = sorted(set(normalized) - SYSTEM_USER_ROLE_CODES)
    if invalid:
        raise HTTPException(status_code=422, detail=f"角色值无效：{', '.join(invalid)}")
    if len(set(normalized)) != len(normalized):
        raise HTTPException(status_code=422, detail="角色不能重复")
    if role_ids is not None and legacy_role and legacy_role not in normalized:
        raise HTTPException(status_code=422, detail="主角色必须包含在角色列表中")
    primary = "admin" if "admin" in normalized else (legacy_role or normalized[0])
    return [primary, *(value for value in normalized if value != primary)]


def _system_user_role_ids(user: User) -> list[str]:
    role_ids = [role for role in user_role_ids(user) if role in SYSTEM_USER_ROLE_CODES]
    if not role_ids:
        return ["user"]
    if "admin" in role_ids:
        return ["admin", *(role for role in role_ids if role != "admin")]
    return role_ids


def _identity_role_ids(identity: dict) -> list[str]:
    role_ids = [str(role).strip() for role in identity.get("role_ids", []) if str(role).strip() in SYSTEM_USER_ROLE_CODES]
    role = str(identity.get("role") or "user").strip()
    if role in SYSTEM_USER_ROLE_CODES and role not in role_ids:
        role_ids.insert(0, role)
    if "admin" in role_ids:
        return ["admin", *(value for value in role_ids if value != "admin")]
    return list(dict.fromkeys(role_ids)) or ["user"]


async def _permission_payload(role: str, db: AsyncSession) -> dict:
    permission = await db.scalar(select(RolePermission).where(RolePermission.role == role))
    config = DEFAULT_ROLE_PERMISSIONS.get(role, DEFAULT_ROLE_PERMISSIONS["user"])
    if role == "admin":
        return {
            "menu_keys": list(MENU_KEYS),
            "action_keys": ["*"],
            "data_scope": config["data_scope"],
            "field_keys": list(FIELD_KEYS),
        }
    menu_keys, action_keys = _split_role_permission_keys(permission.menu_keys if permission else config["menu_keys"])
    return {
        "menu_keys": _expand_menu_permission_keys(menu_keys),
        "action_keys": action_keys,
        "data_scope": permission.data_scope if permission else config["data_scope"],
        "field_keys": list(permission.field_keys if permission else config["field_keys"]),
    }


async def _permission_payload_for_roles(role_ids: list[str], db: AsyncSession) -> dict:
    if "admin" in role_ids:
        return await _permission_payload("admin", db)
    payloads = [await _permission_payload(role, db) for role in role_ids]
    menu_keys = list(dict.fromkeys(key for payload in payloads for key in payload["menu_keys"]))
    action_keys = list(dict.fromkeys(key for payload in payloads for key in payload["action_keys"]))
    field_keys = list(dict.fromkeys(key for payload in payloads for key in payload["field_keys"]))
    # A multi-role account may accumulate menus/actions, but its data range must
    # be deterministic and least-privileged.  Using the first stored role made
    # visibility depend on role_ids ordering (and let role reordering expose
    # data).  The scopes form the legacy range ladder below.
    scope_rank = {
        "本人及共享数据": 0,
        "授权审批数据": 1,
        "本部门数据": 2,
        "全所数据": 3,
    }
    data_scope = min(
        (payload["data_scope"] for payload in payloads),
        key=lambda value: scope_rank.get(value, -1),
    )
    return {
        "menu_keys": _expand_menu_permission_keys(menu_keys),
        "action_keys": action_keys,
        # Multiple roles may broaden operations, but never data visibility.
        "data_scope": data_scope,
        "field_keys": field_keys,
    }


RECORD_MODULE_MENU_ROOTS: dict[str, tuple[str, ...]] = {
    "customer": ("customer",),
    "contract": ("contract",),
    "case": ("case",),
    "ipr_case": ("ipr",),
    "ipr_official_file": ("ipr",),
    "task": ("task",),
    "investigation": ("investigation",),
    "clue": ("investigation",),
    "notary": ("investigation",),
    "evidence": ("investigation",),
    "document": ("documents",),
    "seal": ("seal",),
    "hr": ("hr",),
    "warehouse": ("warehouse",),
    "report": ("reports",),
    "system": ("system",),
    # Financial records are shared by firm finance and platform finance workbenches.
    "finance": ("finance", "platform-finance"),
    "invoice": ("finance", "platform-finance"),
    "refund": ("finance", "platform-finance"),
    "finance_package": ("finance", "platform-finance"),
    "finance_settlement": ("finance", "platform-finance"),
    "finance_archive_settlement": ("finance", "platform-finance"),
    "contract_payment": ("finance", "platform-finance"),
}


def _menu_root(menu_key: str) -> str:
    """Return the configured top-level menu for a grantable menu key."""
    current = menu_key
    seen: set[str] = set()
    while MENU_PARENT_BY_KEY.get(current) and current not in seen:
        seen.add(current)
        current = MENU_PARENT_BY_KEY[current]
    return current


def _record_module_menu_roots(module: str) -> tuple[str, ...]:
    """Map generic-record modules to their owning business menu families.

    This is deliberately used only for direct generic operations.  Cross-module
    selectors retain their narrow, scoped lookup paths instead of receiving a
    broad record-list grant merely because a form needs to reference a customer
    or case.
    """
    roots = RECORD_MODULE_MENU_ROOTS.get(module)
    if not roots:
        raise HTTPException(status_code=422, detail="该业务模块不支持通用操作")
    return roots


async def _require_record_module_menu(module: str, identity: dict, db: AsyncSession, *, action: str) -> None:
    """Prevent generic write/export endpoints from bypassing menu authorization."""
    permission = await _permission_payload_for_identity(identity, db)
    if not _record_module_menu_allowed(module, identity, permission):
        raise HTTPException(status_code=403, detail=f"当前角色没有{action}该业务模块的菜单权限")
    action_key = {
        ("customer", "新建"): "record.customer.create",
        ("customer", "编辑"): "record.customer.update",
    }.get((module, action))
    if action_key and "*" not in permission.get("action_keys", []) and action_key not in permission.get("action_keys", []):
        raise HTTPException(status_code=403, detail=f"当前角色没有{action}该业务模块的动作权限")


def _record_module_menu_allowed(module: str, identity: dict, permission: dict) -> bool:
    """Return whether a module is readable from the caller's effective menu tree."""
    if "admin" in _identity_role_ids(identity):
        return True
    roots = RECORD_MODULE_MENU_ROOTS.get(module)
    if not roots:
        return False
    granted_roots = {_menu_root(key) for key in permission.get("menu_keys", [])}
    return bool(set(roots).intersection(granted_roots))


async def _require_contract_action(identity: dict, db: AsyncSession, action_key: str, action: str) -> None:
    """Allow visible contract workbenches while preserving workflow/data guards."""
    await _require_record_module_menu("contract", identity, db, action=action)


async def _require_hr_employee_action(identity: dict, db: AsyncSession, action_key: str, action: str) -> None:
    """Guard HR employee create/update without expanding other HR endpoints."""
    if "admin" in _identity_role_ids(identity):
        return
    permission = await _permission_payload_for_identity(identity, db)
    if "hr" not in {_menu_root(key) for key in permission["menu_keys"]}:
        raise HTTPException(status_code=403, detail="当前角色没有人事中心菜单权限")
    if action_key not in permission.get("action_keys", []):
        raise HTTPException(status_code=403, detail=f"当前角色没有{action}员工档案的动作权限")


def _user_permission_overrides(user: User) -> dict:
    """Return validated per-user permission overrides stored on the account profile."""
    overrides = (user.profile or {}).get("permission_overrides")
    if not isinstance(overrides, dict):
        return {}
    return {key: overrides[key] for key in ("menu_keys", "field_keys", "data_scope") if key in overrides and overrides[key] not in (None, "")}


def _configured_user_job_role_name(user: User) -> str:
    """Resolve only an explicitly assigned personnel role.

    A display position is descriptive employee data, not an authorization
    grant. This prevents stale values such as ``系统管理员`` from escalating a
    normal account when its role assignment is missing or deleted.
    """
    profile = user.profile or {}
    permission_role_code = str(profile.get("permission_role_code") or "").strip()
    if permission_role_code:
        return permission_role_code
    permission_role = str(profile.get("permission_role") or "").strip()
    if permission_role:
        return permission_role
    staff_role = str(profile.get("staff_role") or "").strip()
    if staff_role:
        return staff_role
    # Older employee records used the position field for business-role
    # assignment. It remains a compatibility fallback only when it is not a
    # system-administrator label; that label must never escalate a user role.
    position = str(profile.get("position") or "").strip()
    return position


async def _job_role_for_name(name: str, db: AsyncSession) -> JobRole | None:
    value = str(name or "").strip()
    if not value:
        return None
    return await db.scalar(select(JobRole).where(
        JobRole.is_active.is_(True),
        or_(JobRole.code == value, JobRole.name == value),
    ))


def _denied_job_role_payload(payload: dict) -> dict:
    """Fail closed for an invalid explicit personnel-role binding."""
    return {**payload, "menu_keys": [], "action_keys": [], "field_keys": []}


def _apply_job_role_policy(payload: dict, job_role: JobRole) -> dict:
    """Overlay one explicitly bound personnel role onto a system-role fallback."""
    if job_role.code == "SYSTEM-ADMIN":
        # A profile must never turn a non-admin system account into an admin.
        return _denied_job_role_payload(payload)
    result = dict(payload)
    result["menu_keys"] = _effective_job_role_menu_keys(job_role)
    result["action_keys"] = _effective_job_role_action_keys(job_role)
    if job_role.field_keys_configured:
        result["field_keys"] = list(dict.fromkeys(job_role.field_keys or []))
    if job_role.data_scope in ROLE_DATA_SCOPES:
        result["data_scope"] = job_role.data_scope
    return result


async def _permission_payload_for_identity(identity: dict, db: AsyncSession) -> dict:
    """Resolve system-role grants plus the explicitly assigned HR role."""
    user = await db.scalar(select(User).where(User.username == identity.get("username", "")))
    if user:
        return await _user_permission_payload(user, db)
    role_ids = _identity_role_ids(identity)
    payload = await _permission_payload_for_roles(role_ids, db)
    if "admin" in role_ids:
        return payload
    explicit_role_name = str(identity.get("permission_role") or identity.get("staff_role") or "").strip()
    if explicit_role_name:
        if explicit_role_name in {"系统管理员", "管理员"}:
            return _denied_job_role_payload(payload)
        job_role = await _job_role_for_name(explicit_role_name, db)
        if not job_role:
            return _denied_job_role_payload(payload)
        payload = _apply_job_role_policy(payload, job_role)
    return payload


async def _user_permission_payload(user: User, db: AsyncSession) -> dict:
    """Resolve navigation and field grants from the assigned HR role.

    A concrete personnel role is the authoritative menu tree for that account;
    the legacy system applies the selected role's checked nodes at login and
    at every protected backend operation. Base system-role grants remain the
    fallback for accounts without an assigned personnel role.
    """
    role_ids = _system_user_role_ids(user)
    permission = await _permission_payload_for_roles(role_ids, db)
    explicit_role_name = _configured_user_job_role_name(user)
    job_role = await _job_role_for_name(explicit_role_name, db) if explicit_role_name else None
    if explicit_role_name and "admin" not in role_ids:
        if explicit_role_name in {"系统管理员", "管理员"}:
            return _denied_job_role_payload(permission)
        if not job_role:
            return _denied_job_role_payload(permission)
        permission = _apply_job_role_policy(permission, job_role)
    overrides = _user_permission_overrides(user)
    if overrides.get("menu_keys") is not None:
        permission["menu_keys"] = _expand_menu_permission_keys(overrides["menu_keys"])
    if overrides.get("field_keys") is not None:
        permission["field_keys"] = list(overrides["field_keys"])
    if overrides.get("data_scope") is not None:
        permission["data_scope"] = overrides["data_scope"]
    can_approve_contract = await _is_contract_approver(user, db)
    menu_keys = list(permission["menu_keys"])
    if can_approve_contract and "contract-audit" not in menu_keys:
        menu_keys.append("contract-audit")
    return {
        **permission,
        "menu_keys": _expand_menu_permission_keys(menu_keys),
        "action_keys": list(dict.fromkeys(permission.get("action_keys", []))),
        "can_approve_contract": can_approve_contract,
    }


async def _allowed_field_keys(identity: dict, db: AsyncSession) -> set[str]:
    role_ids = _identity_role_ids(identity)
    if "admin" in role_ids:
        return set(FIELD_KEYS)
    permission = await _permission_payload_for_identity(identity, db)
    user = await db.scalar(select(User).where(User.username == identity["username"]))
    if user:
        overrides = _user_permission_overrides(user)
        if overrides.get("field_keys") is not None:
            return set(overrides["field_keys"])
    return set(permission["field_keys"])


async def _record_dict_for_identity(record: BusinessRecord, identity: dict, db: AsyncSession) -> dict:
    return await _contract_customer_record_dict(
        record,
        await _allowed_field_keys(identity, db),
        db,
        identity=identity,
    )


def _is_smoke_test_username(username: object) -> bool:
    """Only hide explicitly generated smoke accounts; recorded English names stay valid."""
    return str(username or "").strip().casefold().startswith("smoke_")


async def _active_employee_usernames(db: AsyncSession) -> set[str]:
    """Return active staff login identities backed by an active HR record."""
    employees = (await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "hr",
        BusinessRecord.status.not_in({"离职", "停用"}),
    ))).all()
    return {
        username
        for item in employees
        for username in [str((item.data or {}).get("username") or item.owner or "").strip().lower()]
        if username
        and str((item.data or {}).get("account_type") or "员工账号").strip() == "员工账号"
        and not _is_smoke_test_username(username)
    }


async def _active_customer_usernames(db: AsyncSession) -> set[str]:
    """Return active customer-service login identities from HR customer accounts."""
    employees = (await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "hr",
        BusinessRecord.status.not_in({"离职", "停用"}),
    ))).all()
    return {
        username
        for item in employees
        for username in [str((item.data or {}).get("username") or item.owner or "").strip().lower()]
        if username
        and str((item.data or {}).get("account_type") or "").strip() == "客户账号"
        and not _is_smoke_test_username(username)
    }


async def _resolve_active_customer_managers(values: list[object], db: AsyncSession) -> list[str]:
    """Resolve customer managers to stable usernames, accepting unique display names and keywords for legacy UI clients."""
    tokens = list(dict.fromkeys(str(value or "").strip() for value in values if str(value or "").strip()))
    if not tokens:
        raise HTTPException(status_code=422, detail="至少保留一名客户管理人")
    users = list((await db.scalars(select(User).where(User.is_active.is_(True), or_(User.username.in_(tokens), User.display_name.in_(tokens))))).all())
    by_username = {user.username: user.username for user in users}
    by_display: dict[str, list[str]] = {}
    for user in users:
        by_display.setdefault(user.display_name, []).append(user.username)
    resolved: list[str] = []
    invalid: list[str] = []
    for token in tokens:
        username = by_username.get(token)
        if not username:
            matches = by_display.get(token, [])
            if len(matches) == 1:
                username = matches[0]
        if not username:
            invalid.append(token)
        elif username not in resolved:
            resolved.append(username)
    if invalid:
        unresolved: list[str] = []
        for token in invalid:
            like = f"%{token}%"
            matches = list((await db.scalars(select(User).where(
                User.is_active.is_(True),
                or_(User.username.ilike(like), User.display_name.ilike(like)),
            ))).all())
            match_usernames = sorted({user.username for user in matches})
            if len(match_usernames) == 1:
                username = match_usernames[0]
                if username not in resolved:
                    resolved.append(username)
            else:
                unresolved.append(token)
        if unresolved:
            raise HTTPException(status_code=422, detail=f"客户管理人不存在、已停用或姓名不唯一：{'、'.join(unresolved)}")
    smoke_accounts = [username for username in resolved if _is_smoke_test_username(username)]
    if smoke_accounts:
        raise HTTPException(status_code=422, detail=f"测试账号不能作为客户管理人：{'、'.join(smoke_accounts)}")
    return resolved


def _prioritize_new_customer_managers(existing: list[object], requested: list[str]) -> list[str]:
    """Preserve the caller's newest-first priority block ahead of retained managers."""
    existing_names = list(dict.fromkeys(str(value or "").strip() for value in existing if str(value or "").strip()))
    requested_names = list(dict.fromkeys(requested))
    added = [manager for manager in requested_names if manager not in existing_names]
    retained = [manager for manager in existing_names if manager in requested_names]
    return [*added, *retained]


async def _resolve_active_case_people(values: list[object], db: AsyncSession, *, field_name: str) -> tuple[list[str], list[str]]:
    """Resolve case-team inputs once and persist usernames alongside display values.

    The UI remains compatible with the old name-based forms, but access control
    never depends on a mutable/duplicate display name after a case is saved.
    """
    labels = list(dict.fromkeys(str(value or "").strip() for value in values if str(value or "").strip()))
    if not labels:
        return [], []
    users = list((await db.scalars(select(User).where(
        User.is_active.is_(True),
        or_(User.username.in_(labels), User.display_name.in_(labels)),
    ))).all())
    by_username = {user.username: user for user in users}
    by_display: dict[str, list[User]] = {}
    for user in users:
        by_display.setdefault(user.display_name, []).append(user)
    resolved_labels: list[str] = []
    resolved_usernames: list[str] = []
    invalid: list[str] = []
    for label in labels:
        user = by_username.get(label)
        if not user:
            matches = by_display.get(label, [])
            user = matches[0] if len(matches) == 1 else None
        if not user:
            invalid.append(label)
            continue
        # Persist a stable, human-readable display value; usernames remain the
        # authoritative ACL identity and are what new selection controls submit.
        # The legacy people picker allows every active staff account.  HR position
        # text is optional for migrated accounts and must not invalidate a person
        # that the authoritative picker already exposed.
        resolved_labels.append(user.display_name)
        if user.username not in resolved_usernames:
            resolved_usernames.append(user.username)
    if invalid:
        raise HTTPException(status_code=422, detail=f"{field_name}不存在、已停用或姓名不唯一：{'、'.join(invalid)}")
    return resolved_labels, resolved_usernames


def _case_team_payload(
    case_data: dict, handling_lawyers: list[str], handling_usernames: list[str], assistant: str | list[str], assistant_username: str | list[str],
) -> dict:
    """Keep legacy display fields and the stable access-control projection in sync."""
    assistants = list(dict.fromkeys(
        str(value or "").strip() for value in (assistant if isinstance(assistant, list) else [assistant]) if str(value or "").strip()
    ))
    assistant_usernames = list(dict.fromkeys(
        str(value or "").strip() for value in (assistant_username if isinstance(assistant_username, list) else [assistant_username]) if str(value or "").strip()
    ))
    return {
        **case_data,
        "handling_lawyers": handling_lawyers,
        "assistant": assistants[0] if assistants else "",
        "assistants": assistants,
        "handling_lawyer_usernames": handling_usernames,
        "assistant_username": assistant_usernames[0] if assistant_usernames else "",
        "assistant_usernames": assistant_usernames,
        "case_team_usernames": list(dict.fromkeys([*handling_usernames, *assistant_usernames])),
    }


def _prioritize_new_case_assistants(
    case_data: dict,
    assistant_values: list[str],
    assistant_usernames: list[str],
) -> tuple[list[str], list[str]]:
    """Place newly added assistants first while retaining the stored relative order."""
    existing_usernames = set(_contract_person_values(
        case_data.get("assistant_usernames") or case_data.get("assistant_username")
    ))
    existing_names = set(_contract_person_values(
        case_data.get("assistants") or case_data.get("assistant")
    ))
    pairs = list(zip(assistant_values, assistant_usernames))
    added = [pair for pair in pairs if pair[1] not in existing_usernames and pair[0] not in existing_names]
    retained = [pair for pair in pairs if pair[1] in existing_usernames or pair[0] in existing_names]
    ordered = [*reversed(added), *retained]
    return [pair[0] for pair in ordered], [pair[1] for pair in ordered]


async def _case_team_role(case_record: BusinessRecord, identity: dict, db: AsyncSession) -> str:
    """Return manager/handling_lawyer/assistant/none for a visible case.

    New writes use stable usernames.  The narrowly-scoped legacy fallback keeps
    old rows usable only where the current user's display name is unique.
    """
    if identity.get("role") == "admin" or case_record.owner == identity["username"]:
        return "manager"
    user = await db.scalar(select(User).where(User.username == identity["username"]))
    if identity.get("role") == "manager" and user and case_record.department == user.department:
        return "manager"
    data = case_record.data or {}
    username = identity["username"]
    handling_usernames = {str(value or "").strip() for value in data.get("handling_lawyer_usernames", [])}
    assistant_usernames = {str(value or "").strip() for value in (data.get("assistant_usernames") or [])}
    assistant_username = str(data.get("assistant_username") or "").strip()
    if username in handling_usernames:
        return "handling_lawyer"
    if username and (username == assistant_username or username in assistant_usernames):
        return "assistant"
    if data.get("case_team_usernames"):
        return "none"
    # Legacy-only fallback.  Display names may be used only when unique.
    display_name = str(user.display_name or "").strip() if user else ""
    display_is_unique = bool(display_name) and (await db.scalar(select(func.count(User.id)).where(User.is_active.is_(True), User.display_name == display_name)) == 1)
    handler_labels = {str(value or "").strip() for value in data.get("handling_lawyers", [])}
    assistant_label = str(data.get("assistant") or "").strip()
    if username in handler_labels or (display_is_unique and display_name in handler_labels):
        return "handling_lawyer"
    if username == assistant_label or (display_is_unique and display_name == assistant_label):
        return "assistant"
    return "none"


def _case_personal_scope_condition(username: str):
    exact_username_token = f'"{username}"'
    return or_(
        BusinessRecord.owner == username,
        BusinessRecord.data["case_team_usernames"].as_string().contains(exact_username_token),
        BusinessRecord.data["legacy_participants"].as_string().contains(
            f'"staff_name":"{username}"'
        ),
    )


async def _case_mine_scope_condition(identity: dict, db: AsyncSession):
    """Limit the Mine list to concrete case participation, even for admins."""
    username = str(identity["username"]).strip()
    exact_username_token = f'"{username}"'
    data = BusinessRecord.data
    conditions = [
        and_(
            BusinessRecord.owner == username,
            func.coalesce(data["source_person_username"].as_string(), "") == "",
            func.coalesce(data["source_person"].as_string(), "") == "",
            func.coalesce(data["business_owner"].as_string(), "") == "",
            func.coalesce(data["assistant_username"].as_string(), "") == "",
            func.coalesce(data["investigator"].as_string(), "") == "",
            func.coalesce(data["court_lawyer_username"].as_string(), "") == "",
            func.coalesce(data["case_team_usernames"].as_string(), "").in_({"", "[]"}),
            func.coalesce(data["handling_lawyer_usernames"].as_string(), "").in_({"", "[]"}),
            func.coalesce(data["legacy_participants"].as_string(), "").in_({"", "[]"}),
        ),
        data["case_team_usernames"].as_string().contains(exact_username_token),
        data["handling_lawyer_usernames"].as_string().contains(exact_username_token),
        data["legacy_participants"].as_string().contains(f'"staff_name":"{username}"'),
        func.lower(func.coalesce(data["source_person_username"].as_string(), "")) == username.lower(),
        func.lower(func.coalesce(data["source_person"].as_string(), "")) == username.lower(),
        func.lower(func.coalesce(data["business_owner"].as_string(), "")) == username.lower(),
        func.lower(func.coalesce(data["assistant_username"].as_string(), "")) == username.lower(),
        func.lower(func.coalesce(data["investigator"].as_string(), "")) == username.lower(),
        func.lower(func.coalesce(data["court_lawyer_username"].as_string(), "")) == username.lower(),
        select(FileAttachment.id).where(
            FileAttachment.record_id == BusinessRecord.id,
            func.lower(FileAttachment.uploader) == username.lower(),
        ).exists(),
    ]

    return or_(*conditions)


async def _record_scope_conditions(identity: dict, db: AsyncSession) -> list:
    if identity.get("role") == "admin":
        return []
    user = await db.scalar(select(User).where(User.username == identity["username"]))
    if not user:
        raise HTTPException(status_code=401, detail="当前用户不存在")
    scope = (await _user_permission_payload(user, db))["data_scope"]
    if scope == "全所数据":
        return []
    public_customer = and_(BusinessRecord.module == "customer", BusinessRecord.status == "公海")
    # JSON arrays are serialized with quoted string members.  Matching the
    # quoted username keeps ``ann`` from gaining access to rows assigned or
    # shared to ``joann`` while remaining portable across SQLite and
    # PostgreSQL.
    exact_username_token = f'"{user.username}"'
    managed_customer = and_(BusinessRecord.module == "customer", BusinessRecord.data["customer_managers"].as_string().contains(exact_username_token))
    shared_to_text = BusinessRecord.data["shared_to"].as_string()
    shared_with_text = BusinessRecord.data["shared_with"].as_string()
    shared_customer = and_(BusinessRecord.module == "customer", shared_with_text.contains(exact_username_token))
    exact_shared_to = shared_to_text.contains(exact_username_token)
    # A case team member must be able to find the assigned case even if their
    # ordinary role has only "own data" scope.  This is deliberately limited to
    # case records and stable username projections; it does not widen financial,
    # archive or team-management authority.
    personal_case = and_(BusinessRecord.module == "case", _case_personal_scope_condition(user.username))
    published_investigation = and_(
        BusinessRecord.module == "investigation",
        func.lower(BusinessRecord.data["publisher"].as_string()) == user.username.lower(),
    )
    initiated_task = and_(
        BusinessRecord.module == "task",
        func.lower(func.coalesce(BusinessRecord.data["initiator"].as_string(), "")) == user.username.lower(),
    )
    assigned_clue_review = and_(
        BusinessRecord.module == "clue",
        func.lower(func.coalesce(BusinessRecord.data["reviewer"].as_string(), "")) == user.username.lower(),
    )
    pending_contract_approval = and_(
        BusinessRecord.module == "contract",
        BusinessRecord.status == "审批中",
        select(ContractApprovalStep.id).where(
            ContractApprovalStep.contract_record_id == BusinessRecord.id,
            ContractApprovalStep.approver == user.username,
            ContractApprovalStep.status == "待审批",
        ).exists(),
    )
    if scope == "本部门数据":
        return [or_(BusinessRecord.department == user.department, public_customer, managed_customer, shared_customer, exact_shared_to, personal_case, published_investigation, initiated_task, assigned_clue_review, pending_contract_approval)]
    if scope == "授权审批数据":
        # Approval range is not a blanket view of every pending record.  A
        # contract becomes visible here only for its current pending approver;
        # other modules retain their own owner/share/participant projections
        # until they expose an equally concrete candidate relation.
        return [or_(BusinessRecord.owner == user.username, public_customer, managed_customer, shared_customer, exact_shared_to, personal_case, published_investigation, initiated_task, assigned_clue_review, pending_contract_approval)]
    return [or_(BusinessRecord.owner == user.username, public_customer, managed_customer, shared_customer, exact_shared_to, personal_case, published_investigation, initiated_task, assigned_clue_review, pending_contract_approval)]


async def _visible_legacy_ipr_case_ids(identity: dict, db: AsyncSession) -> set[int]:
    """Expose materialized IPR history only through current IPR menu and scope."""
    await _require_record_module_menu("ipr_case", identity, db, action="查看")
    if "admin" in _identity_role_ids(identity):
        return set()
    rows = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "ipr_case", *(await _record_scope_conditions(identity, db)),
    ))).all())
    legacy_ids: set[int] = set()
    for row in rows:
        raw_id = (row.data or {}).get("legacy_ipr_case_id", (row.data or {}).get("legacy_case_id"))
        try:
            if raw_id not in (None, ""):
                legacy_ids.add(int(raw_id))
        except (TypeError, ValueError):
            continue
    return legacy_ids


app.include_router(
    create_legacy_ipr_history_router(visible_legacy_case_ids=_visible_legacy_ipr_case_ids),
    prefix=settings.api_prefix,
)
app.include_router(ipr_fee_file_router, prefix=settings.api_prefix)


async def _visible_legacy_ls_case_ids(identity: dict, db: AsyncSession) -> set[int]:
    """Expose LS history only through an explicit current-case legacy identity."""

    await _require_record_module_menu("case", identity, db, action="查看")
    if "admin" in _identity_role_ids(identity):
        return set()
    rows = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "case", *(await _record_scope_conditions(identity, db)),
    ))).all())
    visible: set[int] = set()
    for row in rows:
        value = (row.data or {}).get("legacy_ls_case_id")
        try:
            if value not in (None, ""):
                visible.add(int(value))
        except (TypeError, ValueError):
            continue
    # New carrier rows retain their own mapping column rather than requiring a
    # second write into BusinessRecord.data.  The relation remains exact by
    # current record primary key and stays fail-closed when the carrier is not
    # present in a database yet.
    record_ids = [int(row.id) for row in rows]
    if record_ids:
        bind_names = {f"record_id_{index}": record_id for index, record_id in enumerate(record_ids)}
        try:
            result = await db.execute(text(
                "SELECT legacy_case_id FROM legacy_ls_cases WHERE current_case_record_id IN ("
                + ",".join(f":{name}" for name in bind_names) + ")"
            ), bind_names)
            visible.update(int(value) for value in result.scalars().all())
        except SQLAlchemyError:
            # An unmigrated application database has no LS carrier table.  Do
            # not broaden visibility or make ordinary case pages unavailable.
            pass
    return visible


app.include_router(
    create_legacy_ls_history_router(visible_legacy_case_ids=_visible_legacy_ls_case_ids),
    prefix=settings.api_prefix,
)


async def _visible_legacy_contract_history_parent_keys(identity: dict, db: AsyncSession) -> set[str]:
    """Restrict historical contract parents to current visible customer/contract/case scope."""
    if "admin" in _identity_role_ids(identity):
        return set()
    records = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module.in_(("customer", "contract", "case")),
        *(await _record_scope_conditions(identity, db)),
    ))).all())
    aliases: set[tuple[str, str]] = set()
    for record in records:
        data = record.data or {}
        if record.module == "contract":
            value = str(record.serial_no or data.get("contract_no") or "").strip().upper()
            if value:
                aliases.add(("contract_no", value))
        elif record.module == "customer":
            value = str(record.serial_no or data.get("customer_no") or "").strip().upper()
            if value:
                aliases.add(("customer_no", value))
        else:
            contract_no = str(data.get("contract_no") or "").strip().upper()
            customer_no = str(data.get("customer_no") or "").strip().upper()
            if contract_no:
                aliases.add(("contract_no", contract_no))
            if customer_no:
                aliases.add(("customer_no", customer_no))
    if not aliases:
        return set()
    clauses = []
    parameters: dict[str, str] = {}
    for index, (kind, value) in enumerate(sorted(aliases)):
        clauses.append(f"(alias_kind=:legacy_alias_kind_{index} AND alias_value=:legacy_alias_value_{index})")
        parameters[f"legacy_alias_kind_{index}"] = kind
        parameters[f"legacy_alias_value_{index}"] = value
    try:
        result = await db.execute(text(
            "SELECT DISTINCT history_parent_key FROM legacy_contract_parent_aliases "
            "WHERE source_system='GDCRM' AND (" + " OR ".join(clauses) + ")"
        ), parameters)
    except SQLAlchemyError:
        return set()
    return {str(row[0]) for row in result.all()}


app.include_router(
    create_legacy_contract_history_router(
        visible_history_parent_keys=_visible_legacy_contract_history_parent_keys,
    ),
    prefix=settings.api_prefix,
)


async def _ensure_record_visible(record_id: int, identity: dict, db: AsyncSession) -> BusinessRecord:
    conditions = [BusinessRecord.id == record_id, *(await _record_scope_conditions(identity, db))]
    record = await db.scalar(select(BusinessRecord).where(*conditions))
    if not record:
        raise HTTPException(status_code=404, detail="记录不存在或无权访问")
    return record


async def _ensure_attachment_record_visible(record_id: int, identity: dict, db: AsyncSession) -> BusinessRecord:
    """Resolve attachment parent visibility without losing task-participant access.

    Task collaborators and initiators deliberately have a narrower record scope than
    ordinary owners, but they are still first-class participants for task feedback.
    Attachments must therefore use the task participation rule before the generic
    business-record scope rule.
    """
    record = await db.get(BusinessRecord, record_id)
    if record and record.module == "task":
        if not _is_task_participant(record, identity):
            raise HTTPException(status_code=403, detail="只有任务参与人可以访问任务反馈附件")
        return record
    return await _ensure_record_visible(record_id, identity, db)


async def _require_hr_attachment_write_access(record: BusinessRecord, category: str, identity: dict, db: AsyncSession) -> None:
    if record.module != "hr":
        return
    if category != "员工档案":
        raise HTTPException(status_code=422, detail="员工档案附件类型必须为员工档案")
    if identity.get("role") not in {"admin", "manager"}:
        raise HTTPException(status_code=403, detail="仅系统管理员或部门负责人可以维护员工档案")
    await _ensure_record_module(record.id, "hr", identity, db)


async def _ensure_record_module(record_id: int, module: str, identity: dict, db: AsyncSession) -> BusinessRecord:
    record = await _ensure_record_visible(record_id, identity, db)
    if record.module != module:
        raise HTTPException(status_code=404, detail="业务记录不存在")
    return record


async def _require_record_owner_or_manager(record: BusinessRecord, identity: dict, db: AsyncSession) -> None:
    if record.module == "customer" and record.status == "公海" and identity.get("role") != "admin":
        raise HTTPException(status_code=403, detail="公海客户必须先领取后才能修改")
    if identity.get("role") == "admin" or record.owner == identity["username"] or (
        record.module == "customer" and identity["username"] in (record.data or {}).get("customer_managers", [])
    ):
        return
    user = await db.scalar(select(User).where(User.username == identity["username"]))
    if identity.get("role") == "manager" and user and record.department == user.department:
        return
    raise HTTPException(status_code=403, detail="只有负责人、部门负责人或系统管理员可以执行此操作")


async def _require_contract_investigation_create_access(
    contract: BusinessRecord, identity: dict, db: AsyncSession,
) -> None:
    """Recognize the contract's legacy business owner as its investigation publisher."""
    if identity.get("role") == "admin":
        return
    user = await db.scalar(select(User).where(User.username == identity["username"]))
    if not user:
        raise HTTPException(status_code=401, detail="当前用户不存在")
    actor_tokens = {
        str(user.username or "").strip().casefold(),
        str(user.display_name or "").strip().casefold(),
    } - {""}
    data = contract.data or {}
    responsible_tokens = {
        str(value or "").strip().casefold()
        for key in (
            "source_person", "source_person_username", "business_owner",
            "business_owner_username", "source_owner",
        )
        for value in _contract_person_values(data.get(key))
        if str(value or "").strip()
    }
    responsible_tokens.add(str(contract.owner or "").strip().casefold())
    if actor_tokens & responsible_tokens:
        return
    if identity.get("role") == "manager" and contract.department == user.department:
        return
    raise HTTPException(status_code=403, detail="只有负责人、部门负责人或系统管理员可以执行此操作")


async def _require_contract_attachment_write_access(record: BusinessRecord, identity: dict, db: AsyncSession) -> None:
    """Protect generic attachment writes for contract records.

    Contract detail UI disables attachment writes while approval is in progress or
    after archiving; enforce the same rule server-side so the generic attachment
    endpoints cannot be used to bypass that guard.
    """
    await _require_record_owner_or_manager(record, identity, db)
    if record.status in {"审批中", "已归档"}:
        raise HTTPException(status_code=409, detail="审批中或已归档合同不能上传或删除附件")


def _require_task_owner_or_initiator(task: BusinessRecord, identity: dict, *, action: str) -> None:
    """Protect task writes from department-manager privilege escalation.

    Department scope grants read access to task lists, not authority to impersonate
    the current owner.  A manager who is neither owner nor initiator must not first
    replace the owner through a generic/batch endpoint and then perform lifecycle
    actions as that new owner.  System administrators deliberately retain the
    documented all-firm override.
    """
    username = identity["username"]
    data = task.data or {}
    if identity.get("role") == "admin" or task.owner == username or data.get("initiator") == username:
        return
    raise HTTPException(status_code=403, detail=f"只有任务负责人、发起人或系统管理员可以{action}")


async def _visible_record_ids(identity: dict, db: AsyncSession) -> set[int]:
    conditions = await _record_scope_conditions(identity, db)
    return set((await db.scalars(select(BusinessRecord.id).where(*conditions))).all())


async def _filter_visible_attachments(items: list[FileAttachment], identity: dict, db: AsyncSession) -> list[FileAttachment]:
    if identity.get("role") == "admin":
        return items
    record_ids = await _visible_record_ids(identity, db)
    return [item for item in items if (item.record_id and item.record_id in record_ids) or (not item.record_id and item.uploader == identity["username"])]


async def _security_policy(db: AsyncSession) -> SecurityPolicy:
    policy = await db.get(SecurityPolicy, 1)
    if not policy:
        policy = SecurityPolicy(id=1, min_password_length=8, max_failed_attempts=5, lock_minutes=30, token_minutes=settings.access_token_minutes, updated_by="system")
        db.add(policy); await db.flush()
    return policy


def _security_policy_dict(policy: SecurityPolicy) -> dict:
    return {"min_password_length": policy.min_password_length, "max_failed_attempts": policy.max_failed_attempts, "lock_minutes": policy.lock_minutes, "token_minutes": policy.token_minutes, "updated_by": policy.updated_by, "updated_at": policy.updated_at}


async def _login_response(user: User, db: AsyncSession, *, require_password_change: bool | None = None) -> dict:
    policy = await _security_policy(db)
    permission = await _user_permission_payload(user, db)
    role_ids = _system_user_role_ids(user)
    must_change = user.must_change_password if require_password_change is None else require_password_change
    return {
        "access_token": create_token(user.username, role_ids[0], policy.token_minutes),
        "token_type": "bearer",
        "expires_in": policy.token_minutes * 60,
        "must_change_password": must_change,
        "user": {
            "username": user.username,
            "display_name": user.display_name,
            "department": user.department,
            "role": role_ids[0],
            "role_ids": role_ids,
            "must_change_password": must_change,
            **permission,
        },
    }


@app.post(f"{settings.api_prefix}/auth/login")
async def login(form: OAuth2PasswordRequestForm = Depends(), db: AsyncSession = Depends(get_db)):
    user = await db.scalar(select(User).where(User.username == form.username))
    if not user or not user.is_active:
        raise HTTPException(status_code=401, detail="账号或密码错误")
    policy = await _security_policy(db)
    # PostgreSQL returns TIMESTAMP WITH TIME ZONE values as aware datetimes,
    # while SQLite returns the same model field as a naive datetime.
    # Match the persisted value's timezone before comparing so both local
    # development and Docker/PostgreSQL enforce login locks identically.
    now = datetime.now(user.locked_until.tzinfo) if user.locked_until and user.locked_until.tzinfo else datetime.now()
    if user.locked_until and user.locked_until > now:
        raise HTTPException(status_code=423, detail=f"登录失败次数过多，账号锁定至 {user.locked_until.strftime('%Y-%m-%d %H:%M:%S')}")
    if not verify_password(form.password, user.password_hash):
        user.failed_login_attempts = int(user.failed_login_attempts or 0) + 1
        if user.failed_login_attempts >= policy.max_failed_attempts:
            user.locked_until = now + timedelta(minutes=policy.lock_minutes)
        await db.commit()
        if user.locked_until: raise HTTPException(status_code=423, detail=f"登录失败次数过多，账号已锁定 {policy.lock_minutes} 分钟")
        raise HTTPException(status_code=401, detail=f"账号或密码错误，还可尝试 {policy.max_failed_attempts - user.failed_login_attempts} 次")
    if password_needs_rehash(user.password_hash):
        user.password_hash = hash_password(form.password)
        user.password_changed_at = now
    user.failed_login_attempts = 0; user.locked_until = None; user.last_login_at = now
    await db.commit()
    return await _login_response(user, db)


@app.get(f"{settings.api_prefix}/auth/dingtalk/config")
async def dingtalk_login_config():
    return {
        "enabled": dingtalk_client.configured,
        "corp_id": settings.dingtalk_corp_id if dingtalk_client.configured else "",
        "agent_id": settings.dingtalk_agent_id if dingtalk_client.configured else "",
    }


def _dingtalk_allowed_display_names() -> set[str]:
    raw = str(settings.dingtalk_allowed_display_names or "")
    for separator in ("，", ";", "；", "\n"):
        raw = raw.replace(separator, ",")
    return {name.strip() for name in raw.split(",") if name.strip()}


def _require_dingtalk_access(user: User) -> None:
    allowed_names = _dingtalk_allowed_display_names()
    if allowed_names and str(user.display_name or "").strip() not in allowed_names:
        raise HTTPException(status_code=403, detail="当前员工未开通钉钉登录，请联系管理员")


@app.post(f"{settings.api_prefix}/auth/dingtalk/login")
async def dingtalk_login(body: DingTalkLoginInput, db: AsyncSession = Depends(get_db)):
    if not dingtalk_client.configured:
        raise HTTPException(status_code=503, detail="钉钉免登尚未配置")
    try:
        ding_user = await dingtalk_client.user_by_auth_code(body.auth_code.strip())
    except (DingTalkError, httpx.HTTPError) as exc:
        logger.warning("DingTalk login failed: %s", exc)
        raise HTTPException(status_code=502, detail="钉钉身份校验失败，请稍后重试") from exc
    users = (await db.scalars(select(User).where(User.is_active.is_(True)))).all()
    matched = [user for user in users if str((user.profile or {}).get("dingtalk_user_id") or "").strip() == ding_user["user_id"]]
    if not matched and ding_user.get("mobile"):
        matched = [user for user in users if str((user.profile or {}).get("mobile") or "").strip() == ding_user["mobile"]]
        if len(matched) == 1:
            matched[0].profile = {**(matched[0].profile or {}), "dingtalk_user_id": ding_user["user_id"]}
    ding_name = str(ding_user.get("name") or "").strip()
    if not matched and ding_name in _dingtalk_allowed_display_names():
        matched = [user for user in users if str(user.display_name or "").strip() == ding_name]
        if len(matched) == 1:
            matched[0].profile = {**(matched[0].profile or {}), "dingtalk_user_id": ding_user["user_id"]}
    if len(matched) != 1:
        raise HTTPException(status_code=403, detail="钉钉账号尚未绑定系统员工，请联系管理员在员工账号中绑定")
    user = matched[0]
    _require_dingtalk_access(user)
    user.last_login_at = datetime.now()
    await db.commit()
    return await _login_response(user, db, require_password_change=False)


@app.post(f"{settings.api_prefix}/auth/dingtalk/bind")
async def bind_dingtalk_login(body: DingTalkBindInput, db: AsyncSession = Depends(get_db)):
    if not dingtalk_client.configured:
        raise HTTPException(status_code=503, detail="钉钉免登尚未配置")
    try:
        ding_user = await dingtalk_client.user_by_auth_code(body.auth_code.strip())
    except (DingTalkError, httpx.HTTPError) as exc:
        raise HTTPException(status_code=502, detail="钉钉身份校验失败，请从工作台重新打开系统") from exc
    user = await db.scalar(select(User).where(User.username == body.username.strip().lower(), User.is_active.is_(True)))
    if not user or not verify_password(body.password, user.password_hash):
        raise HTTPException(status_code=401, detail="OA 账号或密码错误")
    _require_dingtalk_access(user)
    profile = {**(user.profile or {}), "dingtalk_user_id": ding_user["user_id"]}
    await _ensure_unique_dingtalk_user_id(profile, db, user.id, user.display_name)
    user.profile = profile
    user.last_login_at = datetime.now()
    await db.commit()
    return await _login_response(user, db)


@app.get(f"{settings.api_prefix}/auth/me")
async def current_user_profile(identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    user = await db.scalar(select(User).where(User.username == identity["username"]))
    if not user or not user.is_active:
        raise HTTPException(status_code=404, detail="当前用户不存在")
    return {**_system_user_dict(user), **(await _user_permission_payload(user, db))}


@app.patch(f"{settings.api_prefix}/auth/me")
async def update_current_user_profile(body: CurrentUserUpdate, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    user = await db.scalar(select(User).where(User.username == identity["username"]))
    if not user or not user.is_active:
        raise HTTPException(status_code=404, detail="当前用户不存在")
    if body.display_name is not None:
        user.display_name = body.display_name.strip()
    profile_changes = {
        key: value.strip() if isinstance(value, str) else value
        for key, value in {
            "email": body.email,
            "office_phone": body.office_phone,
            "mobile": body.mobile,
            "menu_auto_collapse": body.menu_auto_collapse,
        }.items()
        if value is not None
    }
    if profile_changes:
        user.profile = {**(user.profile or {}), **profile_changes}
    if body.new_password is not None:
        if not body.current_password or not verify_password(body.current_password, user.password_hash):
            raise HTTPException(status_code=400, detail="当前密码不正确")
        if body.new_password == body.current_password:
            raise HTTPException(status_code=400, detail="新密码不能与当前密码相同")
        policy = await _security_policy(db)
        if len(body.new_password) < policy.min_password_length: raise HTTPException(status_code=422, detail=f"新密码至少需要 {policy.min_password_length} 位")
        user.password_hash = hash_password(body.new_password)
        user.password_changed_at = datetime.now(); user.failed_login_attempts = 0; user.locked_until = None; user.must_change_password = False
    await db.commit()
    await db.refresh(user)
    return {**_system_user_dict(user), **(await _user_permission_payload(user, db))}


def _require_admin(identity: dict) -> None:
    if "admin" not in _identity_role_ids(identity):
        raise HTTPException(status_code=403, detail="仅系统管理员可以执行此操作")


def _system_user_dict(user: User) -> dict:
    profile = user.profile or {}
    role_ids = _system_user_role_ids(user)
    person_name, person_name_missing = _person_display_name(user.display_name, user.username)
    manager_name, manager_name_missing = _person_display_name(profile.get("manager_name", ""), "")
    return {"id": user.id, "username": user.username, "display_name": user.display_name, "person_display_name": person_name, "display_name_missing": person_name_missing, "department": user.department, "role": role_ids[0], "role_ids": role_ids, "is_active": user.is_active, "must_change_password": user.must_change_password, "profile": profile, "contract_approval_enabled": bool(profile.get("contract_approval_enabled")), "dingtalk_user_id": profile.get("dingtalk_user_id", ""), "dingtalk_bound": bool(profile.get("dingtalk_user_id")), "email": profile.get("email", ""), "office_phone": profile.get("office_phone", ""), "mobile": profile.get("mobile", ""), "menu_auto_collapse": profile.get("menu_auto_collapse", "no"), "manager_id": profile.get("manager_id"), "manager_name": profile.get("manager_name", ""), "manager_person_display_name": manager_name if profile.get("manager_id") else "", "manager_name_missing": manager_name_missing if profile.get("manager_id") else False, "access_level": profile.get("access_level", ""), "lead_rate": profile.get("lead_rate", ""), "copy_rate": profile.get("copy_rate", ""), "failed_login_attempts": user.failed_login_attempts or 0, "locked_until": user.locked_until, "last_login_at": user.last_login_at, "password_changed_at": user.password_changed_at, "created_at": user.created_at}


@app.get(f"{settings.api_prefix}/system/users")
async def list_system_users(keyword: str = "", identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    statement = select(User)
    if keyword.strip():
        like = f"%{keyword.strip()}%"
        statement = statement.where(or_(User.username.ilike(like), User.display_name.ilike(like)))
    users = (await db.scalars(statement.order_by(User.id))).all()
    return {"items": [_system_user_dict(user) for user in users], "total": len(users)}


@app.patch(f"{settings.api_prefix}/system/users/{{user_id}}/dingtalk")
async def bind_system_user_dingtalk(user_id: int, body: DingTalkBindingInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    user = await db.get(User, user_id)
    if not user:
        raise HTTPException(status_code=404, detail="系统用户不存在")
    ding_user_id = body.user_id.strip()
    if ding_user_id:
        _require_dingtalk_access(user)
        users = (await db.scalars(select(User).where(User.id != user_id))).all()
        if any(str((item.profile or {}).get("dingtalk_user_id") or "").strip() == ding_user_id for item in users):
            raise HTTPException(status_code=409, detail="该钉钉账号已绑定其他系统用户")
    profile = dict(user.profile or {})
    if ding_user_id:
        profile["dingtalk_user_id"] = ding_user_id
    else:
        profile.pop("dingtalk_user_id", None)
    user.profile = profile
    await db.commit(); await db.refresh(user)
    return _system_user_dict(user)


@app.get(f"{settings.api_prefix}/people/options")
async def list_active_people_options(identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    """Expose only active personnel names for authenticated internal selectors."""
    users = list((await db.scalars(select(User).where(User.is_active.is_(True)).order_by(User.display_name, User.username))).all())
    employees = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "hr", BusinessRecord.status.not_in({"离职", "停用"}),
    ))).all())
    employee_names = {
        str((employee.data or {}).get("username") or employee.owner or "").strip().lower(): str(employee.title or "").strip()
        for employee in employees
        if str((employee.data or {}).get("username") or employee.owner or "").strip()
    }
    items = []
    for user in users:
        name = employee_names.get(user.username.strip().lower()) or str(user.display_name or "").strip()
        if name:
            system_display_name = str(user.display_name or "").strip()
            items.append({
                "value": name,
                "label": name,
                "username": user.username,
                "search_text": " ".join(
                    value for value in (name, system_display_name, user.username) if value
                ),
            })
    return {"items": items}


async def _ensure_unique_dingtalk_user_id(profile: dict, db: AsyncSession, exclude_user_id: int | None = None, display_name: str = "") -> None:
    ding_user_id = str(profile.get("dingtalk_user_id") or "").strip()
    if not ding_user_id:
        return
    allowed_names = _dingtalk_allowed_display_names()
    if allowed_names and str(display_name or "").strip() not in allowed_names:
        raise HTTPException(status_code=403, detail="当前员工未开通钉钉登录，请联系管理员")
    users = (await db.scalars(select(User))).all()
    if any(user.id != exclude_user_id and str((user.profile or {}).get("dingtalk_user_id") or "").strip() == ding_user_id for user in users):
        raise HTTPException(status_code=409, detail="该钉钉账号已绑定其他系统用户")


@app.post(f"{settings.api_prefix}/system/users", status_code=status.HTTP_201_CREATED)
async def create_system_user(body: SystemUserInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    role_ids = _normalize_system_user_role_ids(body.role_ids, body.role)
    username = body.username.strip().lower()
    if await db.scalar(select(User).where(User.username == username)):
        raise HTTPException(status_code=409, detail="登录账号已存在")
    policy = await _security_policy(db)
    if len(body.password) < policy.min_password_length: raise HTTPException(status_code=422, detail=f"密码至少需要 {policy.min_password_length} 位")
    profile = {**body.profile, "access_level": body.access_level.strip(), "lead_rate": body.lead_rate.strip(), "copy_rate": body.copy_rate.strip(), **(await _system_user_manager_profile(body.manager_id, db))}
    await _ensure_unique_dingtalk_user_id(profile, db, display_name=body.display_name)
    user = User(
        username=username,
        display_name=body.display_name.strip(),
        department=body.department.strip(),
        role=role_ids[0],
        role_ids=role_ids,
        profile=profile,
        password_hash=hash_password(body.password),
        is_active=body.is_active,
        password_changed_at=None,
        must_change_password=True,
    )
    db.add(user)
    await db.commit(); await db.refresh(user)
    return _system_user_dict(user)


async def _system_user_manager_profile(manager_id: int | None, db: AsyncSession) -> dict:
    if not manager_id:
        return {"manager_id": None, "manager_name": ""}
    manager = await db.get(User, manager_id)
    if not manager or not manager.is_active:
        raise HTTPException(status_code=422, detail="上级领导不存在或已停用")
    return {"manager_id": manager.id, "manager_name": manager.display_name}


def _replace_username_value(value: object, old_username: str, new_username: str) -> object:
    """Replace exact username tokens in JSON data without touching free text."""
    if isinstance(value, str):
        return new_username if value == old_username else value
    if isinstance(value, list):
        return [_replace_username_value(item, old_username, new_username) for item in value]
    if isinstance(value, dict):
        return {key: _replace_username_value(item, old_username, new_username) for key, item in value.items()}
    return value


async def _rename_system_username(user: User, requested_username: str, identity: dict, db: AsyncSession) -> str:
    new_username = requested_username.strip().lower()
    old_username = user.username
    if not re.fullmatch(r"[a-z0-9._-]{2,64}", new_username):
        raise HTTPException(status_code=422, detail="登录账号只能包含小写字母、数字、点、下划线或短横线")
    if new_username == old_username:
        return old_username
    if old_username == identity["username"]:
        raise HTTPException(status_code=409, detail="不能在当前登录会话中修改自己的登录账号，请由其他管理员操作")
    if await db.scalar(select(User.id).where(User.username == new_username, User.id != user.id)):
        raise HTTPException(status_code=409, detail="登录账号已存在")

    scalar_references = (
        (Department, Department.manager), (Department, Department.created_by), (Department, Department.updated_by),
        (JobRole, JobRole.created_by), (JobRole, JobRole.updated_by),
        (SecurityPolicy, SecurityPolicy.updated_by), (SystemParameter, SystemParameter.created_by),
        (SystemParameter, SystemParameter.updated_by), (SystemConfig, SystemConfig.updated_by),
        (SystemMenu, SystemMenu.updated_by), (BusinessRecord, BusinessRecord.owner),
        (WorkflowEvent, WorkflowEvent.operator), (HrSubrecord, HrSubrecord.created_by),
        (HrSubrecord, HrSubrecord.updated_by), (HearingSchedule, HearingSchedule.hearing_lawyer),
        (FileAttachment, FileAttachment.uploader), (FinanceTransaction, FinanceTransaction.operator),
        (ReconciliationBatch, ReconciliationBatch.operator), (IncomingPayment, IncomingPayment.claimant),
        (IncomingPayment, IncomingPayment.operator), (ContractApprovalStep, ContractApprovalStep.approver),
        (Notification, Notification.sender), (Notification, Notification.recipient),
        (CommunicationLog, CommunicationLog.operator), (AgentDocument, AgentDocument.creator),
        (AgentDocument, AgentDocument.confirmed_by), (SealAsset, SealAsset.custodian),
    )
    for model, field in scalar_references:
        await db.execute(update(model).where(field == old_username).values({field.key: new_username}))

    for record in (await db.scalars(select(BusinessRecord))).all():
        replaced = _replace_username_value(record.data or {}, old_username, new_username)
        if replaced != (record.data or {}):
            record.data = replaced
    for payment in (await db.scalars(select(IncomingPayment))).all():
        replaced = _replace_username_value(payment.allocations or [], old_username, new_username)
        if replaced != (payment.allocations or []):
            payment.allocations = replaced
    for config in (await db.scalars(select(SystemConfig))).all():
        replaced = _replace_username_value(config.value or {}, old_username, new_username)
        if replaced != (config.value or {}):
            config.value = replaced
    user.profile = _replace_username_value(user.profile or {}, old_username, new_username)
    user.username = new_username
    return new_username


async def _ensure_system_user_lifecycle_safe(user: User, db: AsyncSession, *, action: str) -> None:
    """Keep account administration from orphaning HR records or approval nodes."""
    pending_contract = await db.scalar(
        select(BusinessRecord.serial_no)
        .join(ContractApprovalStep, ContractApprovalStep.contract_record_id == BusinessRecord.id)
        .where(
            BusinessRecord.module == "contract",
            BusinessRecord.status == "审批中",
            ContractApprovalStep.status == "待审批",
            ContractApprovalStep.approver == user.username,
        )
        .order_by(BusinessRecord.id)
        .limit(1)
    )
    if pending_contract:
        raise HTTPException(status_code=409, detail=f"账号正在审批合同 {pending_contract}，请先完成、改派或撤回该合同审批后再{action}")
    employee_no = await db.scalar(
        select(BusinessRecord.serial_no)
        .where(
            BusinessRecord.module == "hr",
            or_(BusinessRecord.owner == user.username, BusinessRecord.data["username"].as_string() == user.username),
        )
        .order_by(BusinessRecord.id)
        .limit(1)
    )
    if employee_no:
        raise HTTPException(status_code=409, detail=f"账号已关联员工档案 {employee_no}，请通过人事办理状态同步账号，不能直接{action}")


@app.patch(f"{settings.api_prefix}/system/users/{{user_id}}")
async def update_system_user(user_id: int, body: SystemUserUpdate, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    user = await db.get(User, user_id)
    if not user:
        raise HTTPException(status_code=404, detail="用户不存在")
    if body.username is not None:
        await _rename_system_username(user, body.username, identity, db)
    if body.role is not None or body.role_ids is not None:
        role_ids = _normalize_system_user_role_ids(body.role_ids, body.role, fallback_role=_system_user_role_ids(user)[0])
        if user.username == identity["username"] and "admin" not in role_ids:
            raise HTTPException(status_code=409, detail="不能取消当前登录账号的管理员角色")
        user.role = role_ids[0]
        user.role_ids = role_ids
    if body.is_active is not None:
        if user.username == identity["username"] and not body.is_active:
            raise HTTPException(status_code=409, detail="不能停用当前登录账号")
        if not body.is_active and user.is_active:
            await _ensure_system_user_lifecycle_safe(user, db, action="停用")
        user.is_active = body.is_active
    if body.display_name is not None:
        user.display_name = await _require_unique_hr_display_name(
            body.display_name,
            db,
            linked_username=user.username,
        )
    if body.department is not None:
        user.department = body.department.strip()
    if body.password is not None:
        policy = await _security_policy(db)
        if len(body.password) < policy.min_password_length: raise HTTPException(status_code=422, detail=f"密码至少需要 {policy.min_password_length} 位")
        user.password_hash = hash_password(body.password)
        user.password_changed_at = None; user.must_change_password = True; user.failed_login_attempts = 0; user.locked_until = None
    profile = dict(user.profile or {})
    if "manager_id" in body.model_fields_set:
        profile.update(await _system_user_manager_profile(body.manager_id or None, db))
    for key in ("access_level", "lead_rate", "copy_rate"):
        if key in body.model_fields_set:
            value = getattr(body, key)
            profile[key] = (value or "").strip()
    if body.profile is not None:
        profile = {**profile, **body.profile}
    await _ensure_unique_dingtalk_user_id(profile, db, user.id, user.display_name)
    user.profile = profile
    await db.commit(); await db.refresh(user)
    return _system_user_dict(user)


