async def _parameter_reference_examples(item: SystemParameter, db: AsyncSession) -> list[str]:
    """Return a small, exact sample of business references before parameter deletion.

    Parameters remain historical master data.  Deleting one that is already in a
    customer, case or attachment would make existing records impossible to
    interpret, so the generic maintenance endpoint must reject it instead.
    """
    relation_checks = (
        (CaseTypeFileTypeRelation, CaseTypeFileTypeRelation.case_type_id, "案件类型-文件类型关联"),
        (CaseTypeFileTypeRelation, CaseTypeFileTypeRelation.file_type_id, "案件类型-文件类型关联"),
        (CaseFileTypeFeeTypeRelation, CaseFileTypeFeeTypeRelation.file_type_id, "文件类型-费用类型关联"),
        (CaseFileTypeFeeTypeRelation, CaseFileTypeFeeTypeRelation.fee_type_id, "文件类型-费用类型关联"),
        (CaseTypeCasePhaseRelation, CaseTypeCasePhaseRelation.case_type_id, "案件类型-案件阶段关联"),
        (CaseTypeCasePhaseRelation, CaseTypeCasePhaseRelation.case_phase_id, "案件类型-案件阶段关联"),
    )
    for model, field, label in relation_checks:
        if await db.scalar(select(model.id).where(field == item.id).limit(1)):
            return [label]
    if item.category == "fee_type":
        children = list((await db.scalars(select(SystemParameter).where(
            SystemParameter.category == "fee_type",
            SystemParameter.extra["parent_code"].as_string() == item.code,
        ).limit(3))).all())
        if children:
            return [f"下级费用类型：{child.name}" for child in children]
        records = list((await db.scalars(select(BusinessRecord).where(
            BusinessRecord.module == "finance",
            or_(
                BusinessRecord.data["fee_type_id"].as_integer() == item.id,
                BusinessRecord.data["fee_type_code"].as_string() == item.code,
                BusinessRecord.data["expense_subtype"].as_string() == item.name,
            ),
        ).limit(3))).all())
        if records:
            return [record.serial_no for record in records]
    if item.category == "case_file_type":
        attachments = list((await db.scalars(select(FileAttachment).where(FileAttachment.category == item.name).limit(3))).all())
        return [f"附件#{attachment.id}" for attachment in attachments]
    if item.category == "case_phase":
        records = list((await db.scalars(select(BusinessRecord).where(BusinessRecord.module == "case", BusinessRecord.status == item.name).limit(3))).all())
        return [record.serial_no for record in records]
    fields_by_module = PARAMETER_REFERENCE_FIELDS.get(item.category, {})
    examples: list[str] = []
    for module, fields in fields_by_module.items():
        records = list((await db.scalars(select(BusinessRecord).where(BusinessRecord.module == module))).all())
        for record in records:
            data = record.data or {}
            if any(str(data.get(field) or "").strip() == item.name for field in fields):
                examples.append(record.serial_no)
                if len(examples) >= 3:
                    return examples
    return examples


@app.post(f"{settings.api_prefix}/system/parameters", status_code=status.HTTP_201_CREATED)
async def create_system_parameter(body: SystemParameterInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    if body.category not in SYSTEM_PARAMETER_CATEGORIES: raise HTTPException(status_code=422, detail="参数分类无效")
    code, name = body.code.strip(), body.name.strip()
    if body.category == "payment_type":
        candidates = list((await db.scalars(select(SystemParameter).where(SystemParameter.category == body.category))).all())
        next_payee = str((body.extra or {}).get("payee") or "").strip().casefold()
        duplicate = next((item for item in candidates if item.code == code or (next_payee and str((item.extra or {}).get("payee") or "").strip().casefold() == next_payee)), None)
    else:
        duplicate = await db.scalar(select(SystemParameter).where(SystemParameter.category == body.category, or_(SystemParameter.code == code, SystemParameter.name == name)))
    if duplicate: raise HTTPException(status_code=409, detail="同一分类下参数代码或名称已存在")
    next_extra = body.extra
    await _validate_parameter_parent(body.category, code, next_extra, db)
    if body.category == "fee_type":
        next_extra = await _normalized_fee_type_extra(code, next_extra, db)
    await _validate_parameter_references(body.category, next_extra, db)
    item = SystemParameter(**body.model_dump(exclude={"code", "name", "extra"}), code=code, name=name, extra=next_extra, created_by=identity["username"], updated_by=identity["username"])
    db.add(item); await db.flush()
    await _system_audit(db, identity, "创建系统参数", f"系统参数:{item.category}/{item.code}", {"id": item.id, "category": item.category, "code": item.code})
    await db.commit(); await db.refresh(item); _clear_parameter_cache(body.category, identity["username"])
    return _system_parameter_dict(item)


@app.patch(f"{settings.api_prefix}/system/parameters/{{parameter_id}}")
async def update_system_parameter(parameter_id: int, body: SystemParameterUpdate, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    item = await db.get(SystemParameter, parameter_id)
    if not item: raise HTTPException(status_code=404, detail="系统参数不存在")
    code = body.code.strip() if body.code is not None else item.code
    name = body.name.strip() if body.name is not None else item.name
    next_extra = body.extra if body.extra is not None else (item.extra or {})
    if item.category == "payment_type":
        candidates = list((await db.scalars(select(SystemParameter).where(SystemParameter.category == item.category, SystemParameter.id != item.id))).all())
        next_payee = str(next_extra.get("payee") or "").strip().casefold()
        duplicate = next((candidate for candidate in candidates if candidate.code == code or (next_payee and str((candidate.extra or {}).get("payee") or "").strip().casefold() == next_payee)), None)
    else:
        duplicate = await db.scalar(select(SystemParameter).where(SystemParameter.category == item.category, SystemParameter.id != item.id, or_(SystemParameter.code == code, SystemParameter.name == name)))
    if duplicate: raise HTTPException(status_code=409, detail="同一分类下参数代码、名称或收款单位已存在")
    await _validate_parameter_parent(item.category, code, next_extra, db, current_id=item.id)
    if item.category == "fee_type":
        next_extra = await _normalized_fee_type_extra(code, next_extra, db)
        active_children = list((await db.scalars(select(SystemParameter).where(
            SystemParameter.category == "fee_type",
            SystemParameter.extra["parent_code"].as_string() == item.code,
            SystemParameter.is_active.is_(True),
        ))).all())
        if body.is_active is False and active_children:
            raise HTTPException(status_code=409, detail="费用类型存在可用的下级类型，不能直接停用")
    await _validate_parameter_references(item.category, next_extra, db)
    previous_code = item.code
    for key, value in body.model_dump(exclude_unset=True, exclude={"extra"}).items(): setattr(item, key, value.strip() if key in {"code", "name"} else value)
    item.extra = next_extra
    if item.category == "fee_type" and previous_code != code:
        children = list((await db.scalars(select(SystemParameter).where(
            SystemParameter.category == "fee_type",
            SystemParameter.extra["parent_code"].as_string() == previous_code,
        ))).all())
        for child in children:
            child.extra = {**(child.extra or {}), "parent_code": code}
            child.updated_by = identity["username"]
    item.updated_by = identity["username"]
    await _system_audit(db, identity, "更新系统参数", f"系统参数:{item.category}/{item.code}", {"id": item.id, "category": item.category, "code": item.code})
    await db.commit(); await db.refresh(item); _clear_parameter_cache(item.category, identity["username"])
    return _system_parameter_dict(item)


@app.delete(f"{settings.api_prefix}/system/parameters/{{parameter_id}}", status_code=status.HTTP_204_NO_CONTENT)
async def delete_system_parameter(parameter_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    item = await db.get(SystemParameter, parameter_id)
    if not item: raise HTTPException(status_code=404, detail="系统参数不存在")
    references = await _parameter_reference_examples(item, db)
    if references:
        raise HTTPException(status_code=409, detail=f"参数“{item.name}”已被业务记录引用（{ '、'.join(references) }），不能删除；请停用以保留历史数据")
    category = item.category
    await _system_audit(db, identity, "删除系统参数", f"系统参数:{category}/{item.code}", {"id": item.id, "category": category, "code": item.code})
    await db.delete(item); await db.commit(); _clear_parameter_cache(category, identity["username"])
    return Response(status_code=status.HTTP_204_NO_CONTENT)


def _validate_system_config(key: str, value: dict) -> dict:
    if key == "customer_share_policy":
        required = {"all_days", "filed_days", "premium_days", "standard_days", "basic_days", "shared_days"}
        if set(value) != required or any(isinstance(value[name], bool) or not isinstance(value[name], int) or not 1 <= value[name] <= 3650 for name in required):
            raise HTTPException(status_code=422, detail="客户共享天数必须完整填写，范围为 1 至 3650 天")
    elif key == "company_profile":
        required = {"name", "code", "short_code", "address", "phone", "fax", "email", "postal_code", "bank_name", "bank_account", "bank_address"}
        if set(value) != required or any(not isinstance(value[name], str) for name in required) or not all(str(value[name]).strip() for name in {"name", "code", "short_code"}):
            raise HTTPException(status_code=422, detail="公司名称、代码和字母短写代码必填，且公司资料字段必须完整")
        value = {name: str(value[name]).strip() for name in required}
    elif key == "application_settings":
        required = {"system_name", "default_department", "page_size", "attachment_limit_mb", "maintenance_mode"}
        if set(value) != required or not isinstance(value["maintenance_mode"], bool) or not isinstance(value["page_size"], int) or not 10 <= value["page_size"] <= 200 or not isinstance(value["attachment_limit_mb"], int) or not 1 <= value["attachment_limit_mb"] <= 100:
            raise HTTPException(status_code=422, detail="系统配置字段或数值范围无效")
        if not str(value["system_name"]).strip() or not str(value["default_department"]).strip(): raise HTTPException(status_code=422, detail="系统名称和默认部门必填")
    elif key == "investigation_assignment":
        if set(value) != {"supervisor_username"} or not isinstance(value["supervisor_username"], str):
            raise HTTPException(status_code=422, detail="调查任务分配人配置无效")
        value = {"supervisor_username": value["supervisor_username"].strip()}
    else:
        raise HTTPException(status_code=404, detail="系统配置不存在")
    return value


@app.get(f"{settings.api_prefix}/system/configs")
async def list_system_configs(keyword: str = "", page: int | None = Query(None, ge=1), page_size: int | None = Query(None, ge=1, le=200), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    items = (await db.scalars(select(SystemConfig).order_by(SystemConfig.id))).all()
    result = [{"key": item.key, "label": item.label, "group": item.group, "value": item.value or {}, "description": item.description, "updated_by": item.updated_by, "updated_at": item.updated_at} for item in items]
    supervisor_options = [
        {"username": user.username, "display_name": user.display_name}
        for user in (await db.scalars(select(User).where(User.is_active.is_(True)).order_by(User.display_name, User.username))).all()
    ]
    if keyword.strip():
        needle = keyword.strip().lower()
        result = [item for item in result if needle in " ".join([item["key"], item["label"], item["group"], item["description"], json.dumps(item["value"], ensure_ascii=False)]).lower()]
    if page is None and page_size is None:
        return {"items": result, "investigation_supervisor_options": supervisor_options}
    current_page, current_size = page or 1, page_size or 15
    total = len(result); start = (current_page - 1) * current_size
    return {"items": result[start:start + current_size], "total": total, "page": current_page, "page_size": current_size, "investigation_supervisor_options": supervisor_options}


@app.patch(f"{settings.api_prefix}/system/configs/{{config_key}}")
async def update_system_config(config_key: str, body: SystemConfigUpdate, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    item = await db.scalar(select(SystemConfig).where(SystemConfig.key == config_key))
    if not item: raise HTTPException(status_code=404, detail="系统配置不存在")
    value = _validate_system_config(config_key, body.value)
    if config_key == "investigation_assignment":
        supervisor = await db.scalar(select(User).where(User.username == value["supervisor_username"], User.is_active.is_(True)))
        if not supervisor:
            raise HTTPException(status_code=422, detail="调查任务分配人必须是启用的系统人员")
    item.value = value; item.updated_by = identity["username"]
    await _system_audit(db, identity, "更新系统配置", f"系统配置:{item.key}", {"key": item.key})
    await db.commit(); await db.refresh(item)
    return {"key": item.key, "label": item.label, "group": item.group, "value": item.value, "description": item.description, "updated_by": item.updated_by, "updated_at": item.updated_at}


async def _system_cache_entry_count(cache_key: str, definition: dict, db: AsyncSession) -> int:
    category = definition.get("category")
    if category:
        if category == "__all__":
            return sum(len(items) for items in SYSTEM_PARAMETER_CACHE.values())
        return len(SYSTEM_PARAMETER_CACHE.get(category, []))
    return 0


def _clear_registered_cache(cache_key: str, operator: str) -> None:
    definition = SYSTEM_CACHE_REGISTRY[cache_key]
    category = definition.get("category")
    if category:
        _clear_parameter_cache(None if category == "__all__" else category, operator)
    SYSTEM_CACHE_META[cache_key] = {"last_cleared_at": datetime.now().isoformat(), "last_cleared_by": operator}


@app.get(f"{settings.api_prefix}/system/caches")
async def list_system_caches(keyword: str = "", page: int | None = Query(None, ge=1), page_size: int | None = Query(None, ge=1, le=200), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    # system-parameters is retained as a backwards-compatible clear alias, but the
    # visible registry mirrors the legacy eight cache rows.
    keys = [key for key in SYSTEM_CACHE_REGISTRY if key != "system-parameters"]
    rows = []
    for key in keys:
        definition = SYSTEM_CACHE_REGISTRY[key]
        rows.append({"key": key, "name": definition["name"], "description": definition["description"], "entry_count": await _system_cache_entry_count(key, definition, db), "bucket_count": 1, **SYSTEM_CACHE_META[key]})
    if keyword.strip():
        needle = keyword.strip().lower()
        rows = [row for row in rows if needle in f"{row['key']} {row['name']} {row['description']}".lower()]
    # Keep the legacy cache-list contract when callers omit pagination: the old
    # endpoint defaulted to page 1 with 15 rows and always returned metadata.
    current_page, current_size = page or 1, page_size or 15
    total = len(rows); start = (current_page - 1) * current_size
    return {"items": rows[start:start + current_size], "total": total, "page": current_page, "page_size": current_size, "pages": (total + current_size - 1) // current_size}


@app.post(f"{settings.api_prefix}/system/caches/clear")
async def clear_system_caches(body: CacheBatchClearInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    requested_keys = list(dict.fromkeys(body.cache_keys))
    keys = requested_keys if requested_keys else [key for key in SYSTEM_CACHE_REGISTRY if key != "system-parameters"]
    unknown = [key for key in keys if key not in SYSTEM_CACHE_REGISTRY or key == "system-parameters"]
    if unknown:
        raise HTTPException(status_code=404, detail=f"缓存不存在: {unknown[0]}")
    for key in keys:
        _clear_registered_cache(key, identity["username"])
    await _system_audit(db, identity, "清理系统缓存", "系统缓存:批量", {"cache_keys": keys, "clear_all": not requested_keys})
    await db.commit()
    return {"cleared": keys, "items": [{"key": key, "entry_count": await _system_cache_entry_count(key, SYSTEM_CACHE_REGISTRY[key], db), **SYSTEM_CACHE_META[key]} for key in keys]}


@app.post(f"{settings.api_prefix}/system/caches/{{cache_key}}/clear")
async def clear_system_cache(cache_key: str, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    if cache_key not in SYSTEM_CACHE_REGISTRY: raise HTTPException(status_code=404, detail="缓存不存在")
    _clear_registered_cache(cache_key, identity["username"])
    await _system_audit(db, identity, "清理系统缓存", f"系统缓存:{cache_key}", {"cache_key": cache_key})
    await db.commit()
    definition = SYSTEM_CACHE_REGISTRY[cache_key]
    return {"key": cache_key, "cleared": True, "entry_count": await _system_cache_entry_count(cache_key, definition, db), **SYSTEM_CACHE_META[cache_key]}


def _law_firm_contact_dict(item: LawFirmContact, *, is_default: bool = False) -> dict:
    return {
        "id": item.id, "law_firm_id": item.law_firm_id, "name": item.name,
        "address": item.address, "postal_code": item.postal_code, "phone": item.phone,
        "fax": item.fax, "email": item.email, "is_active": item.is_active,
        "is_default": is_default, "created_by": item.created_by, "updated_by": item.updated_by,
        "created_at": item.created_at, "updated_at": item.updated_at,
    }


def _law_firm_dict(item: LawFirm, license_attachment: FileAttachment | None = None, contacts: list[LawFirmContact] | None = None) -> dict:
    result = {
        "id": item.id, "code": item.code, "name": item.name,
        "registered_address": item.registered_address, "business_address": item.business_address,
        "detail_address": item.detail_address, "postal_code": item.postal_code, "phone": item.phone,
        "fax": item.fax, "email": item.email, "organization_code": item.organization_code,
        "company_code": item.company_code, "firm_type": item.firm_type, "firm_level": item.firm_level,
        "country": item.country, "is_active": item.is_active,
        "default_contact_id": item.default_contact_id, "license_attachment_id": item.license_attachment_id,
        "license": _attachment_dict(license_attachment) if license_attachment else None,
        "created_by": item.created_by, "updated_by": item.updated_by,
        "created_at": item.created_at, "updated_at": item.updated_at,
    }
    if contacts is not None:
        contact_dicts = [_law_firm_contact_dict(contact, is_default=contact.id == item.default_contact_id) for contact in contacts]
        result["contacts"] = contact_dicts
        result["default_contact"] = next((contact for contact in contact_dicts if contact["is_default"]), None)
    return result


def _law_firm_audit_dict(item: LawFirmAudit) -> dict:
    return {"id": item.id, "law_firm_id": item.law_firm_id, "action": item.action, "operator": item.operator, "detail": item.detail, "created_at": item.created_at}


async def _law_firm_or_404(law_firm_id: int, db: AsyncSession) -> LawFirm:
    item = await db.get(LawFirm, law_firm_id)
    if not item: raise HTTPException(status_code=404, detail="律所不存在")
    return item


async def _law_firm_license(item: LawFirm, db: AsyncSession) -> FileAttachment | None:
    return await db.get(FileAttachment, item.license_attachment_id) if item.license_attachment_id else None


@app.get(f"{settings.api_prefix}/law-firms")
async def list_law_firms(keyword: str = "", include_inactive: bool = False, page: int = Query(1, ge=1), page_size: int = Query(50, ge=1, le=200), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    conditions = []
    if not include_inactive: conditions.append(LawFirm.is_active.is_(True))
    if keyword.strip():
        like = f"%{keyword.strip()}%"
        conditions.append(or_(LawFirm.code.ilike(like), LawFirm.name.ilike(like), LawFirm.phone.ilike(like), LawFirm.email.ilike(like), LawFirm.firm_type.ilike(like)))
    total = int(await db.scalar(select(func.count()).select_from(LawFirm).where(*conditions)) or 0)
    items = (await db.scalars(select(LawFirm).where(*conditions).order_by(LawFirm.is_active.desc(), LawFirm.name, LawFirm.id).offset((page - 1) * page_size).limit(page_size))).all()
    licenses = {item.id: await _law_firm_license(item, db) for item in items}
    return {"items": [_law_firm_dict(item, licenses[item.id]) for item in items], "total": total, "page": page, "page_size": page_size}


@app.get(f"{settings.api_prefix}/law-firms/{{law_firm_id}}")
async def get_law_firm(law_firm_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    item = await _law_firm_or_404(law_firm_id, db)
    contacts = list((await db.scalars(select(LawFirmContact).where(LawFirmContact.law_firm_id == item.id).order_by(LawFirmContact.id))).all())
    return _law_firm_dict(item, await _law_firm_license(item, db), contacts)


@app.get(f"{settings.api_prefix}/law-firms/{{law_firm_id}}/audits")
async def list_law_firm_audits(law_firm_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    await _law_firm_or_404(law_firm_id, db)
    items = list((await db.scalars(select(LawFirmAudit).where(LawFirmAudit.law_firm_id == law_firm_id).order_by(LawFirmAudit.id.desc()))).all())
    return {"items": [_law_firm_audit_dict(item) for item in items], "total": len(items)}


async def _create_law_firm_record(body: LawFirmInput, identity: dict, db: AsyncSession, *, license_bytes: bytes | None = None, license_filename: str | None = None) -> dict:
    _require_admin(identity)
    code, name = body.code.strip().upper(), body.name.strip()
    if await db.scalar(select(LawFirm.id).where(or_(LawFirm.code == code, LawFirm.name == name))):
        raise HTTPException(status_code=409, detail="律所编号或名称已存在")
    default_contact_payload = body.default_contact
    item = LawFirm(code=code, name=name, **body.model_dump(exclude={"code", "name", "default_contact"}), created_by=identity["username"], updated_by=identity["username"])
    db.add(item); await db.flush()
    if default_contact_payload is not None:
        contact = LawFirmContact(law_firm_id=item.id, **default_contact_payload.model_dump(), created_by=identity["username"], updated_by=identity["username"])
        db.add(contact); await db.flush(); item.default_contact_id = contact.id
    if license_bytes:
        filename = Path(license_filename or "营业执照").name
        suffix = Path(filename).suffix.lower()
        if suffix not in {".jpg", ".jpeg", ".png", ".gif"}: raise HTTPException(status_code=422, detail="营业执照仅支持 JPG、PNG 或 GIF 图片")
        if len(license_bytes) > 20 * 1024 * 1024: raise HTTPException(status_code=422, detail="营业执照文件不能超过 20MB")
        target = UPLOAD_ROOT / f"law-firm-{item.id}-{uuid4().hex}{suffix}"
        target.write_bytes(license_bytes)
        attachment = FileAttachment(law_firm_id=item.id, category="律所营业执照", original_name=filename, stored_name=target.name, content_type="image/*", size=len(license_bytes), path=str(target), uploader=identity["username"], remark=f"律所 {item.code} 营业执照")
        db.add(attachment); await db.flush(); item.license_attachment_id = attachment.id
    db.add(LawFirmAudit(law_firm_id=item.id, action="新建律所档案", operator=identity["username"], detail={"code": code, "name": name}))
    await db.commit(); await db.refresh(item)
    contacts = list((await db.scalars(select(LawFirmContact).where(LawFirmContact.law_firm_id == item.id).order_by(LawFirmContact.id))).all())
    return _law_firm_dict(item, await _law_firm_license(item, db), contacts)


@app.post(f"{settings.api_prefix}/law-firms", status_code=status.HTTP_201_CREATED)
async def create_law_firm(request: Request, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    content_type = (request.headers.get("content-type") or "").lower()
    if "multipart/form-data" in content_type:
        form = await request.form()
        raw: dict[str, object] = {}
        file_value: UploadFile | None = None
        for key, value in form.items():
            if hasattr(value, "read") and hasattr(value, "filename"):
                file_value = value
            else:
                raw[key] = str(value)
        if raw.get("default_contact"):
            raw["default_contact"] = json.loads(str(raw["default_contact"]))
        body = LawFirmInput.model_validate(raw)
        license_bytes = await file_value.read() if file_value else None
        return await _create_law_firm_record(body, identity, db, license_bytes=license_bytes or None, license_filename=file_value.filename if file_value else None)
    raw_body = await request.body()
    if not raw_body:
        raise HTTPException(status_code=422, detail="请求体不能为空")
    body = LawFirmInput.model_validate(json.loads(raw_body.decode("utf-8")))
    return await _create_law_firm_record(body, identity, db)


@app.put(f"{settings.api_prefix}/law-firms/{{law_firm_id}}")
async def update_law_firm(law_firm_id: int, body: LawFirmInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    item = await _law_firm_or_404(law_firm_id, db)
    code, name = body.code.strip().upper(), body.name.strip()
    duplicate = await db.scalar(select(LawFirm.id).where(LawFirm.id != item.id, or_(LawFirm.code == code, LawFirm.name == name)))
    if duplicate: raise HTTPException(status_code=409, detail="律所编号或名称已被其他档案使用")
    before = {key: getattr(item, key) for key in body.model_fields if key != "default_contact"}
    for key, value in body.model_dump(exclude={"default_contact"}).items(): setattr(item, key, code if key == "code" else name if key == "name" else value)
    item.updated_by = identity["username"]
    changed = {key: {"before": before[key], "after": getattr(item, key)} for key in before if before[key] != getattr(item, key)}
    if changed: db.add(LawFirmAudit(law_firm_id=item.id, action="修改律所档案", operator=identity["username"], detail=changed))
    await db.commit(); await db.refresh(item)
    return _law_firm_dict(item, await _law_firm_license(item, db))


@app.delete(f"{settings.api_prefix}/law-firms/{{law_firm_id}}")
async def delete_law_firm(law_firm_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    item = await _law_firm_or_404(law_firm_id, db)
    linked_case_count = await db.scalar(select(func.count(IprCaseLawFirm.id)).where(IprCaseLawFirm.law_firm_id == item.id)) or 0
    if linked_case_count:
        raise HTTPException(status_code=409, detail=f"该律所已关联 {linked_case_count} 个知识产权案件，解除关联后才能删除")
    attachment = await _law_firm_license(item, db)
    # 当前律所档案尚未允许被合同、用印、财务或文书引用；引用接入后必须先增加相应的删除阻断检查。
    contacts = (await db.scalars(select(LawFirmContact).where(LawFirmContact.law_firm_id == item.id))).all()
    db.add(LawFirmAudit(law_firm_id=item.id, action="删除律所档案", operator=identity["username"], detail={"code": item.code, "name": item.name, "contact_count": len(contacts), "license_attachment_id": attachment.id if attachment else None}))
    await db.flush()
    if attachment:
        await db.delete(attachment)
    for contact in contacts:
        await db.delete(contact)
    await db.delete(item)
    await db.commit()
    if attachment:
        try:
            Path(attachment.path).unlink(missing_ok=True)
        except OSError:
            pass
    return {"deleted": True, "id": law_firm_id}


