@app.put(f"{settings.api_prefix}/law-firms/{{law_firm_id}}/contacts/{{contact_id}}")
async def update_law_firm_contact(law_firm_id: int, contact_id: int, body: LawFirmContactInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity); firm = await _law_firm_or_404(law_firm_id, db)
    item = await db.get(LawFirmContact, contact_id)
    if not item or item.law_firm_id != firm.id: raise HTTPException(status_code=404, detail="律所联系人不存在")
    if item.id == firm.default_contact_id and not body.is_active: raise HTTPException(status_code=409, detail="默认联系人不能直接停用，请先设置其他有效联系人为默认联系人")
    before = {key: getattr(item, key) for key in body.model_fields}
    for key, value in body.model_dump().items(): setattr(item, key, value)
    item.updated_by = identity["username"]
    db.add(LawFirmAudit(law_firm_id=firm.id, action="修改律所联系人", operator=identity["username"], detail={"contact_id": item.id, "before": before, "after": body.model_dump()}))
    await db.commit(); await db.refresh(item)
    return _law_firm_contact_dict(item, is_default=item.id == firm.default_contact_id)


@app.post(f"{settings.api_prefix}/law-firms/{{law_firm_id}}/contacts/{{contact_id}}/default")
async def set_law_firm_default_contact(law_firm_id: int, contact_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity); firm = await _law_firm_or_404(law_firm_id, db)
    item = await db.get(LawFirmContact, contact_id)
    if not item or item.law_firm_id != firm.id: raise HTTPException(status_code=404, detail="律所联系人不存在")
    if not item.is_active: raise HTTPException(status_code=409, detail="停用联系人不能设为默认联系人")
    previous = firm.default_contact_id; firm.default_contact_id = item.id; firm.updated_by = identity["username"]
    db.add(LawFirmAudit(law_firm_id=firm.id, action="设置默认联系人", operator=identity["username"], detail={"before_contact_id": previous, "after_contact_id": item.id}))
    await db.commit(); await db.refresh(item)
    return _law_firm_contact_dict(item, is_default=True)


@app.post(f"{settings.api_prefix}/law-firms/{{law_firm_id}}/license", status_code=status.HTTP_201_CREATED)
async def upload_law_firm_license(law_firm_id: int, file: UploadFile = File(...), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity); firm = await _law_firm_or_404(law_firm_id, db)
    filename = Path(file.filename or "营业执照").name
    suffix = Path(filename).suffix.lower()
    if suffix not in {".jpg", ".jpeg", ".png", ".gif"}: raise HTTPException(status_code=422, detail="营业执照仅支持 JPG、PNG 或 GIF 图片")
    content = await file.read()
    if not content: raise HTTPException(status_code=422, detail="营业执照文件不能为空")
    if len(content) > 20 * 1024 * 1024: raise HTTPException(status_code=422, detail="营业执照文件不能超过 20MB")
    old_attachment = await _law_firm_license(firm, db)
    target = UPLOAD_ROOT / f"law-firm-{firm.id}-{uuid4().hex}{suffix}"
    target.write_bytes(content)
    attachment = FileAttachment(law_firm_id=firm.id, category="律所营业执照", original_name=filename, stored_name=target.name, content_type=file.content_type or "image/*", size=len(content), path=str(target), uploader=identity["username"], remark=f"律所 {firm.code} 营业执照")
    db.add(attachment); await db.flush()
    firm.license_attachment_id = attachment.id; firm.updated_by = identity["username"]
    db.add(LawFirmAudit(law_firm_id=firm.id, action="替换营业执照", operator=identity["username"], detail={"previous_attachment_id": old_attachment.id if old_attachment else None, "attachment_id": attachment.id, "name": filename}))
    if old_attachment: await db.delete(old_attachment)
    await db.commit(); await db.refresh(attachment)
    if old_attachment:
        old_path = Path(old_attachment.path)
        if old_path.is_file() and UPLOAD_ROOT.resolve() in old_path.resolve().parents: old_path.unlink(missing_ok=True)
    return _attachment_dict(attachment)


@app.get(f"{settings.api_prefix}/law-firms/{{law_firm_id}}/license/download")
async def download_law_firm_license(law_firm_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity); firm = await _law_firm_or_404(law_firm_id, db); attachment = await _law_firm_license(firm, db)
    if not attachment: raise HTTPException(status_code=404, detail="该律所尚未上传营业执照")
    path = Path(attachment.path)
    if not path.is_file() or UPLOAD_ROOT.resolve() not in path.resolve().parents: raise HTTPException(status_code=404, detail="营业执照文件不存在")
    return FileResponse(path, media_type=attachment.content_type, filename=attachment.original_name)


def _system_menu_dict(item: SystemMenu) -> dict:
    label = str(item.label or "").strip()
    if not label or label in {"---", "—", "-"}:
        label = DEFAULT_MENU_LABEL_BY_KEY.get(item.key, "未命名菜单")
    return {
        "id": item.id, "key": item.key, "parent_key": item.parent_key,
        "label": label, "description": getattr(item, "description", ""), "icon": item.icon, "sort_order": item.sort_order,
        "is_visible": item.is_visible, "is_active": item.is_active,
        "is_system": item.key in SYSTEM_MENU_ROUTE_KEYS,
        "updated_by": item.updated_by, "updated_at": item.updated_at,
    }


@app.get(f"{settings.api_prefix}/system/menus/navigation")
async def navigation_menus(identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    items = [
        item for item in (await db.scalars(
            select(SystemMenu).where(SystemMenu.is_active.is_(True), SystemMenu.is_visible.is_(True)).order_by(SystemMenu.sort_order, SystemMenu.id)
        )).all()
        if item.key in SYSTEM_MENU_ROUTE_KEYS or item.key.startswith("legacy-menu-")
    ]
    if "admin" in _identity_role_ids(identity):
        visible_keys = {item.key for item in items}
    else:
        user = await db.scalar(select(User).where(User.username == identity["username"]))
        permission = await _user_permission_payload(user, db) if user else await _permission_payload_for_identity(identity, db)
        visible_keys = {"dashboard", *permission["menu_keys"]}
        # Parent containers must remain visible for an authorized child, but
        # they are not themselves added as route grants.
        for key in list(visible_keys):
            parent_key = MENU_PARENT_BY_KEY.get(key, "")
            while parent_key:
                visible_keys.add(parent_key)
                parent_key = MENU_PARENT_BY_KEY.get(parent_key, "")
    return {"items": [_system_menu_dict(item) for item in items if item.key in visible_keys]}


@app.get(f"{settings.api_prefix}/system/menus")
async def list_system_menus(keyword: str = "", page: int | None = Query(None, ge=1), page_size: int | None = Query(None, ge=1, le=200), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    items = (await db.scalars(select(SystemMenu).order_by(SystemMenu.sort_order, SystemMenu.id))).all()
    result = [_system_menu_dict(item) for item in items]
    if keyword.strip():
        needle = keyword.strip().lower()
        result = [item for item in result if needle in " ".join(str(item.get(key) or "") for key in ("key", "parent_key", "label", "description")).lower()]
    if page is None and page_size is None:
        return {"items": result, "total": len(result)}
    current_page, current_size = page or 1, page_size or 15
    total = len(result); start = (current_page - 1) * current_size
    return {"items": result[start:start + current_size], "total": total, "page": current_page, "page_size": current_size}


@app.post(f"{settings.api_prefix}/system/menus", status_code=status.HTTP_201_CREATED)
async def create_system_menu(body: SystemMenuInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    requested_key = (body.key or "").strip()
    menu_key = requested_key or f"legacy-menu-{uuid4().hex[:12]}"
    parent_key = body.parent_key.strip()
    if requested_key and menu_key not in SYSTEM_MENU_ROUTE_KEYS:
        raise HTTPException(status_code=422, detail="菜单标识不是已实现的系统路由，不能创建菜单入口")
    if await db.scalar(select(SystemMenu.id).where(SystemMenu.key == menu_key)):
        raise HTTPException(status_code=409, detail="菜单标识已经存在")
    if parent_key and not await db.scalar(select(SystemMenu.id).where(SystemMenu.key == parent_key)):
        raise HTTPException(status_code=422, detail="父级菜单不存在")
    item = SystemMenu(
        key=menu_key,
        parent_key=parent_key,
        label=body.label.strip(),
        icon=body.icon.strip(),
        sort_order=body.sort_order,
        is_visible=body.is_visible,
        is_active=body.is_active,
        updated_by=identity["username"],
    )
    if hasattr(item, "description"):
        item.description = body.description.strip()
    db.add(item)
    await db.flush()
    await _system_audit(db, identity, "创建系统菜单", f"系统菜单:{item.key}", {"id": item.id, "key": item.key})
    await db.commit()
    await db.refresh(item)
    return _system_menu_dict(item)


@app.patch(f"{settings.api_prefix}/system/menus/{{menu_id}}")
async def update_system_menu(menu_id: int, body: SystemMenuUpdate, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    item = await db.get(SystemMenu, menu_id)
    if not item: raise HTTPException(status_code=404, detail="菜单不存在")
    changes = body.model_dump(exclude_none=True)
    if item.key in {"dashboard", "system", "system-management"} and (changes.get("is_active") is False or changes.get("is_visible") is False):
        raise HTTPException(status_code=422, detail="控制台和系统管理入口不能隐藏或停用")
    for key, value in changes.items():
        setattr(item, key, value.strip() if isinstance(value, str) else value)
    item.updated_by = identity["username"]
    await _system_audit(db, identity, "更新系统菜单", f"系统菜单:{item.key}", {"id": item.id, "key": item.key})
    await db.commit(); await db.refresh(item)
    return _system_menu_dict(item)


@app.delete(f"{settings.api_prefix}/system/menus/{{menu_id}}", status_code=status.HTTP_204_NO_CONTENT)
async def delete_system_menu(menu_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    item = await db.get(SystemMenu, menu_id)
    if not item:
        raise HTTPException(status_code=404, detail="菜单不存在")
    if item.key in {key for key, *_ in DEFAULT_SYSTEM_MENUS}:
        raise HTTPException(status_code=422, detail="系统预置菜单不能删除")
    if await db.scalar(select(SystemMenu.id).where(SystemMenu.parent_key == item.key)):
        raise HTTPException(status_code=409, detail="请先删除该菜单的子菜单")
    await _system_audit(db, identity, "删除系统菜单", f"系统菜单:{item.key}", {"id": item.id, "key": item.key})
    await db.delete(item)
    await db.commit()


@app.post(f"{settings.api_prefix}/system/menus/reset")
async def reset_system_menus(identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    defaults = {key: (parent_key, label, icon, sort_order) for key, parent_key, label, icon, sort_order in DEFAULT_SYSTEM_MENUS}
    items = (await db.scalars(select(SystemMenu))).all()
    by_key = {item.key: item for item in items}
    for item in items:
        if item.key not in defaults:
            item.is_visible = False; item.is_active = False; item.updated_by = identity["username"]
    for key, (parent_key, label, icon, sort_order) in defaults.items():
        item = by_key.get(key)
        if not item:
            db.add(SystemMenu(key=key, parent_key=parent_key, label=label, icon=icon, sort_order=sort_order, updated_by=identity["username"]))
            continue
        item.parent_key = parent_key; item.label = label; item.icon = icon; item.sort_order = sort_order
        item.is_visible = True; item.is_active = True; item.updated_by = identity["username"]
    await _system_audit(db, identity, "重置系统菜单", "系统菜单:重置", {"count": len(defaults)})
    await db.commit()
    refreshed = (await db.scalars(select(SystemMenu).order_by(SystemMenu.sort_order, SystemMenu.id))).all()
    return {"items": [_system_menu_dict(item) for item in refreshed], "total": len(refreshed)}


def _role_permission_dict(item: RolePermission) -> dict:
    menu_keys, action_keys = _split_role_permission_keys(item.menu_keys)
    if item.role == "admin":
        config = DEFAULT_ROLE_PERMISSIONS["admin"]
        return {"role": item.role, "display_name": config["display_name"], "data_scope": config["data_scope"], "menu_keys": list(MENU_KEYS), "action_keys": [item["code"] for item in SYSTEM_ACTION_DEFINITIONS], "field_keys": list(FIELD_KEYS), "updated_at": item.updated_at}
    return {"role": item.role, "display_name": item.display_name, "data_scope": item.data_scope, "menu_keys": menu_keys, "action_keys": action_keys, "field_keys": item.field_keys, "updated_at": item.updated_at}


@app.get(f"{settings.api_prefix}/system/role-permissions")
async def list_role_permissions(
    keyword: str = "", page: int | None = Query(None, ge=1), page_size: int | None = Query(None, ge=1, le=200),
    identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db),
):
    _require_admin(identity)
    all_items = list((await db.scalars(select(RolePermission).order_by(RolePermission.id))).all())
    items = all_items
    if keyword.strip():
        needle = keyword.strip().casefold()
        items = [item for item in items if needle in " ".join((item.role, item.display_name, item.data_scope)).casefold()]
    response_items = [_role_permission_dict(item) for item in items]
    response = {"items": response_items}
    if page is not None or page_size is not None or keyword.strip():
        current_page, current_size = page or 1, page_size or 15
        total = len(items)
        start = (current_page - 1) * current_size
        response.update({
            "items": response_items[start:start + current_size], "total": total,
            "page": current_page, "page_size": current_size,
            "pages": (total + current_size - 1) // current_size if total else 0,
        })
    legacy_keys = list((await db.scalars(select(SystemMenu.key).where(~SystemMenu.key.in_(SYSTEM_MENU_ROUTE_KEYS)))).all())
    tree_permission = next((item for item in all_items if item.role == identity.get("role")), all_items[0] if all_items else None)
    response.update({"available_menu_keys": [*MENU_KEYS, *legacy_keys], "available_field_keys": FIELD_KEYS, "permission_tree": await _system_permission_tree(db, tree_permission)})
    return response


@app.patch(f"{settings.api_prefix}/system/role-permissions/{{role}}")
async def update_role_permission(role: str, body: RolePermissionUpdate, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    if role not in DEFAULT_ROLE_PERMISSIONS:
        raise HTTPException(status_code=404, detail="角色不存在")
    data_scope = body.data_scope.strip()
    if data_scope not in ROLE_DATA_SCOPES:
        raise HTTPException(status_code=422, detail="数据范围无效")
    legacy_keys = set((await db.scalars(select(SystemMenu.key).where(~SystemMenu.key.in_(SYSTEM_MENU_ROUTE_KEYS)))).all())
    all_menu_keys = set(MENU_KEYS) | legacy_keys
    invalid = sorted(set(body.menu_keys) - all_menu_keys)
    if invalid:
        raise HTTPException(status_code=422, detail=f"无效菜单权限：{', '.join(invalid)}")
    menu_keys = list(dict.fromkeys(body.menu_keys))
    item = await db.scalar(select(RolePermission).where(RolePermission.role == role))
    _, existing_actions = _split_role_permission_keys(item.menu_keys if item else [])
    action_keys = list(dict.fromkeys(body.action_keys if body.action_keys is not None else (existing_actions or ([item["code"] for item in SYSTEM_ACTION_DEFINITIONS] if role == "admin" else []))))
    invalid_actions = sorted(set(action_keys) - set(SYSTEM_ACTION_BY_CODE))
    if invalid_actions:
        raise HTTPException(status_code=422, detail=f"无效动作权限：{', '.join(invalid_actions)}")
    if "user-center" not in menu_keys:
        raise HTTPException(status_code=422, detail="用户中心为基础权限，不能移除")
    if role == "admin" and set(menu_keys) != all_menu_keys:
        raise HTTPException(status_code=422, detail="系统管理员必须保留全部菜单权限")
    if role == "admin" and data_scope != DEFAULT_ROLE_PERMISSIONS["admin"]["data_scope"]:
        raise HTTPException(status_code=422, detail="系统管理员必须保留全所数据权限")
    invalid_fields = sorted(set(body.field_keys) - set(FIELD_KEYS))
    if invalid_fields: raise HTTPException(status_code=422, detail=f"无效字段权限：{', '.join(invalid_fields)}")
    field_keys = list(dict.fromkeys(body.field_keys))
    if role == "admin" and set(field_keys) != set(FIELD_KEYS): raise HTTPException(status_code=422, detail="系统管理员必须保留全部字段权限")
    if role == "admin" and body.action_keys is not None and set(action_keys) != set(SYSTEM_ACTION_BY_CODE):
        raise HTTPException(status_code=422, detail="系统管理员必须保留全部动作权限")
    stored_menu_keys = menu_keys + [f"@action:{key}" for key in action_keys]
    if not item:
        config = DEFAULT_ROLE_PERMISSIONS[role]
        item = RolePermission(role=role, display_name=config["display_name"], data_scope=data_scope, menu_keys=stored_menu_keys, field_keys=field_keys)
        db.add(item)
    else:
        item.data_scope = data_scope
        item.menu_keys = stored_menu_keys
        item.field_keys = field_keys
    await _system_audit(db, identity, "更新角色权限", f"角色权限:{role}", {"role": role, "menu_keys": menu_keys, "action_keys": action_keys})
    await db.commit(); await db.refresh(item)
    return _role_permission_dict(item)


DASHBOARD_SUPPLEMENT_EVIDENCE_STATUSES = {
    "一审补充证据",
    "二审补充证据",
    "再审补充证据",
}
DASHBOARD_SUPPLEMENT_OPINION_STATUSES = {
    "一审补充代理意见",
    "二审补充代理意见",
}
DASHBOARD_CASE_QUEUES = {"supplement_evidence", "supplement_opinion", "urgent"}


def _case_phase_changed_date(item: BusinessRecord) -> date:
    data = item.data or {}
    legacy = data.get("legacy_record") if isinstance(data.get("legacy_record"), dict) else {}
    for raw in (
        data.get("phase_changed_at"),
        legacy.get("PhaseChangedTime"),
        legacy.get("ChangeTime"),
        data.get("case_register_date"),
        item.created_at,
    ):
        if isinstance(raw, datetime):
            return raw.date()
        if isinstance(raw, date):
            return raw
        text = str(raw or "").strip()
        if not text:
            continue
        try:
            return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
        except ValueError:
            try:
                return date.fromisoformat(text[:10])
            except ValueError:
                continue
    return date.today()


def _case_phase_changed_days(item: BusinessRecord, *, as_of: date | None = None) -> int:
    return max(((as_of or date.today()) - _case_phase_changed_date(item)).days, 0)


def _is_urgent_case(item: BusinessRecord, *, as_of: date | None = None) -> bool:
    return _case_phase_changed_days(item, as_of=as_of) > 365


def _matches_dashboard_case_queue(item: BusinessRecord, queue: str) -> bool:
    data = item.data or {}
    legacy = data.get("legacy_record") if isinstance(data.get("legacy_record"), dict) else {}
    case_type = str(data.get("case_type") or "").strip()
    status_name = str(
        data.get("case_phase_name")
        or legacy.get("CasePhaseName")
        or item.status
        or ""
    ).strip()
    if queue == "supplement_evidence":
        return case_type in {"民事争议", "民事案件"} and status_name in DASHBOARD_SUPPLEMENT_EVIDENCE_STATUSES
    if queue == "supplement_opinion":
        return case_type in {"民事争议", "民事案件"} and status_name in DASHBOARD_SUPPLEMENT_OPINION_STATUSES
    if queue == "urgent":
        return _is_urgent_case(item)
    return False
def _dashboard_case_date(record: BusinessRecord) -> datetime:
    def as_utc_naive(value: datetime) -> datetime:
        if value.tzinfo is not None:
            return value.astimezone(timezone.utc).replace(tzinfo=None)
        return value

    data = record.data or {}
    legacy = data.get("legacy_record") if isinstance(data.get("legacy_record"), dict) else {}
    raw = data.get("case_register_date") or legacy.get("CaseRegisterDate")
    if isinstance(raw, datetime):
        return as_utc_naive(raw)
    if isinstance(raw, date):
        return datetime.combine(raw, time.min)
    text = str(raw or "").strip()
    if text:
        try:
            return as_utc_naive(datetime.fromisoformat(text.replace("Z", "+00:00")))
        except ValueError:
            pass
    return as_utc_naive(record.created_at) if record.created_at else datetime.min


def _dashboard_text(value: object) -> str:
    values = _contract_person_values(value)
    return "、".join(dict.fromkeys(values))


def _dashboard_people(
    users_by_username: dict[str, User],
    *candidate_groups: object,
) -> str:
    for candidate in candidate_groups:
        values = _contract_person_values(candidate)
        if not values:
            continue
        labels: list[str] = []
        for value in values:
            if value.lower() == "system":
                continue
            else:
                user = users_by_username.get(value.lower())
                label = (
                    _valid_contract_chinese_person_name(user.display_name)
                    if user
                    else _valid_contract_chinese_person_name(value)
                )
            if label and label not in labels:
                labels.append(label)
        if labels:
            return "、".join(labels)
    return ""


def _dashboard_customer_for_case(
    record: BusinessRecord,
    customers_by_id: dict[int, BusinessRecord],
    customers_by_no: dict[str, list[BusinessRecord]],
    customers_by_name: dict[str, list[BusinessRecord]],
) -> BusinessRecord | None:
    data = record.data or {}
    customer, _ = _customer_reference_from_maps(
        record.customer,
        data,
        customers_by_id,
        customers_by_no,
        customers_by_name,
    )
    return customer


def _dashboard_latest_case_row(
    record: BusinessRecord,
    customer: BusinessRecord | None,
    users_by_username: dict[str, User],
) -> dict:
    data = record.data or {}
    legacy = data.get("legacy_record") if isinstance(data.get("legacy_record"), dict) else {}
    customer_data = customer.data or {} if customer else {}
    manager_values = (
        customer_data.get("customer_managers")
        or ([customer.owner] if customer and customer.owner else [])
    )
    registered_at = _dashboard_case_date(record)
    return {
        "case_no": record.serial_no,
        "stage": str(data.get("case_phase_name") or legacy.get("CasePhaseName") or record.status or ""),
        "plaintiff": _dashboard_text(
            data.get("plaintiff") or data.get("plaintiffs") or legacy.get("AppellantNames") or record.customer
        ),
        "defendant": _dashboard_text(
            data.get("opponent") or data.get("defendant") or data.get("defendants") or legacy.get("AppelleeNames")
        ),
        "date": registered_at.date().isoformat() if registered_at != datetime.min else "",
        "manager": _dashboard_people(
            users_by_username,
            data.get("customer_manager_usernames"),
            data.get("customer_manager_username"),
            data.get("customer_managers"),
            data.get("customer_manager"),
            manager_values,
            data.get("customer_manager_display_names"),
            data.get("customer_manager_display_name"),
            customer_data.get("customer_manager_display_names"),
            customer_data.get("customer_manager_display_name"),
            legacy.get("CoordinatorName"),
        ),
        "lawyer": _dashboard_people(
            users_by_username,
            data.get("hearing_lawyer_usernames"),
            data.get("hearing_lawyer_username"),
            data.get("hearing_lawyers"),
            data.get("hearing_lawyer"),
            data.get("hearing_lawyer_display_names"),
            data.get("hearing_lawyer_display_name"),
            legacy.get("CourtLawyerName"),
        ),
        "agent": _dashboard_people(
            users_by_username,
            data.get("handling_lawyer_usernames"),
            data.get("handling_lawyers"),
            data.get("handling_lawyer_display_names"),
            data.get("handling_lawyer_display_name"),
            legacy.get("CaseLawyerName"),
        ),
        "assistant": _dashboard_people(
            users_by_username,
            data.get("assistant_usernames"),
            data.get("assistant_username"),
            data.get("assistants"),
            data.get("assistant"),
            data.get("assistant_display_names"),
            data.get("assistant_display_name"),
            legacy.get("CaseAssistantName"),
        ),
    }


@app.get(f"{settings.api_prefix}/dashboard")
async def dashboard(identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    # Keep dashboard task counts on the same lifecycle snapshot as /tasks.
    # Otherwise an auto-completed handoff can remain in the dashboard after it
    # has already disappeared from the user's accepted-task queue.
    await _apply_task_auto_completion(db)
    await _apply_task_overdue_performance(db)
    scope = await _record_scope_conditions(identity, db)
    records = (await db.scalars(select(BusinessRecord).where(*scope))).all()
    by_module = {module: [item for item in records if item.module == module] for module in {"case", "task", "finance", "refund", "contract", "clue", "seal"}}
    cases, tasks = by_module["case"], by_module["task"]
    finances = by_module["finance"] + by_module["refund"]
    username = identity["username"]
    pending_statuses = {"待审批", "审批中", "待审核"}
    def count(rows, statuses, owner_only=False, predicate=None):
        return sum(item.status in statuses and (not owner_only or item.owner == username) and (predicate is None or predicate(item.data or {})) for item in rows)
    def fee_match(word): return lambda data: word in str(data.get("fee_type") or data.get("expense_scope") or "")
    official = lambda data: any(word in str(data.get("fee_type") or data.get("expense_scope") or "") for word in ("官方", "官费", "律所"))
    def amount(value: object) -> float:
        try:
            return float(value or 0)
        except (TypeError, ValueError):
            return 0.0
    unpaid_official = await _fee_query_rows(
        identity, db, scope="mine", unpaid_official=True,
    )
    receivable_details = await _receivable_detail_projection(identity, db, list(records))
    personal_official_receivables = [
        item for item in receivable_details
        if item["fee_category"] == "official" and item["owner"] == username
    ]
    unpaid_amount = sum(item["remaining_amount"] for item in personal_official_receivables)
    pending_refunds = await _refund_case_fee_rows(identity, db)
    def case_signal(item: BusinessRecord, *words: str) -> bool:
        data = item.data or {}
        values = [
            item.status, data.get("case_phase"), data.get("execution_status"),
            data.get("required_action"), data.get("review_action"), data.get("supplement_type"),
        ]
        return any(word in str(value or "") for word in words for value in values)
    supplement_evidence = [item for item in cases if _matches_dashboard_case_queue(item, "supplement_evidence")]
    supplement_opinion = [item for item in cases if _matches_dashboard_case_queue(item, "supplement_opinion")]
    personal_cases = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "case",
        _case_personal_scope_condition(username),
    ))).all())
    appeal_phases = {"一审等待上诉", "待上诉"}
    pending_appeal = [
        item for item in personal_cases
        if str(item.status or "").strip() in appeal_phases
    ]
    pending_execution = [item for item in cases if _is_pending_execution_case(item)]
    urgent_cases = [item for item in cases if _matches_dashboard_case_queue(item, "urgent")]
    metrics = [
        {
            "key": "official-fee-unpaid", "label": "待缴官费",
            "value": f"{len(unpaid_official)}件", "tone": "amber",
            "route": "finance-fee-query",
            "query": {"scope": "mine", "unpaid_official": True},
        },
        {"key": "refund-pending", "label": "待退费", "value": f"{len(pending_refunds)}件", "tone": "cyan", "route": "finance-refund"},
        {"key": "evidence-supplement", "label": "补充证据", "value": f"{len(supplement_evidence)}件", "tone": "green", "route": "case-company-supplement-evidence"},
        {"key": "opinion-supplement", "label": "补充意见", "value": f"{len(supplement_opinion)}件", "tone": "blue", "route": "case-company-supplement-opinion"},
        {"key": "appeal-pending", "label": "待上诉", "value": f"{len(pending_appeal)}件", "tone": "red", "route": "case-mine-appeal"},
        {"key": "execution-pending", "label": "待执行", "value": f"{len(pending_execution)}件", "tone": "purple", "route": "case-company-execution"},
        {"key": "urgent-cases", "label": "紧急案件", "value": f"{len(urgent_cases)}件", "tone": "orange", "route": "case-company-urgent"},
        {
            "key": "official-fee-unreceived", "label": "未到官费金额",
            "value": f"{unpaid_amount:.2f}元", "tone": "navy",
            "route": "contract-receivable-detail",
            "detail_context": {
                "contract_no": "", "return_view": "contract-receivable-mine",
                "amount_filter": "official-unreceived", "owner": username,
            },
        },
    ]
    todo_specs = [
        ("待处理任务", tasks, {"待接收", "待处理", "处理中"}, None, "待审批官方费用", finances, pending_statuses, official),
        ("待审批线索", by_module["clue"], pending_statuses, None, "待审批内部费用", finances, pending_statuses, fee_match("内部")),
        ("待审批合同", by_module["contract"], pending_statuses, None, "待审批结算费用", finances, pending_statuses, fee_match("结算")),
        ("待审批用印", by_module["seal"], pending_statuses, None, "待审批归档费用", finances, pending_statuses, fee_match("归档")),
        ("待审核归档", cases, {"待归档审核", "亏损内审", "亏损审核"}, None, "待审核预损费用", finances, pending_statuses, fee_match("预损")),
    ]
    todos = [[left, count(left_rows, left_states, True, left_pred), count(left_rows, left_states, False, left_pred), right, count(right_rows, right_states, True, right_pred), count(right_rows, right_states, False, right_pred)] for left, left_rows, left_states, left_pred, right, right_rows, right_states, right_pred in todo_specs]

    # The legacy dashboard's blue number is the signed-in user's actionable
    # queue; the orange number is that user's rejected/returned queue.  Neither
    # number is a company-wide total, even for administrators.
    personal_tasks = [
        item for item in tasks
        if not _is_investigation_task(item)
        and (
            item.owner == username
            or str((item.data or {}).get("initiator") or "").strip() == username
        )
    ]
    def task_is_effectively_pending(item: BusinessRecord) -> bool:
        # The task centre presents an overdue task in the processing tab even
        # when the stored workflow state is still 待接收/待处理.
        if _task_dict(item)["status"] not in {"待接收", "待处理"}:
            return False
        data = item.data or {}
        if item.status != "待接收" or data.get("handoff_restarted"):
            return True
        auto_complete_at = str(data.get("handoff_auto_complete_at") or "").strip()
        if not auto_complete_at:
            return True
        try:
            return date.fromisoformat(auto_complete_at) > date.today()
        except ValueError:
            return True
    personal_todo_counts = {
        "待处理任务": (
            sum(item.owner == username and task_is_effectively_pending(item) for item in personal_tasks),
            sum(
                str((item.data or {}).get("initiator") or "").strip() == username
                and item.status == "已拒绝"
                for item in personal_tasks
            ),
        ),
        "待审批合同": (0, 0),
        "待审批线索": (
            sum(item.status == "待审批" for item in by_module["clue"]),
            sum(item.status in {"已驳回", "已拒绝"} for item in by_module["clue"]),
        ),
        "待审批用印": (0, 0),
        "待审核归档": (0, 0),
    }
    pending_contract_ids = set((await db.scalars(select(ContractApprovalStep.contract_record_id).where(
        ContractApprovalStep.approver == username,
        ContractApprovalStep.status == "待审批",
    ))).all())
    personal_todo_counts["待审批合同"] = (
        int(await db.scalar(select(func.count()).select_from(BusinessRecord).where(
            BusinessRecord.module == "contract",
            BusinessRecord.id.in_(pending_contract_ids),
            BusinessRecord.status.in_(pending_statuses),
        )) or 0) if pending_contract_ids else 0,
        int(await db.scalar(select(func.count()).select_from(BusinessRecord).where(
            BusinessRecord.module == "contract",
            BusinessRecord.owner == username,
            BusinessRecord.status.in_({"已拒绝", "已驳回"}),
        )) or 0),
    )

    seal_context = await _seal_authorization_context(identity, db)
    seal_approver = func.trim(func.coalesce(BusinessRecord.data["approver"].as_string(), ""))
    personal_todo_counts["待审批用印"] = (
        int(await db.scalar(select(func.count()).select_from(BusinessRecord).where(
            BusinessRecord.module == "seal",
            BusinessRecord.status == "待审批",
            or_(seal_approver == "", seal_approver == username),
        )) or 0) if seal_context["approve"] or seal_context["reject"] else 0,
        int(await db.scalar(select(func.count()).select_from(BusinessRecord).where(
            BusinessRecord.module == "seal",
            BusinessRecord.owner == username,
            BusinessRecord.status == "已拒绝",
        )) or 0),
    )

    archive_action_allowed = await _case_action_granted(identity, db, "case.archive.review")
    archive_scope = await _record_scope_conditions(identity, db)
    archive_submitter = func.trim(func.coalesce(BusinessRecord.data["archive_submitter"].as_string(), ""))
    archive_reviewer = func.trim(func.coalesce(BusinessRecord.data["archive_reviewer"].as_string(), ""))
    archive_internal_reviewer = func.trim(func.coalesce(BusinessRecord.data["archive_internal_reviewer"].as_string(), ""))
    archive_assigned_to_user = or_(
        archive_reviewer == username,
        archive_internal_reviewer == username,
        and_(archive_reviewer == "", archive_internal_reviewer == "", BusinessRecord.owner == username),
    )
    personal_todo_counts["待审核归档"] = (
        int(await db.scalar(select(func.count()).select_from(BusinessRecord).where(
            BusinessRecord.module == "case",
            BusinessRecord.status.in_({"待归档审核", "亏损内审", "亏损审核"}),
            archive_assigned_to_user,
            archive_submitter != username,
            *archive_scope,
        )) or 0) if archive_action_allowed else 0,
        int(await db.scalar(select(func.count()).select_from(BusinessRecord).where(
            BusinessRecord.module == "case",
            archive_submitter == username,
            or_(
                BusinessRecord.status == "亏损归档拒绝",
                func.trim(func.coalesce(BusinessRecord.data["archive_reject_reason"].as_string(), "")) != "",
            ),
            *archive_scope,
        )) or 0),
    )
    for todo in todos:
        if todo[0] in personal_todo_counts:
            todo[1], todo[2] = personal_todo_counts[todo[0]]
    current_month = date.today().replace(day=1); month_keys = []
    for offset in range(9, -1, -1):
        year, month = current_month.year, current_month.month - offset
        while month <= 0: year -= 1; month += 12
        month_keys.append(f"{year:04d}-{month:02d}")
    case_trend = [{"date": key, "value": sum(item.created_at.strftime("%Y-%m") == key for item in cases)} for key in month_keys]
    stage_groups = [("立案待分配", lambda s: s in {"新案待分配", "立案待分配"}, "#f7474c"), ("文书准备", lambda s: "文书准备" in s, "#46b8b8"), ("一审", lambda s: "一审" in s, "#ffb45a"), ("二审", lambda s: "二审" in s, "#7f70b3"), ("再审", lambda s: "再审" in s, "#98a5b7"), ("执行", lambda s: "执行" in s, "#303030")]
    stage_counts = {label: 0 for label, _, _ in stage_groups}; other_count = 0
    for item in cases:
        matched = next((label for label, match, _ in stage_groups if match(item.status)), None)
        if matched: stage_counts[matched] += 1
        else: other_count += 1
    civil_distribution = [{"label": label, "value": stage_counts[label], "color": color} for label, _, color in stage_groups]
    if other_count: civil_distribution.append({"label": "其他", "value": other_count, "color": "#c5cbd3"})
    case_map = {item.id: item for item in cases}; visible_case_ids = set(case_map)
    today = date.today()
    cutoff = today + timedelta(days=100)
    projected_hearings = {
        item.id: projected
        for item in cases
        if (projected := _dashboard_case_hearing(item, today, cutoff)) is not None
    }
    hearing_rows = (await db.scalars(select(HearingSchedule).where(
        HearingSchedule.case_record_id.in_(visible_case_ids),
        HearingSchedule.hearing_date >= today,
        HearingSchedule.hearing_date <= cutoff,
    ).order_by(HearingSchedule.hearing_date, HearingSchedule.hearing_time))).all() if visible_case_ids else []
    hearings = list(projected_hearings.values())
    for item in hearing_rows:
        if item.case_record_id in projected_hearings:
            continue
        case = case_map[item.case_record_id]; data = case.data or {}
        hearings.append({"case_record_id": case.id, "weekday": "星期" + "一二三四五六日"[item.hearing_date.weekday()], "date": str(item.hearing_date), "time": item.hearing_time, "court": item.court, "case_no": case.serial_no, "client": case.customer, "lawyer": item.hearing_lawyer or data.get("hearing_lawyer", ""), "agent": ",".join(data.get("handling_lawyers", [])), "assistant": data.get("assistant", ""), "hearing_type": item.hearing_type, "courtroom": item.courtroom})
    hearings.sort(key=lambda item: (item["date"], item["time"], item["case_no"]))
    hearings = hearings[:13]
    latest_case_records = sorted(cases, key=lambda value: (_dashboard_case_date(value), value.id), reverse=True)[:13]
    customer_ids: set[int] = set()
    customer_nos: set[str] = set()
    customer_names: set[str] = set()
    person_usernames: set[str] = set()
    for item in latest_case_records:
        data = item.data or {}
        try:
            customer_id = int(data.get("customer_record_id") or data.get("customer_id") or 0)
        except (TypeError, ValueError):
            customer_id = 0
        if customer_id:
            customer_ids.add(customer_id)
        if customer_no := str(data.get("customer_no") or "").strip():
            customer_nos.add(customer_no)
        if item.customer:
            customer_names.add(_normalized_customer_name(item.customer))
        person_usernames.update(_record_person_usernames(item))
        for person_key in (
            "customer_manager", "customer_managers", "customer_manager_username", "customer_manager_usernames",
            "hearing_lawyer", "hearing_lawyers",
            "hearing_lawyer_username", "hearing_lawyer_usernames", "handling_lawyers",
            "handling_lawyer_usernames", "assistant", "assistants", "assistant_username",
            "assistant_usernames",
        ):
            person_usernames.update(_contract_person_values(data.get(person_key)))
    customer_conditions = []
    if customer_ids:
        customer_conditions.append(BusinessRecord.id.in_(customer_ids))
    if customer_nos:
        customer_conditions.append(BusinessRecord.serial_no.in_(customer_nos))
    if customer_names:
        customer_conditions.append(BusinessRecord.title.in_({item.customer for item in latest_case_records if item.customer}))
    related_customers = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "customer", or_(*customer_conditions),
    ))).all()) if customer_conditions else []
    customers_by_id = {item.id: item for item in related_customers}
    customers_by_no: dict[str, list[BusinessRecord]] = {}
    customers_by_name: dict[str, list[BusinessRecord]] = {}
    for item in related_customers:
        customers_by_no.setdefault(str(item.serial_no or "").strip(), []).append(item)
        customers_by_name.setdefault(_normalized_customer_name(item.title), []).append(item)
    for customer in related_customers:
        person_usernames.add(customer.owner)
        person_usernames.update(_contract_person_values((customer.data or {}).get("customer_managers")))
    users_by_username = await _user_display_map(person_usernames, db)
    latest_cases = [
        _dashboard_latest_case_row(
            item,
            _dashboard_customer_for_case(item, customers_by_id, customers_by_no, customers_by_name),
            users_by_username,
        )
        for item in latest_case_records
    ]
    return {"metrics": metrics, "todos": todos, "case_trend": case_trend, "civil_distribution": civil_distribution, "hearings": hearings, "latest_cases": latest_cases, "source": "realtime"}


@app.get(f"{settings.api_prefix}/search")
async def global_search(q: str = Query(min_length=2, max_length=100), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    keyword = q.strip(); like = f"%{keyword}%"
    permission = await _permission_payload_for_identity(identity, db)
    records = (await db.scalars(select(BusinessRecord).where(or_(BusinessRecord.serial_no.ilike(like), BusinessRecord.title.ilike(like), BusinessRecord.customer.ilike(like), BusinessRecord.owner.ilike(like), BusinessRecord.description.ilike(like)), *(await _record_scope_conditions(identity, db))).order_by(BusinessRecord.updated_at.desc()).limit(50))).all()
    records = [record for record in records if _record_module_menu_allowed(record.module, identity, permission)]
    document_menu_keys = set(permission.get("menu_keys") or [])
    can_search_attachments = "documents-files" in document_menu_keys
    can_search_templates = "documents-template" in document_menu_keys
    attachments = (await db.scalars(select(FileAttachment).where(or_(FileAttachment.original_name.ilike(like), FileAttachment.remark.ilike(like))).order_by(FileAttachment.created_at.desc()).limit(20))).all() if can_search_attachments else []
    attachments = await _filter_visible_attachments(attachments, identity, db) if attachments else []
    templates = (await db.scalars(select(DocumentTemplate).where(or_(DocumentTemplate.name.ilike(like), DocumentTemplate.description.ilike(like))).order_by(DocumentTemplate.updated_at.desc()).limit(20))).all() if can_search_templates else []
    route_map = {"customer": "customer-company", "contract": "contract-mine", "case": "case-company", "task": "task-company", "clue": "clue", "notary": "notary", "evidence": "evidence", "seal": "seal-my", "finance": "finance-fee-query", "finance_package": "finance-fee-query", "finance_settlement": "finance-fee-query", "finance_archive_settlement": "finance-fee-query", "invoice": "finance-invoice-mine", "refund": "finance-refund", "sms": "case-company", "document": "documents-register", "hr": "hr-all", "warehouse": "warehouse", "report": "reports"}
    items = [{"type": "record", "id": x.id, "module": x.module, "route": route_map.get(x.module, "dashboard"), "serial_no": x.serial_no, "title": x.title, "subtitle": x.customer or x.description, "status": x.status, "updated_at": x.updated_at, "related_id": (x.data or {}).get("case_id") if x.module == "sms" else None, "related_serial_no": (x.data or {}).get("case_no", "") if x.module == "sms" else ""} for x in records]
    items.extend({"type": "attachment", "id": x.id, "module": "attachment", "route": "documents-files", "serial_no": "附件", "title": x.original_name, "subtitle": f"{x.category}｜{x.remark}", "status": "", "updated_at": x.created_at} for x in attachments)
    items.extend({"type": "template", "id": x.id, "module": "template", "route": "documents-template", "serial_no": "模板", "title": x.name, "subtitle": f"{x.category}｜{x.description}", "status": "启用" if x.is_active else "停用", "updated_at": x.updated_at} for x in templates)
    return {"query": keyword, "items": items, "total": len(items)}


def _notification_dict(item: Notification, users_by_username: dict[str, User] | None = None) -> dict:
    users = users_by_username or {}
    return {
        "id": item.id, "source_type": item.source_type, "source_id": item.source_id,
        "sender": item.sender, "sender_display_name": _person_reference_display(item.sender, users)[0],
        "recipient": item.recipient, "recipient_display_name": _person_reference_display(item.recipient, users)[0],
        "notification_type": item.notification_type, "title": item.title, "content": item.content,
        "level": item.level, "is_read": item.is_read, "read_at": item.read_at,
        "dingtalk_status": item.dingtalk_status, "dingtalk_sent_at": item.dingtalk_sent_at, "created_at": item.created_at,
    }


async def _dispatch_dingtalk_notifications() -> None:
    if not settings.dingtalk_notifications_enabled or not dingtalk_client.configured:
        return
    async with SessionLocal() as db:
        notices = (await db.scalars(
            select(Notification).where(
                Notification.is_read.is_(False),
                Notification.recipient_deleted.is_(False),
                Notification.dingtalk_status.in_(("pending", "failed")),
                Notification.dingtalk_attempts < 5,
            ).order_by(Notification.id).limit(50)
        )).all()
        if not notices:
            return
        usernames = {notice.recipient for notice in notices}
        users = (await db.scalars(select(User).where(User.username.in_(usernames), User.is_active.is_(True)))).all()
        users_by_username = {user.username: user for user in users}
        for notice in notices:
            user = users_by_username.get(notice.recipient)
            ding_user_id = str(((user.profile if user else {}) or {}).get("dingtalk_user_id") or "").strip()
            if not ding_user_id:
                continue
            try:
                await dingtalk_client.send_work_notification(ding_user_id, notice.title, notice.content)
                notice.dingtalk_status = "sent"
                notice.dingtalk_sent_at = datetime.now()
                notice.dingtalk_error = ""
            except (DingTalkError, httpx.HTTPError, ValueError) as exc:
                notice.dingtalk_status = "failed"
                notice.dingtalk_attempts = int(notice.dingtalk_attempts or 0) + 1
                notice.dingtalk_error = str(exc)[:500]
                logger.warning("DingTalk notification %s failed: %s", notice.id, exc)
        await db.commit()


async def _dingtalk_notification_loop() -> None:
    while True:
        try:
            await _dispatch_dingtalk_notifications()
        except Exception:
            logger.exception("DingTalk notification loop failed")
        await asyncio.sleep(10)


async def _sync_notifications(identity: dict, db: AsyncSession) -> None:
    username = identity["username"]; today = date.today(); candidates: list[dict] = []
    task_terminal_statuses = ["已完成", "待确认", "已验收", "已拒绝", "已撤回", "已停止", "已取消"]
    all_tasks = list((await db.scalars(select(BusinessRecord).where(BusinessRecord.module == "task"))).all())
    tasks = [task for task in all_tasks if task.status not in task_terminal_statuses]
    terminal_task_ids = {task.id for task in all_tasks if task.status in task_terminal_statuses}
    current_user = await db.scalar(select(User).where(User.username == username))
    stale = (await db.scalars(select(Notification).where(Notification.recipient == username, Notification.source_type.in_(["task", "finance", "contract", "case"])))).all()
    existing_record_ids = set((await db.scalars(select(BusinessRecord.id))).all())
    if identity.get("role") != "admin":
        visible_tasks = [task for task in all_tasks if _is_task_participant(task, identity) or (identity.get("role") == "manager" and current_user and task.department == current_user.department)]
        tasks = [task for task in tasks if _is_task_participant(task, identity) or (identity.get("role") == "manager" and current_user and task.department == current_user.department)]
        visible_ids = await _visible_record_ids(identity, db)
        visible_task_ids = {task.id for task in visible_tasks}
    else:
        visible_ids = existing_record_ids
        visible_task_ids = {task.id for task in all_tasks}
    for notice in stale:
        is_auto_reminder = (
            (notice.source_type == "task" and notice.source_key.startswith("task-") and not notice.source_key.startswith(("task-history-", "task-message-")))
            or notice.source_key.startswith(("finance-approval-", "contract-approval-", "hearing-"))
        )
        # 旧版本的自动提醒键是全局唯一键，同一业务只能被第一个访问提醒页的
        # 用户取得。迁移为收件人维度，确保管理员与每个参与人都有独立提醒。
        if is_auto_reminder and not notice.source_key.endswith(f"-{username}"):
            recipient_key = f"{notice.source_key}-{username}"
            duplicate = await db.scalar(select(Notification).where(Notification.source_key == recipient_key))
            if duplicate:
                await db.delete(notice)
                continue
            notice.source_key = recipient_key
        allowed_ids = visible_task_ids if notice.source_type == "task" else visible_ids
        is_terminal_task_reminder = (
            notice.source_type == "task" and notice.source_id in terminal_task_ids
            and notice.source_key.startswith("task-")
            and not notice.source_key.startswith(("task-history-", "task-message-"))
        )
        if notice.source_id not in existing_record_ids or notice.source_id not in allowed_ids or is_terminal_task_reminder:
            await db.delete(notice)
    for task in tasks:
        info = _task_dict(task)
        if info["reminder_due"]:
            candidates.append({"source_key": f"task-{task.id}-{today}-{username}", "source_type": "task", "source_id": task.id, "title": info["reminder_text"], "content": f"{task.serial_no}｜{task.title}｜负责人：{task.owner}", "level": "error" if info["status"] == "已逾期" else "warning"})
    fees = (await db.scalars(select(BusinessRecord).where(BusinessRecord.module == "finance", BusinessRecord.status == "待审批", *(await _record_scope_conditions(identity, db))))).all()
    for fee in fees:
        candidates.append({"source_key": f"finance-approval-{fee.id}-{username}", "source_type": "finance", "source_id": fee.id, "title": "费用待审批", "content": f"{fee.serial_no}｜{fee.title}｜{(fee.data or {}).get('amount', 0)} 元", "level": "warning"})
    current_steps = (await db.execute(select(ContractApprovalStep, BusinessRecord).join(BusinessRecord, BusinessRecord.id == ContractApprovalStep.contract_record_id).where(ContractApprovalStep.status == "待审批", BusinessRecord.status == "审批中"))).all()
    for step, contract in current_steps:
        if identity.get("role") == "admin" or step.approver == username:
            candidates.append({"source_key": f"contract-approval-{contract.id}-{step.id}-{username}", "source_type": "contract", "source_id": contract.id, "title": f"合同第 {step.step_order} 级待审批", "content": f"{contract.serial_no}｜{contract.title}｜审批人：{step.approver}", "level": "warning"})
    hearings = (await db.execute(select(HearingSchedule, BusinessRecord).join(BusinessRecord, BusinessRecord.id == HearingSchedule.case_record_id).where(HearingSchedule.hearing_date == today + timedelta(days=1), HearingSchedule.status == "已排期", *(await _record_scope_conditions(identity, db))))).all()
    for hearing, case_record in hearings:
        candidates.append({"source_key": f"hearing-{hearing.id}-{hearing.hearing_date}-{username}", "source_type": "case", "source_id": case_record.id, "title": "明日开庭提醒", "content": f"{case_record.serial_no}｜{hearing.hearing_time}｜{hearing.court}｜{hearing.hearing_lawyer}", "level": "info"})
    existing_keys = set((await db.scalars(select(Notification.source_key).where(Notification.source_key.in_([x["source_key"] for x in candidates])))).all()) if candidates else set()
    for item in candidates:
        if item["source_key"] not in existing_keys: db.add(Notification(**item, recipient=username))
    await db.commit()


@app.get(f"{settings.api_prefix}/notifications")
async def list_notifications(
    unread_only: bool = False, sent_only: bool = False, read_status: str = "", sender: str = "",
    keyword: str = "", notification_type: str = "", source_type: str = "", level: str = "",
    reminder_only: bool = False, date_from: date | None = None, date_to: date | None = None,
    page: int = Query(1, ge=1), page_size: int = Query(100, ge=1, le=200),
    identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db),
):
    await _sync_notifications(identity, db)
    if date_from and date_to and date_from > date_to: raise HTTPException(status_code=422, detail="开始日期不能晚于结束日期")
    conditions = [Notification.sender == identity["username"], Notification.sender_deleted.is_(False)] if sent_only else [Notification.recipient == identity["username"], Notification.recipient_deleted.is_(False)]
    if unread_only or read_status == "未读": conditions.append(Notification.is_read.is_(False))
    elif read_status == "已读": conditions.append(Notification.is_read.is_(True))
    elif read_status not in {"", "全部"}: raise HTTPException(status_code=422, detail="消息状态无效")
    if sender.strip(): conditions.append(Notification.sender.ilike(f"%{sender.strip()}%"))
    if keyword.strip():
        term = f"%{keyword.strip()}%"; conditions.append(or_(Notification.title.ilike(term), Notification.content.ilike(term)))
    if notification_type:
        if notification_type not in {"系统通知", "用户通知"}: raise HTTPException(status_code=422, detail="消息类型无效")
        conditions.append(Notification.notification_type == notification_type)
    if source_type:
        if source_type not in {"task", "finance", "contract", "case", "message"}: raise HTTPException(status_code=422, detail="消息来源无效")
        conditions.append(Notification.source_type == source_type)
    if level:
        if level not in {"info", "warning", "error"}: raise HTTPException(status_code=422, detail="提醒级别无效")
        conditions.append(Notification.level == level)
    if reminder_only:
        conditions.extend([
            Notification.source_type == "task",
            Notification.source_key.like("task-%"),
            ~Notification.source_key.like("task-message-%"),
            ~Notification.source_key.like("task-history-%"),
        ])
    if date_from: conditions.append(Notification.created_at >= datetime.combine(date_from, datetime.min.time()))
    if date_to: conditions.append(Notification.created_at <= datetime.combine(date_to, datetime.max.time()))
    total = int(await db.scalar(select(func.count()).select_from(Notification).where(*conditions)) or 0)
    items = (await db.scalars(select(Notification).where(*conditions).order_by(Notification.created_at.desc(), Notification.id.desc()).offset((page - 1) * page_size).limit(page_size))).all()
    unread = int(await db.scalar(select(func.count()).select_from(Notification).where(Notification.recipient == identity["username"], Notification.recipient_deleted.is_(False), Notification.is_read.is_(False))) or 0)
    users_by_username = await _user_display_map({value for item in items for value in (item.sender, item.recipient)}, db)
    return {"items": [_notification_dict(x, users_by_username) for x in items], "unread": unread, "total": total, "page": page, "page_size": page_size}


@app.get(f"{settings.api_prefix}/users/directory")
async def user_directory(
    purpose: str = "",
    identity: dict = Depends(current_identity),
    db: AsyncSession = Depends(get_db),
):
    directory_purpose = purpose.strip().lower()
    if directory_purpose == "contract_approver":
        approver_employees = (await db.scalars(select(BusinessRecord).where(
            BusinessRecord.module == "hr",
        ))).all()
        eligible_usernames = {
            str((item.data or {}).get("username") or item.owner or "").strip().lower()
            for item in approver_employees
            if str((item.data or {}).get("username") or item.owner or "").strip()
        }
    else:
        eligible_usernames = (
            await _active_customer_usernames(db)
            if directory_purpose == "customer_contact"
            else await _active_employee_usernames(db)
        )
    if directory_purpose == "customer_manager":
        # Keep active legacy/system accounts in the response so an existing
        # customer source or manager can still render its display name.  The
        # eligibility flag below continues to prevent accounts without an
        # active employee record from being newly selected.
        candidates = (await db.scalars(select(User).where(
            User.is_active.is_(True),
        ).order_by(User.display_name, User.username))).all()
        items = [
            item for item in candidates
            if not _is_smoke_test_username(item.username)
            and str((item.profile or {}).get("account_type") or "").strip() != "客户账号"
        ]
    else:
        items = (await db.scalars(select(User).where(
            User.is_active.is_(True), User.username.in_(eligible_usernames),
        ).order_by(User.display_name, User.username))).all() if eligible_usernames else []
    employee_display_names: dict[str, str] = {}
    active_employees = (await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "hr",
        *([] if directory_purpose == "contract_approver" else [BusinessRecord.status.not_in({"离职", "停用"})]),
    ))).all()
    for employee in active_employees:
        username = str((employee.data or {}).get("username") or employee.owner or "").strip().lower()
        display_name = str(employee.title or "").strip()
        if username and display_name:
            employee_display_names.setdefault(username, display_name)
    job_roles = (await db.scalars(select(JobRole).where(JobRole.is_active.is_(True)))).all()
    roles_by_name = {item.name: item for item in job_roles}
    payload = []
    for item in items:
        position = _configured_user_job_role_name(item)
        account_type = str((item.profile or {}).get("account_type") or "员工账号").strip()
        job_role = roles_by_name.get(position)
        job_permissions = list(job_role.permissions or []) if job_role else []
        display_name = employee_display_names.get(item.username.lower()) or item.display_name
        payload.append({
            "username": item.username,
            "display_name": display_name,
            "department": item.department,
            "is_active": item.is_active,
            "role": item.role,
            "position": position,
            "staff_role": str((item.profile or {}).get("staff_role") or ""),
            "account_type": account_type,
            "job_permissions": job_permissions,
            "can_approve_contract": await _is_contract_approver(item, db),
            "eligible_customer_person": item.username.lower() in eligible_usernames if directory_purpose in {"customer_manager", "customer_contact"} else None,
        })
    return {"items": payload}


async def _configured_investigation_supervisor(db: AsyncSession) -> User:
    config = await db.scalar(select(SystemConfig).where(SystemConfig.key == "investigation_assignment"))
    configured_username = str((config.value or {}).get("supervisor_username") or "").strip() if config else ""
    if not configured_username:
        raise HTTPException(status_code=409, detail="请先由管理员在系统配置中设置调查任务分配人")
    supervisor = await db.scalar(select(User).where(User.username == configured_username, User.is_active.is_(True)))
    if not supervisor:
        raise HTTPException(status_code=409, detail="已配置的调查任务分配人不存在或已停用，请重新设置")
    return supervisor


@app.get(f"{settings.api_prefix}/investigations/assignment-supervisor")
async def investigation_assignment_supervisor(identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    supervisor = await _configured_investigation_supervisor(db)
    return {"username": supervisor.username, "display_name": supervisor.display_name, "department": supervisor.department}

@app.get(f"{settings.api_prefix}/contracts/approver-settings")
async def contract_approver_settings(identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    employees = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "hr",
    ).order_by(BusinessRecord.title, BusinessRecord.id))).all())
    usernames = list(dict.fromkeys(
        str((item.data or {}).get("username") or item.owner or "").strip().lower()
        for item in employees
        if str((item.data or {}).get("username") or item.owner or "").strip()
    ))
    users = list((await db.scalars(select(User).where(User.username.in_(usernames), User.is_active.is_(True)))).all()) if usernames else []
    by_username = {item.username: item for item in users}
    items = []
    seen_usernames: set[str] = set()
    for employee in employees:
        username = str((employee.data or {}).get("username") or employee.owner or "").strip().lower()
        user = by_username.get(username)
        if not user or username in seen_usernames:
            continue
        seen_usernames.add(username)
        display_name = _valid_contract_person_name(user.display_name, username)
        items.append({
            "username": username,
            "display_name": display_name or CONTRACT_PERSON_NAME_PLACEHOLDER,
            "display_name_valid": bool(display_name),
            "department": user.department or employee.department,
            "position": str((user.profile or {}).get("position") or (employee.data or {}).get("position") or ""),
            "selected": bool((user.profile or {}).get("contract_approval_enabled")),
        })
    return {"items": items}

@app.put(f"{settings.api_prefix}/contracts/approver-settings")
async def save_contract_approver_settings(body: ContractApproverSettingsInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _require_admin(identity)
    requested = set(dict.fromkeys(value.strip().lower() for value in body.usernames if value.strip()))
    employees = list((await db.scalars(select(BusinessRecord).where(
        BusinessRecord.module == "hr",
    ))).all())
    eligible = {
        str((item.data or {}).get("username") or item.owner or "").strip().lower()
        for item in employees
        if str((item.data or {}).get("username") or item.owner or "").strip()
    }
    invalid = sorted(requested - eligible)
    if invalid:
        raise HTTPException(status_code=422, detail=f"所选人员没有关联员工档案：{', '.join(invalid)}")
    users = list((await db.scalars(select(User).where(User.username.in_(eligible)))).all()) if eligible else []
    active_usernames = {item.username for item in users if item.is_active}
    invalid = sorted(requested - active_usernames)
    if invalid:
        raise HTTPException(status_code=422, detail=f"所选人员账号不存在或已停用：{', '.join(invalid)}")
    users_by_username = {item.username: item for item in users}
    invalid_names = sorted(username for username in requested if not _valid_contract_person_name(users_by_username[username].display_name, username))
    if invalid_names:
        raise HTTPException(status_code=422, detail="所选员工缺少有效姓名，请先在人事中心维护姓名并取消其合同审批资格")
    for user in users:
        user.profile = {**(user.profile or {}), "contract_approval_enabled": user.username in requested}
    await db.commit()
    return {"usernames": sorted(requested), "count": len(requested)}


@app.post(f"{settings.api_prefix}/notifications/send", status_code=status.HTTP_201_CREATED)
async def send_user_message(body: UserMessageInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    recipients = list(dict.fromkeys(value.strip() for value in body.recipients if value.strip()))
    active_users = set((await db.scalars(select(User.username).where(User.username.in_(recipients), User.is_active.is_(True)))).all())
    missing = sorted(set(recipients) - active_users)
    if missing: raise HTTPException(status_code=422, detail=f"接收人不存在或已停用：{', '.join(missing)}")
    batch = uuid4().hex
    items = []
    for recipient in recipients:
        item = Notification(source_key=f"user-message-{batch}-{recipient}", source_type="message", sender=identity["username"], recipient=recipient, notification_type="用户通知", title=body.title.strip(), content=body.content.strip(), level="info")
        db.add(item); items.append(item)
    await db.commit()
    for item in items: await db.refresh(item)
    users_by_username = await _user_display_map({value for item in items for value in (item.sender, item.recipient)}, db)
    return {"items": [_notification_dict(item, users_by_username) for item in items], "sent": len(items)}


@app.post(f"{settings.api_prefix}/notifications/{{notification_id}}/read")
async def read_notification(notification_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    item = await db.get(Notification, notification_id)
    if not item or item.recipient != identity["username"] or item.recipient_deleted: raise HTTPException(status_code=404, detail="消息不存在")
    item.is_read = True; item.read_at = datetime.now(); await db.commit(); await db.refresh(item)
    users_by_username = await _user_display_map({item.sender, item.recipient}, db)
    return _notification_dict(item, users_by_username)


@app.post(f"{settings.api_prefix}/notifications/read-all")
async def read_all_notifications(identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    items = (await db.scalars(select(Notification).where(Notification.recipient == identity["username"], Notification.recipient_deleted.is_(False), Notification.is_read.is_(False)))).all()
    now = datetime.now()
    for item in items: item.is_read = True; item.read_at = now
    await db.commit(); return {"updated": len(items)}


@app.delete(f"{settings.api_prefix}/notifications/{{notification_id}}", status_code=status.HTTP_204_NO_CONTENT)
async def delete_notification(notification_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    item = await db.get(Notification, notification_id)
    if not item: raise HTTPException(status_code=404, detail="消息不存在")
    changed = False
    if item.recipient == identity["username"] and not item.recipient_deleted: item.recipient_deleted = True; changed = True
    if item.sender == identity["username"] and not item.sender_deleted: item.sender_deleted = True; changed = True
    if not changed: raise HTTPException(status_code=404, detail="消息不存在")
    if item.recipient_deleted and item.sender_deleted: await db.delete(item)
    await db.commit(); return Response(status_code=status.HTTP_204_NO_CONTENT)


def _communication_dict(item: CommunicationLog, users_by_username: dict[str, User] | None = None) -> dict:
    return {"id": item.id, "customer_record_id": item.customer_record_id, "customer_name": item.customer_name, "contact": item.contact, "phone": item.phone, "content": item.content, "occurred_at": item.occurred_at, "operator": item.operator, "operator_display_name": _person_reference_display(item.operator, users_by_username or {})[0], "created_at": item.created_at, "updated_at": item.updated_at}


def _parse_customer_contact_at(value: object) -> datetime | None:
    raw_value = str(value or "").strip()
    if not raw_value:
        return None
    try:
        parsed = datetime.fromisoformat(raw_value.replace("Z", "+00:00"))
    except ValueError:
        return None
    # Normalize explicit offsets and Z to one UTC-naive timeline.  Historical
    # naive values keep their wall-clock meaning for backward compatibility.
    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
    return parsed


def _sync_customer_contact_metrics(customer: BusinessRecord) -> None:
    """Recompute the denormalized contact date/count from real contact notes.

    Communication-log rows are mirrored into ``data.notes`` with the same
    stable note id.  Keeping one source of truth here also covers ordinary
    customer follow-up notes and makes edits/deletes recalculate the maximum
    event time instead of blindly overwriting it with the last API request.
    Customer-directory changes (for example adding a contact person) are not
    communication events and must never call this helper.
    """
    data = dict(customer.data or {})
    notes = [dict(note) for note in list(data.get("notes", [])) if isinstance(note, dict)]
    occurred_values: list[tuple[datetime, str]] = []
    for note in notes:
        raw_value = str(note.get("created_at") or "").strip()
        parsed = _parse_customer_contact_at(raw_value)
        if parsed is not None:
            occurred_values.append((parsed, raw_value))
    latest = max(occurred_values, key=lambda value: value[0])[1] if occurred_values else ""
    customer.data = {**data, "notes": notes, "last_contact_at": latest, "contact_count": len(occurred_values)}


CUSTOMER_MODIFICATION_ACTIONS = {
    "创建客户", "批量导入", "编辑", "编辑变更",
    "领取客户", "释放公海", "共享客户", "移入回收站", "恢复客户",
    "新增联系人", "删除联系人", "更新客户管理人",
    "新增客户跟进", "删除客户跟进",
    "新增沟通日志", "修改沟通日志", "删除沟通日志",
}


def _mark_customer_modified(customer: BusinessRecord, identity: dict) -> None:
    """Maintain the actor used by the original ``最近更新的客户`` projection.

    ``updated_at`` is the authoritative modification time maintained by the
    database.  The actor is kept in customer JSON because the legacy schema has
    no dedicated column.  A historical ``last_modified_date`` value must not
    override the authoritative database timestamp after a real local change.
    """
    data = dict(customer.data or {})
    data.pop("last_modified_date", None)
    data["last_modified_by"] = identity["username"]
    customer.data = data


@app.get(f"{settings.api_prefix}/communications")
async def list_communications(keyword: str = "", date_from: date | None = None, date_to: date | None = None, mine_only: bool = True, customer_record_id: int | None = Query(default=None, ge=1), page: int = Query(1, ge=1), page_size: int = Query(50, ge=1, le=200), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    conditions = []
    if identity.get("role") != "admin" or mine_only: conditions.append(CommunicationLog.operator == identity["username"])
    if identity.get("role") != "admin": conditions.append(CommunicationLog.customer_record_id.in_(await _visible_record_ids(identity, db)))
    if customer_record_id:
        if identity.get("role") != "admin" and customer_record_id not in await _visible_record_ids(identity, db):
            raise HTTPException(status_code=404, detail="客户不存在或无权查看")
        conditions.append(CommunicationLog.customer_record_id == customer_record_id)
    if keyword.strip():
        term = f"%{keyword.strip()}%"; conditions.append(or_(CommunicationLog.customer_name.ilike(term), CommunicationLog.contact.ilike(term), CommunicationLog.phone.ilike(term), CommunicationLog.content.ilike(term)))
    if date_from: conditions.append(CommunicationLog.occurred_at >= datetime.combine(date_from, datetime.min.time()))
    if date_to: conditions.append(CommunicationLog.occurred_at <= datetime.combine(date_to, datetime.max.time()))
    total = int(await db.scalar(select(func.count()).select_from(CommunicationLog).where(*conditions)) or 0)
    items = (await db.scalars(select(CommunicationLog).where(*conditions).order_by(CommunicationLog.occurred_at.desc(), CommunicationLog.id.desc()).offset((page - 1) * page_size).limit(page_size))).all()
    users_by_username = await _user_display_map({item.operator for item in items}, db)
    return {"items": [_communication_dict(item, users_by_username) for item in items], "total": total, "page": page, "page_size": page_size}


async def _communication_attachment_context(communication_id: int, identity: dict, db: AsyncSession) -> tuple[CommunicationLog, BusinessRecord]:
    item = await db.get(CommunicationLog, communication_id)
    if not item or (identity.get("role") != "admin" and item.operator != identity["username"]):
        raise HTTPException(status_code=404, detail="沟通记录不存在")
    customer = await _customer_or_404(item.customer_record_id, identity, db)
    await _require_record_owner_or_manager(customer, identity, db)
    return item, customer


@app.get(f"{settings.api_prefix}/communications/{{communication_id}}/attachments")
async def list_communication_attachments(communication_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _item, customer = await _communication_attachment_context(communication_id, identity, db)
    attachments = (await db.scalars(select(FileAttachment).where(
        FileAttachment.communication_log_id == communication_id,
    ).order_by(FileAttachment.created_at.desc(), FileAttachment.id.desc()))).all()
    return {"items": [_attachment_dict(attachment, customer) for attachment in attachments]}


@app.post(f"{settings.api_prefix}/communications/{{communication_id}}/attachments", status_code=status.HTTP_201_CREATED)
async def upload_communication_attachment(communication_id: int, file: UploadFile = File(...), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _item, customer = await _communication_attachment_context(communication_id, identity, db)
    suffix = Path(file.filename or "").suffix.lower()
    # Accept all ordinary file types. Browsers do not upload a directory as a
    # file; a directory must still be compressed as ZIP before selection.
    content = await file.read()
    if len(content) > 20 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="单个文件不能超过 20MB")
    stored_name = f"{uuid4().hex}{suffix}"
    target = UPLOAD_ROOT / stored_name
    target.write_bytes(content)
    attachment = FileAttachment(
        record_id=customer.id, communication_log_id=communication_id, category="沟通记录附件",
        original_name=Path(file.filename or stored_name).name, stored_name=stored_name,
        content_type=file.content_type or "application/octet-stream", size=len(content), path=str(target),
        uploader=identity["username"], remark="",
    )
    try:
        db.add(attachment)
        db.add(_customer_event(customer, "上传沟通记录附件", identity, f"沟通记录 #{communication_id}：{attachment.original_name}"))
        await db.commit()
        await db.refresh(attachment)
    except Exception:
        await db.rollback()
        target.unlink(missing_ok=True)
        raise
    return _attachment_dict(attachment, customer)


@app.delete(f"{settings.api_prefix}/communications/{{communication_id}}/attachments/{{attachment_id}}", status_code=status.HTTP_204_NO_CONTENT)
async def delete_communication_attachment(communication_id: int, attachment_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    _item, customer = await _communication_attachment_context(communication_id, identity, db)
    attachment = await db.scalar(select(FileAttachment).where(
        FileAttachment.id == attachment_id, FileAttachment.communication_log_id == communication_id,
    ))
    if not attachment:
        raise HTTPException(status_code=404, detail="沟通记录附件不存在")
    path = Path(attachment.path)
    name = attachment.original_name
    await db.delete(attachment)
    db.add(_customer_event(customer, "删除沟通记录附件", identity, f"沟通记录 #{communication_id}：{name}"))
    await db.commit()
    if path.is_file() and UPLOAD_ROOT.resolve() in path.resolve().parents:
        path.unlink(missing_ok=True)
    return Response(status_code=status.HTTP_204_NO_CONTENT)


@app.post(f"{settings.api_prefix}/communications", status_code=status.HTTP_201_CREATED)
async def create_communication(body: CommunicationLogInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    customer = await _customer_or_404(body.customer_record_id, identity, db)
    await _require_record_owner_or_manager(customer, identity, db)
    occurred_at = _parse_customer_contact_at(body.occurred_at)
    if occurred_at is None: raise HTTPException(status_code=422, detail="沟通时间格式无效")
    if occurred_at > datetime.now() + timedelta(minutes=5): raise HTTPException(status_code=422, detail="沟通时间不能晚于当前时间")
    note_id = uuid4().hex; contact, phone, content = body.contact.strip(), body.phone.strip(), body.content.strip()
    note = {"id": note_id, "type": "沟通日志", "content": content, "operator": identity["username"], "contact": contact, "phone": phone, "created_at": body.occurred_at.isoformat(timespec="seconds")}
    customer.data = {**(customer.data or {}), "notes": [note, *list((customer.data or {}).get("notes", []))]}
    _sync_customer_contact_metrics(customer)
    item = CommunicationLog(customer_record_id=customer.id, customer_name=customer.title, contact=contact, phone=phone, content=content, occurred_at=body.occurred_at, operator=identity["username"], note_id=note_id)
    db.add(item); db.add(_customer_event(customer, "新增沟通日志", identity, f"{contact or '客户联系人'}：{content[:120]}"))
    await db.commit(); await db.refresh(item)
    return _communication_dict(item, await _user_display_map({item.operator}, db))


@app.patch(f"{settings.api_prefix}/communications/{{communication_id}}")
async def update_communication(communication_id: int, body: CommunicationLogUpdate, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    item = await db.get(CommunicationLog, communication_id)
    if not item or (identity.get("role") != "admin" and item.operator != identity["username"]): raise HTTPException(status_code=404, detail="沟通记录不存在")
    customer = await _customer_or_404(item.customer_record_id, identity, db)
    await _require_record_owner_or_manager(customer, identity, db)
    if body.occurred_at:
        occurred_at = _parse_customer_contact_at(body.occurred_at)
        if occurred_at is None: raise HTTPException(status_code=422, detail="沟通时间格式无效")
        if occurred_at > datetime.now() + timedelta(minutes=5): raise HTTPException(status_code=422, detail="沟通时间不能晚于当前时间")
    changes = body.model_dump(exclude_unset=True, exclude_none=True)
    for key, value in changes.items(): setattr(item, key, value.strip() if key in {"contact", "phone", "content"} else value)
    data = dict(customer.data or {}); note_updates = {"content": item.content, "contact": item.contact, "phone": item.phone, "created_at": item.occurred_at.isoformat(timespec="seconds")}
    notes = [{**dict(note), **note_updates} if note.get("id") == item.note_id else dict(note) for note in list(data.get("notes", []))]
    customer.data = {**data, "notes": notes}
    _sync_customer_contact_metrics(customer)
    db.add(_customer_event(customer, "修改沟通日志", identity, item.content[:120]))
    await db.commit(); await db.refresh(item)
    return _communication_dict(item, await _user_display_map({item.operator}, db))


@app.delete(f"{settings.api_prefix}/communications/{{communication_id}}", status_code=status.HTTP_204_NO_CONTENT)
async def delete_communication(communication_id: int, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    item = await db.get(CommunicationLog, communication_id)
    if not item or (identity.get("role") != "admin" and item.operator != identity["username"]): raise HTTPException(status_code=404, detail="沟通记录不存在")
    attachment_paths = (await db.scalars(select(FileAttachment.path).where(FileAttachment.communication_log_id == communication_id))).all()
    customer = await db.get(BusinessRecord, item.customer_record_id)
    if customer:
        customer = await _customer_or_404(customer.id, identity, db)
        await _require_record_owner_or_manager(customer, identity, db)
        data = customer.data or {}; customer.data = {**data, "notes": [note for note in list(data.get("notes", [])) if note.get("id") != item.note_id]}
        _sync_customer_contact_metrics(customer)
        db.add(_customer_event(customer, "删除沟通日志", identity, item.content[:120]))
    await db.delete(item); await db.commit()
    for raw_path in attachment_paths:
        path = Path(raw_path)
        if path.is_file() and UPLOAD_ROOT.resolve() in path.resolve().parents:
            path.unlink(missing_ok=True)
    return Response(status_code=status.HTTP_204_NO_CONTENT)


