@app.get(f"{settings.api_prefix}/records/import-template")
async def records_import_template(module: str = Query(min_length=1, max_length=32), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    await _require_record_module_menu(module, identity, db, action="下载导入模板")
    if module == "case": raise HTTPException(status_code=409, detail="案件必须使用分阶段专用入口创建，不能使用通用导入模板")
    columns = RECORD_IMPORT_COLUMNS.get(module)
    if not columns: raise HTTPException(status_code=422, detail="该业务模块不支持批量导入")
    output = io.StringIO(); writer = csv.writer(output); writer.writerow(columns); writer.writerow(RECORD_IMPORT_SAMPLES[module])
    return Response(content=("\ufeff" + output.getvalue()).encode("utf-8"), media_type="text/csv; charset=utf-8", headers={"Content-Disposition": f'attachment; filename="{module}-import-template.csv"'})


def _csv_value(row: dict, *names: str, default: str = "") -> str:
    for name in names:
        value = row.get(name)
        if value is not None and str(value).strip(): return str(value).strip()
    return default


def _csv_date(value: str, label: str, *, required: bool = True) -> str:
    if not value and not required: return ""
    try: return str(date.fromisoformat(value))
    except ValueError as exc: raise ValueError(f"{label}必须为 YYYY-MM-DD") from exc


def _unique_import_record(records: list[BusinessRecord], value: str, label: str) -> BusinessRecord | None:
    token = value.strip()
    if not token:
        return None
    exact_serial = [item for item in records if item.serial_no == token]
    exact_title = [item for item in records if item.title == token]
    matches = exact_serial or exact_title
    if not matches:
        raise ValueError(f"{label}不存在或无权访问：{token}")
    if len(matches) != 1:
        raise ValueError(f"{label}存在多个同名记录，请使用唯一业务编号：{token}")
    return matches[0]


def _import_relation_data(
    *,
    customer: BusinessRecord | None = None,
    contract: BusinessRecord | None = None,
    case: BusinessRecord | None = None,
    investigation: BusinessRecord | None = None,
    task: BusinessRecord | None = None,
    clue: BusinessRecord | None = None,
    evidence: BusinessRecord | None = None,
) -> dict:
    result: dict = {}
    items = (
        ("customer", customer), ("contract", contract), ("case", case),
        ("investigation", investigation), ("task", task), ("clue", clue), ("evidence", evidence),
    )
    for name, item in items:
        if item:
            result[f"{name}_id"] = item.id
            result[f"{name}_record_id"] = item.id
            result[f"{name}_no"] = item.serial_no
            result[f"{name}_title"] = item.title
    # A directly selected child also carries its already-resolved parent chain.
    # This keeps downstream imports navigable even when the CSV only provides a
    # case, clue, task, or evidence number.
    for _, item in items:
        if not item:
            continue
        source = item.data or {}
        for name in ("customer", "contract", "case", "investigation", "task", "clue", "evidence"):
            for suffix in ("id", "record_id", "no", "title"):
                key = f"{name}_{suffix}"
                value = source.get(key)
                if value not in (None, ""):
                    result.setdefault(key, value)
    return result


def _validate_import_relation_consistency(relations: dict[str, BusinessRecord]) -> None:
    for child_name, child in relations.items():
        source = child.data or {}
        for parent_name, parent in relations.items():
            if child_name == parent_name:
                continue
            expected = source.get(f"{parent_name}_record_id") or source.get(f"{parent_name}_id")
            expected_no = str(source.get(f"{parent_name}_no") or "").strip()
            if expected and int(expected) != parent.id:
                raise ValueError(f"关联关系冲突：{child.serial_no} 不属于 {parent.serial_no}")
            if expected_no and expected_no != parent.serial_no:
                raise ValueError(f"关联关系冲突：{child.serial_no} 不属于 {parent.serial_no}")


@app.post(f"{settings.api_prefix}/records/import")
async def import_business_records(module: str = Query(min_length=1, max_length=32), file: UploadFile = File(...), identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    await _require_record_module_menu(module, identity, db, action="批量导入")
    if module not in RECORD_IMPORT_COLUMNS: raise HTTPException(status_code=422, detail="该业务模块不支持批量导入")
    if module == "case": raise HTTPException(status_code=409, detail="案件必须使用分阶段专用入口创建，不能通过通用导入绕过")
    if module in {"hr", "warehouse"} and identity.get("role") not in {"admin", "manager"}: raise HTTPException(status_code=403, detail="当前角色不能批量导入该模块")
    if not (file.filename or "").lower().endswith(".csv"): raise HTTPException(status_code=422, detail="仅支持 UTF-8 CSV 文件")
    raw = await file.read()
    if len(raw) > 5 * 1024 * 1024: raise HTTPException(status_code=413, detail="导入文件不能超过 5MB")
    try: csv_text = raw.decode("utf-8-sig")
    except UnicodeDecodeError as exc: raise HTTPException(status_code=422, detail="CSV 必须使用 UTF-8 编码") from exc
    reader = csv.DictReader(io.StringIO(csv_text))
    if not reader.fieldnames: raise HTTPException(status_code=422, detail="CSV 缺少表头")
    existing = set((await db.scalars(select(BusinessRecord.serial_no))).all()); seen: set[str] = set(); errors: list[dict] = []; created_items: list[dict] = []
    scope = await _record_scope_conditions(identity, db)
    scoped_records = list((await db.scalars(select(BusinessRecord).where(*scope))).all())
    records_by_module = {name: [item for item in scoped_records if item.module == name] for name in ("customer", "contract", "case", "investigation", "task", "clue", "evidence")}
    seal_assets = {item.code: item for item in (await db.scalars(select(SealAsset).where(SealAsset.status == "可用"))).all()}
    user = await db.scalar(select(User).where(User.username == identity["username"]))
    for row_no, row in enumerate(reader, 2):
        try:
            serial = _csv_value(row, "业务编号", "员工编号", "物品编号", "申请编号", "serial_no")
            title = _csv_value(row, "标题", "合同名称", "案件名称", "任务内容", "文件名称", "费用名称", "姓名", "物品名称", "申请标题", "title")
            if not serial or not title: raise ValueError("业务编号和名称不能为空")
            if serial in existing or serial in seen: raise ValueError(f"业务编号已存在：{serial}")
            owner = _csv_value(row, "负责人", "经办人", "owner", default=identity["username"])
            department = _csv_value(row, "部门", "department", default=(user.department if user else "上海分所"))
            if identity.get("role") != "admin":
                department = user.department if user else department
                if identity.get("role") == "user": owner = identity["username"]
            customer = _csv_value(row, "客户/主体", "customer")
            description = _csv_value(row, "说明", "description")
            data: dict = {"imported_at": datetime.now().isoformat(timespec="seconds"), "import_row": row_no}
            status_value = "草稿"
            if module == "contract":
                amount = float(_csv_value(row, "合同金额", "amount")); signed_at = _csv_date(_csv_value(row, "签订日期", "signed_at"), "签订日期")
                if amount < 0 or not customer: raise ValueError("客户不能为空，合同金额不能为负数")
                customer_record = _unique_import_record(records_by_module["customer"], customer, "关联客户")
                customer = customer_record.title
                data.update(_import_relation_data(customer=customer_record))
                data.update({"type": _csv_value(row, "合同类型", "type", default="专项服务"), "amount": f"{amount:.2f}", "signed_at": signed_at, "external_contract_no": _csv_value(row, "外部合同号", "external_contract_no")})
            elif module == "case":
                contract_no = _csv_value(row, "关联合同号", "contract_no"); contract = contracts.get(contract_no)
                if not contract: raise ValueError("关联合同不存在或无权访问")
                if contract.status in {"草稿", "审批中", "已拒绝", "已撤回", "已作废"}: raise ValueError("关联合同尚未审批通过")
                customer = contract.customer; department = contract.department; status_value = "新案待分配"; contract_data = contract.data or {}
                data.update({"contract_id": contract.id, "contract_no": contract.serial_no, "external_contract_no": contract_data.get("external_contract_no", ""), "contract_title": contract.title, "case_type": _csv_value(row, "案件类型", "case_type", default="民事案件"), "opponent": _csv_value(row, "对方当事人", "opponent"), "court": _csv_value(row, "法院", "court")})
            elif module == "task":
                deadline = _csv_date(_csv_value(row, "截止日期", "deadline"), "截止日期")
                priority = _csv_value(row, "优先级", "priority", default="普通")
                if priority not in {"普通", "重要", "紧急"}: raise ValueError("任务优先级无效")
                try:
                    _validate_task_deadline(date.fromisoformat(deadline))
                    owner = await _active_task_username(owner, db, field_name="负责人")
                    collaborators = []
                    for value in [name.strip() for name in re.split(r"[、,，;；]", _csv_value(row, "协作人", "collaborators")) if name.strip()]:
                        collaborator = await _active_task_username(value, db, field_name="协作人")
                        if collaborator != owner and collaborator not in collaborators:
                            collaborators.append(collaborator)
                except HTTPException as exc:
                    raise ValueError(str(exc.detail)) from exc
                case_record = _unique_import_record(records_by_module["case"], _csv_value(row, "关联案号", "case_no"), "关联案件")
                if case_record:
                    customer = case_record.customer
                status_value = "待接收"; data.update(_import_relation_data(case=case_record)); data.update({"deadline": deadline, "priority": priority, "source": _csv_value(row, "来源", "source", default="日常任务"), "initiator": identity["username"], "collaborators": collaborators})
            elif module == "document":
                direction = _csv_value(row, "收发类型", "direction"); case_no = _csv_value(row, "关联案号", "case_no")
                if direction not in {"收文", "发文"}: raise ValueError("收发类型必须为收文或发文")
                case_record = _unique_import_record(records_by_module["case"], case_no, "关联案件")
                if case_record:
                    customer = case_record.customer
                status_value = "待登记"; data.update(_import_relation_data(case=case_record)); data.update({"direction": direction, "document_date": _csv_date(_csv_value(row, "文件日期", "document_date"), "文件日期"), "sender": _csv_value(row, "来文/送达单位", "sender")})
            elif module == "finance":
                amount = float(_csv_value(row, "金额", "amount")); case_no = _csv_value(row, "关联案号", "case_no")
                if amount <= 0: raise ValueError("费用金额必须大于 0")
                case_record = _unique_import_record(records_by_module["case"], case_no, "关联案件")
                if case_record:
                    customer = case_record.customer
                data.update(_import_relation_data(case=case_record)); data.update({"fee_type": _csv_value(row, "费用类型", "fee_type", default="官方费用"), "amount": f"{amount:.2f}", "handler": _csv_value(row, "经办人", "handler", default=owner)})
            elif module == "hr":
                position = _csv_value(row, "岗位", "position"); joined_at = _csv_date(_csv_value(row, "入职日期", "joined_at"), "入职日期")
                if not position: raise ValueError("岗位不能为空")
                requested_status = _csv_value(row, "状态", "status", default="试用"); status_value = "在职" if requested_status == "在职" else "试用"
                data.update({"position": position, "phone": _csv_value(row, "联系电话", "phone"), "joined_at": joined_at, "employment_type": _csv_value(row, "用工类型", "employment_type", default="全职"), "id_no": _csv_value(row, "证件号码", "id_no"), "email": _csv_value(row, "邮箱", "email")})
            elif module == "warehouse":
                quantity = int(_csv_value(row, "数量", "quantity")); category = _csv_value(row, "物品类别", "category"); location = _csv_value(row, "存放位置", "location")
                if quantity < 1 or not category or not location: raise ValueError("物品类别、数量和存放位置不能为空")
                customer = _csv_value(row, "供应商", "vendor"); status_value = "在库"; data.update({"category": category, "quantity": quantity, "unit": _csv_value(row, "单位", "unit", default="件"), "location": location, "vendor": customer, "borrower": "", "due_date": "", "borrow_purpose": ""})
            elif module == "seal":
                asset_code = _csv_value(row, "印章编号", "seal_code"); asset = seal_assets.get(asset_code); copies = int(_csv_value(row, "份数", "copies"))
                if not asset: raise ValueError("印章编号不存在或印章不可用")
                if copies < 1: raise ValueError("用印份数必须大于 0")
                data.update({"seal_asset_id": asset.id, "seal_name": asset.name, "seal_type": asset.seal_type, "copies": copies, "purpose": _csv_value(row, "用途", "purpose"), "use_date": _csv_date(_csv_value(row, "计划日期", "use_date"), "计划日期"), "delivery_method": _csv_value(row, "办理方式", "delivery_method", default="现场用印"), "document_names": _csv_value(row, "文件名称", "document_names")})
            relation_inputs = {
                "customer": _csv_value(row, "客户编号", "customer_no", default=customer if module not in {"warehouse", "hr"} else ""),
                "contract": _csv_value(row, "关联合同号", "contract_no"),
                "case": _csv_value(row, "关联案号", "case_no"),
                "investigation": _csv_value(row, "调查编号", "investigation_no"),
                "task": _csv_value(row, "调查任务编号", "task_no"),
                "clue": _csv_value(row, "线索编号", "clue_no"),
                "evidence": _csv_value(row, "取证编号", "evidence_no"),
            }
            resolved_relations = {
                name: _unique_import_record(records_by_module[name], value, f"关联{name}")
                for name, value in relation_inputs.items()
                if value
            }
            _validate_import_relation_consistency(resolved_relations)
            data.update(_import_relation_data(**resolved_relations))
            if customer_record := resolved_relations.get("customer"):
                customer = customer_record.title
            item = BusinessRecord(module=module, serial_no=serial, title=title, customer=customer, status=status_value, owner=owner, department=department, description=description, data=data)
            db.add(item); await db.flush(); db.add(WorkflowEvent(record_id=item.id, action="批量导入", to_status=item.status, operator=identity["username"], comment=f"CSV 第 {row_no} 行"))
            seen.add(serial); created_items.append({"id": item.id, "serial_no": serial, "title": title})
        except (ValueError, TypeError) as exc:
            errors.append({"row": row_no, "error": str(exc) or "字段格式错误", "value": _csv_value(row, "业务编号", "员工编号", "物品编号", "申请编号", "serial_no")})
    await db.commit()
    return {"module": module, "created": len(created_items), "failed": len(errors), "items": created_items, "errors": errors}


@app.get(f"{settings.api_prefix}/records")
async def list_records(
    module: str = Query(min_length=1, max_length=32),
    keyword: str = "", record_status: str = "", scope: str = Query("all", pattern="^(all|mine|recycle|department|company|audit)$"), statuses: str = "",
    customer_id: int | None = Query(default=None, gt=0), customer: str = "", customer_no: str = "", exclude_archived: bool = False,
    title: str = "", serial_no: str = "", record_type: str = Query("", alias="type"),
    case_no: str = "", fee_type: str = "", contract_body: str = "", source_person: str = "",
    signed_at_start: str = "", signed_at_end: str = "",
    investigation_view: str = Query("", pattern="^(|published|assigned|unassigned)$"),
    archive_view: str = Query("", pattern="^(|pending|refused)$"),
    pending_approver_only: bool = False,
    page: int = Query(1, ge=1), page_size: int = Query(20, ge=1, le=100),
    identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db),
):
    await _require_record_module_menu(module, identity, db, action="查看")
    if module in {"notary", "case"}:
        await _apply_notary_auto_conversion(db)
    conditions = [BusinessRecord.module == module]
    relation_customer = None
    if module == "contract" and customer_id:
        relation_customer = await _customer_or_404(customer_id, identity, db)
    elif not (
        module == "contract"
        and scope == "department"
        and identity.get("role") in {"admin", "manager"}
    ):
        # Department contracts are classified by the linked customer's active
        # managers below. Applying the contract row's stamped department first
        # would discard rows whose legacy department is stale.
        conditions.extend(await _record_scope_conditions(identity, db))
    if keyword:
        like = f"%{keyword}%"
        conditions.append(or_(BusinessRecord.serial_no.ilike(like), BusinessRecord.title.ilike(like), BusinessRecord.customer.ilike(like), BusinessRecord.owner.ilike(like)))
    if record_status:
        conditions.append(BusinessRecord.status == record_status)
    if module == "case" and archive_view:
        archive_submitter = func.trim(func.coalesce(BusinessRecord.data["archive_submitter"].as_string(), ""))
        if archive_view == "pending":
            if not await _case_action_granted(identity, db, "case.archive.review"):
                return {"items": [], "total": 0, "page": page, "page_size": page_size, "pages": 0}
            archive_reviewer = func.trim(func.coalesce(BusinessRecord.data["archive_reviewer"].as_string(), ""))
            archive_internal_reviewer = func.trim(func.coalesce(BusinessRecord.data["archive_internal_reviewer"].as_string(), ""))
            conditions.extend([
                BusinessRecord.status.in_({"待归档审核", "亏损内审", "亏损审核"}),
                or_(
                    archive_reviewer == identity["username"],
                    archive_internal_reviewer == identity["username"],
                    and_(
                        archive_reviewer == "",
                        archive_internal_reviewer == "",
                        BusinessRecord.owner == identity["username"],
                    ),
                ),
                archive_submitter != identity["username"],
            ])
        else:
            conditions.extend([
                archive_submitter == identity["username"],
                or_(
                    BusinessRecord.status == "亏损归档拒绝",
                    func.trim(func.coalesce(BusinessRecord.data["archive_reject_reason"].as_string(), "")) != "",
                ),
            ])
    if module == "case" and scope == "mine":
        conditions.append(await _case_mine_scope_condition(identity, db))
    if module == "clue" and statuses:
        requested_statuses = [value.strip() for value in statuses.split(",") if value.strip()]
        if requested_statuses:
            conditions.append(BusinessRecord.status.in_(requested_statuses))
    if module == "clue" and scope == "mine":
        # "My investigation clues" is an actor projection for every role,
        # including administrators.  Elevated data access must not turn a
        # personal queue into the company-wide clue list.
        conditions.append(func.lower(BusinessRecord.owner) == identity["username"].lower())
    if module in {"investigation", "task"} and investigation_view:
        publisher_expr = func.lower(func.coalesce(BusinessRecord.data["publisher"].as_string(), ""))
        legacy_publisher_missing = or_(
            BusinessRecord.data["publisher"].as_string().is_(None),
            BusinessRecord.data["publisher"].as_string() == "",
        )
        if module == "investigation" and investigation_view == "published":
            conditions.append(or_(
                publisher_expr == identity["username"].lower(),
                and_(legacy_publisher_missing, BusinessRecord.owner == identity["username"]),
            ))
        elif module == "task":
            investigation_subtask = or_(
                BusinessRecord.data["investigation_record_id"].as_integer() > 0,
                func.coalesce(BusinessRecord.data["investigation_no"].as_string(), "") != "",
                BusinessRecord.data["investigation_module"].as_string() == "investigation",
            )
            conditions.append(investigation_subtask)
            if investigation_view == "published" and identity.get("role") != "admin":
                publisher_expr = func.lower(func.coalesce(
                    BusinessRecord.data["initiator"].as_string(),
                    BusinessRecord.data["publisher"].as_string(),
                    BusinessRecord.data["assigned_by"].as_string(),
                    "",
                ))
                legacy_publisher_missing = and_(
                    or_(BusinessRecord.data["initiator"].as_string().is_(None), BusinessRecord.data["initiator"].as_string() == ""),
                    or_(BusinessRecord.data["publisher"].as_string().is_(None), BusinessRecord.data["publisher"].as_string() == ""),
                    or_(BusinessRecord.data["assigned_by"].as_string().is_(None), BusinessRecord.data["assigned_by"].as_string() == ""),
                )
                conditions.append(or_(
                    publisher_expr == identity["username"].lower(),
                    and_(legacy_publisher_missing, func.lower(BusinessRecord.owner) == identity["username"].lower()),
                ))
            elif investigation_view == "assigned" and identity.get("role") != "admin":
                # "My investigation tasks" must be private to the assignee.
                # The normal data scope may include a supervisor's department,
                # tasks they initiated, or records shared for collaboration,
                # none of which makes another investigator's child task a
                # personal task.
                conditions.append(func.lower(BusinessRecord.owner) == identity["username"].lower())
        elif investigation_view == "assigned" and identity.get("role") != "admin":
            # "My investigation tasks" must be private to the assignee.  The
            # normal data scope may include a supervisor's department, tasks
            # they initiated, or records shared for collaboration, none of
            # which makes another investigator's child task a personal task.
            conditions.append(func.lower(BusinessRecord.owner) == identity["username"].lower())
    if module == "contract":
        # Contract views pass scope/statuses from the frontend parity round; apply
        # them server-side so mine/dept/company/audit/recycle stay isolated.
        if title.strip():
            conditions.append(BusinessRecord.title.ilike(f"%{title.strip()}%"))
        if serial_no.strip():
            conditions.append(BusinessRecord.serial_no.ilike(f"%{serial_no.strip()}%"))
        if record_type.strip():
            conditions.append(BusinessRecord.data["type"].as_string() == record_type.strip())
        if case_no.strip():
            conditions.append(BusinessRecord.data["case_no"].as_string().ilike(f"%{case_no.strip()}%"))
        if fee_type.strip():
            conditions.append(BusinessRecord.data["fee_type"].as_string() == fee_type.strip())
        if contract_body.strip():
            conditions.append(BusinessRecord.data["contract_body"].as_string() == contract_body.strip())
        if source_person.strip():
            source_like = f"%{source_person.strip()}%"
            conditions.append(or_(
                BusinessRecord.data["source_person"].as_string().ilike(source_like),
                BusinessRecord.data["source_person_display_name"].as_string().ilike(source_like),
                BusinessRecord.owner.ilike(source_like),
            ))
        signed_at = func.substr(BusinessRecord.data["signed_at"].as_string(), 1, 10)
        if signed_at_start.strip():
            conditions.append(signed_at >= signed_at_start.strip())
        if signed_at_end.strip():
            conditions.append(signed_at <= signed_at_end.strip())
        if scope == "audit" and pending_approver_only:
            conditions.append(select(ContractApprovalStep.id).where(
                ContractApprovalStep.contract_record_id == BusinessRecord.id,
                ContractApprovalStep.approver == identity["username"],
                ContractApprovalStep.status == "待审批",
            ).exists())
        if statuses:
            requested_statuses = [value.strip() for value in statuses.split(",") if value.strip()]
            if requested_statuses:
                conditions.append(BusinessRecord.status.in_(requested_statuses))
        if scope == "recycle":
            conditions.append(BusinessRecord.status == "已回收")
        elif scope == "mine" and relation_customer is None:
            conditions.append(BusinessRecord.owner == identity["username"])
        elif scope == "department" and relation_customer is None:
            current_user = await db.scalar(select(User).where(User.username == identity["username"]))
            if current_user:
                department_users = (await db.scalars(select(User).where(
                    User.is_active.is_(True), User.department == current_user.department,
                ))).all()
                department_tokens = {
                    value
                    for user in department_users
                    for value in (str(user.username or "").strip(), str(user.display_name or "").strip())
                    if value
                }
                customers = (await db.scalars(select(BusinessRecord).where(
                    BusinessRecord.module == "customer",
                    BusinessRecord.status.not_in({"已回收", "公海"}),
                ))).all()
                customer_links = []
                for customer_record in customers:
                    managers = (customer_record.data or {}).get("customer_managers")
                    if not isinstance(managers, list) or not managers:
                        managers = [customer_record.owner]
                    if not (set(str(value).strip() for value in managers if str(value).strip()) & department_tokens):
                        continue
                    customer_links.append(BusinessRecord.data["customer_id"].as_integer() == customer_record.id)
                    if str(customer_record.serial_no or "").strip():
                        customer_links.append(BusinessRecord.data["customer_no"].as_string() == customer_record.serial_no)
                    if str(customer_record.title or "").strip():
                        customer_links.append(BusinessRecord.customer == customer_record.title)
                conditions.append(or_(*customer_links) if customer_links else false())
        if relation_customer is not None:
            relation_no = str(relation_customer.serial_no or "").strip()
            relation_name = str(relation_customer.title or "").strip()
            conditions.append(or_(
                BusinessRecord.data["customer_id"].as_integer() == relation_customer.id,
                BusinessRecord.data["customer_no"].as_string() == relation_no,
                func.lower(func.trim(BusinessRecord.customer)) == relation_name.casefold(),
            ))
        elif customer.strip():
            customer_like = f"%{customer.strip()}%"
            matching_customers = list((await db.scalars(select(BusinessRecord).where(
                BusinessRecord.module == "customer",
                BusinessRecord.title.ilike(customer_like),
            ))).all())
            customer_ids = [item.id for item in matching_customers]
            customer_nos = [
                str(item.serial_no or "").strip()
                for item in matching_customers
                if str(item.serial_no or "").strip()
            ]
            customer_conditions = [BusinessRecord.customer.ilike(customer_like)]
            if customer_ids:
                customer_conditions.extend([
                    BusinessRecord.data["customer_id"].as_integer().in_(customer_ids),
                    BusinessRecord.data["customer_record_id"].as_integer().in_(customer_ids),
                ])
            if customer_nos:
                customer_conditions.append(BusinessRecord.data["customer_no"].as_string().in_(customer_nos))
            conditions.append(or_(*customer_conditions))
        if relation_customer is None and customer_no.strip():
            conditions.append(BusinessRecord.data["customer_no"].as_string() == customer_no.strip())
        if exclude_archived:
            conditions.append(BusinessRecord.status.notin_(["已归档", "Archived", "archived"]))
    total = await db.scalar(select(func.count()).select_from(BusinessRecord).where(*conditions))
    result = list((await db.scalars(select(BusinessRecord).where(*conditions).order_by(BusinessRecord.updated_at.desc()).offset((page - 1) * page_size).limit(page_size))).all())
    allowed_fields = await _allowed_field_keys(identity, db)
    return {
        "items": await _contract_customer_record_dicts(result, allowed_fields, db, identity),
        "total": total or 0,
        "page": page,
        "page_size": page_size,
    }


CUSTOMER_CREATE_DATA_FIELDS = {
    "contact", "contact_accounts", "phone", "credit_code", "legal_representative", "registered_address",
    "invoice_title", "taxpayer_id", "invoice_address", "invoice_phone", "bank_name", "bank_account",
    "customer_type", "short_name", "fax", "legal_agent_id_no", "legal_agent_title", "customer_source",
    "is_shared", "is_assisted", "file_date", "level", "province", "postal_code", "patent_customer_type",
    "fee_reduction", "industry", "output_value", "cooperation_status", "gb_classification", "website",
    "organization_nature", "organization_code", "registration_region", "registration_postal_code",
    "registered_capital", "registration_year",
}
CUSTOMER_SYSTEM_DATA_FIELDS = {
    "notes", "last_contact_at", "contact_count", "last_modified_by", "last_modified_date",
    "status_before_recycle", "recycled_at", "recycled_by", "restored_at", "restored_by",
    "released_at", "released_by", "claimed_at", "claimed_by", "shared_with", "is_shared", "shared_at",
    "level_change", "key_change", "portal_access",
}
CUSTOMER_CREATE_STATUSES = {"潜在", "目标", "立项", "关怀", "签约", "谈判", "价值"}
CUSTOMER_LEVELS = {"潜在客户", "目标客户", "签约客户", "立案客户", "高级客户", "中级客户", "低级客户"}


def _normalize_customer_yes_no(value: object, field_name: str) -> str:
    if isinstance(value, bool):
        return "是" if value else "否"
    normalized = str(value or "").strip().casefold()
    if normalized in {"是", "yes", "true", "1"}: return "是"
    if normalized in {"否", "no", "false", "0", ""}: return "否"
    raise HTTPException(status_code=422, detail=f"{field_name}只能填写是或否")


def _normalize_customer_name(value: object) -> str:
    return unicodedata.normalize("NFKC", str(value or "").strip()).casefold()


def _record_belongs_to_customer(record: BusinessRecord, customer: BusinessRecord | None, customer_title: str) -> bool:
    """Match legacy-linked records through the customer master, not only a copied name."""
    data = record.data or {}
    if customer is not None:
        customer_id = int(customer.id)
        customer_no = str(customer.serial_no or "").strip()
        linked_id = int(data.get("customer_id") or data.get("customer_record_id") or 0)
        linked_no = str(data.get("customer_no") or "").strip()
        if linked_id and linked_id == customer_id:
            return True
        if customer_no and linked_no and linked_no == customer_no:
            return True
    return _normalize_customer_name(record.customer) == _normalize_customer_name(customer_title)


def _is_civil_case_type(value: object) -> bool:
    return str(value or "").strip() in {
        "民事案件",
        "民事争议",
    }


async def _customer_linked_business_counts(customer: BusinessRecord, db: AsyncSession) -> dict[str, int]:
    customer_no = str(customer.serial_no or "").strip()
    customer_name = _normalize_customer_name(customer.title)
    related_records = list((await db.scalars(
        select(BusinessRecord).where(BusinessRecord.module.in_(["contract", "case", "ipr_case"]))
    )).all())
    counts = {"contract_count": 0, "case_count": 0, "civil_case_count": 0}
    for related in related_records:
        data = related.data or {}
        linked = False
        try:
            linked = int(data.get("customer_id") or data.get("customer_record_id") or 0) == customer.id
        except (TypeError, ValueError):
            linked = False
        if not linked and customer_no:
            linked = str(data.get("customer_no") or "").strip() == customer_no
        if not linked and related.customer:
            linked = _normalize_customer_name(related.customer) == customer_name
        if not linked:
            continue
        if related.module == "contract":
            counts["contract_count"] += 1
        else:
            counts["case_count"] += 1
            if related.module == "case" and _is_civil_case_type(data.get("case_type")):
                counts["civil_case_count"] += 1
    return counts


async def _ensure_unique_customer_name(title: str, db: AsyncSession, *, exclude_id: int | None = None) -> None:
    normalized = _normalize_customer_name(title)
    if not normalized:
        raise HTTPException(status_code=422, detail="客户名称不能为空")
    rows = (await db.execute(
        select(BusinessRecord.id, BusinessRecord.title).where(BusinessRecord.module == "customer")
    )).all()
    if any(item_id != exclude_id and _normalize_customer_name(existing_title) == normalized for item_id, existing_title in rows):
        raise HTTPException(status_code=409, detail="客户名称已存在，不能创建或改为同名客户")


async def _next_customer_serial_no(db: AsyncSession) -> str:
    """Allocate the next visible customer number using the legacy SHKH rule."""
    serial_prefix = f"SHKH{datetime.now():%y}"
    serial_candidates = (await db.scalars(
        select(BusinessRecord.serial_no).where(
            BusinessRecord.module == "customer",
            BusinessRecord.serial_no.like(f"{serial_prefix}%"),
        )
    )).all()
    serial_sequence = max(
        (
            int(item[len(serial_prefix):])
            for item in serial_candidates
            if item[len(serial_prefix):].isdigit()
            and len(item[len(serial_prefix):]) == 5
        ),
        default=0,
    ) + 1
    return f"{serial_prefix}{serial_sequence:05d}"


@app.post(f"{settings.api_prefix}/customers", status_code=status.HTTP_201_CREATED)
async def create_customer(body: CustomerCreateInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    title = body.title.strip()
    await _ensure_unique_customer_name(title, db)
    customer_status = body.status.strip()
    if customer_status and customer_status not in CUSTOMER_CREATE_STATUSES:
        raise HTTPException(status_code=422, detail="客户状态无效")
    data = dict(body.data or {})
    for field_name in CUSTOMER_CREATE_DATA_FIELDS:
        if field_name in body.model_fields_set:
            data[field_name] = getattr(body, field_name)
    # New customers have no lifecycle or sharing history.  Drop every
    # client-supplied system field after merging both ``data`` and top-level
    # aliases so neither input shape can forge audit state or list membership.
    for protected_customer_field in CUSTOMER_SYSTEM_DATA_FIELDS:
        data.pop(protected_customer_field, None)
    data["shared_with"] = []
    data["is_shared"] = "否"
    data["customer_guid"] = str(uuid4())
    customer_type = str(data.get("customer_type") or "客户").strip()
    active_customer_types = set((await db.scalars(select(SystemParameter.name).where(
        SystemParameter.category == "customer_type", SystemParameter.is_active.is_(True),
    ))).all())
    if customer_type not in active_customer_types:
        raise HTTPException(status_code=422, detail="客户类型不存在或已停用")
    level = str(data.get("level") or "立案客户").strip()
    if level not in CUSTOMER_LEVELS: raise HTTPException(status_code=422, detail="客户等级无效")
    data["customer_type"] = customer_type; data["level"] = level
    for key, label in {"is_shared": "是否共享", "is_assisted": "上海市资助信息", "fee_reduction": "是否费减"}.items():
        data[key] = _normalize_customer_yes_no(data.get(key), label)
    credit_code = str(data.get("credit_code") or "").strip()
    if credit_code and any(character.isspace() for character in str(data.get("credit_code") or "")):
        raise HTTPException(status_code=422, detail="统一社会信用代码不允许包含空格")
    if credit_code:
        existing_customers = (await db.scalars(select(BusinessRecord).where(BusinessRecord.module == "customer"))).all()
        if any(str((item.data or {}).get("credit_code") or "").strip().casefold() == credit_code.casefold() for item in existing_customers):
            raise HTTPException(status_code=409, detail="统一社会信用代码已存在")
    data["credit_code"] = credit_code
    contact_values: list[str] = []
    raw_contact = body.contact if "contact" in body.model_fields_set else data.get("contact")
    if isinstance(raw_contact, list):
        contact_values.extend(str(value).strip() for value in raw_contact if str(value).strip())
    elif str(raw_contact or "").strip():
        contact_values.append(str(raw_contact).strip())
    contact_values.extend(
        str(value).strip()
        for value in list(body.contact_accounts or [])
        if str(value).strip()
    )
    contact_values = list(dict.fromkeys(contact_values))
    data["contact_accounts"] = contact_values
    data["contact"] = contact_values[0] if contact_values else ""
    current_user = await db.scalar(select(User).where(User.username == identity["username"], User.is_active.is_(True)))
    if not current_user: raise HTTPException(status_code=401, detail="当前用户不存在或已停用")
    requested_owner = body.owner.strip() or current_user.username
    department = body.department.strip() or current_user.department
    if identity.get("role") != "admin":
        department = current_user.department
        if identity.get("role") == "user": requested_owner = current_user.username
    owner = (await _resolve_active_customer_managers([requested_owner], db))[0]
    raw_managers = body.customer_managers if "customer_managers" in body.model_fields_set else data.get("customer_managers", [])
    managers = await _resolve_active_customer_managers(list(raw_managers or [owner]), db)
    data["customer_managers"] = [owner, *[manager for manager in managers if manager != owner]]
    serial_no = body.serial_no.strip()
    if not serial_no:
        serial_no = await _next_customer_serial_no(db)
    if await db.scalar(select(BusinessRecord.id).where(BusinessRecord.serial_no == serial_no)):
        raise HTTPException(status_code=409, detail="业务编号已存在")
    record = BusinessRecord(
        module="customer", serial_no=serial_no, title=title, customer=title, status=customer_status,
        owner=owner, department=department, description=body.description.strip(), data=data,
    )
    _mark_customer_modified(record, identity)
    db.add(record); await db.flush()
    db.add(WorkflowEvent(record_id=record.id, action="创建客户", to_status=record.status, operator=identity["username"], comment="通过新建客户专用入口创建"))
    await _sync_legacy_projection(record, identity, db)
    await db.commit(); await db.refresh(record)
    return await _record_dict_for_identity(record, identity, db)


CASE_PLAINTIFF_FIELDS = (
    "plaintiff", "plaintiffs", "plaintiff_name", "plaintiff_names",
    "appellant", "appellants", "appellant_name", "appellant_names",
)
CASE_DEFENDANT_FIELDS = (
    "defendant", "defendants", "defendant_name", "defendant_names", "opponent",
    "appellee", "appellees", "appellee_name", "appellee_names",
)
CASE_THIRD_PARTY_FIELDS = (
    "third_party", "third_parties", "third_party_name", "third_party_names",
)
# Legacy Chinese multi-party strings use adjacent commas.  A comma followed by
# whitespace is retained as part of an English legal name (for example
# ``Foo, Inc.``) rather than treated as a party boundary.
CASE_PARTY_SEPARATOR = re.compile(r",(?!\s)|[，、;；\r\n]+")


def _normalize_conflict_entity(value: object) -> str:
    """Normalize typography without weakening whole-entity equality."""
    return " ".join(unicodedata.normalize("NFKC", str(value or "")).split()).casefold()


def _conflict_entity_tokens(value: object) -> list[str]:
    """Expand stored party arrays and legacy comma-delimited party fields."""
    if isinstance(value, (list, tuple, set)):
        # An explicit array already defines entity boundaries.  Do not split an
        # English legal name such as ``Foo, Inc.`` inside one array element.
        return list(dict.fromkeys(str(item or "").strip() for item in value if str(item or "").strip()))
    tokens: list[str] = []
    for token in CASE_PARTY_SEPARATOR.split(str(value or "")):
        token = token.strip()
        if token and token not in tokens:
            tokens.append(token)
    return tokens


def _case_party_values(data: dict, fields: tuple[str, ...]) -> list[str]:
    """Use the first populated historical field family, preserving stored order."""
    for field in fields:
        tokens = _conflict_entity_tokens(data.get(field))
        if tokens:
            return tokens
    return []


def _case_party_match_values(data: dict, fields: tuple[str, ...]) -> list[str]:
    """Match only the same highest-priority field that the result will show."""
    for field in fields:
        raw_value = data.get(field)
        displayed = _conflict_entity_tokens(raw_value)
        if not displayed:
            continue
        if isinstance(raw_value, (list, tuple, set)):
            return displayed
        full_value = str(raw_value or "").strip()
        # Keep the complete scalar as an exact candidate so an English legal
        # name containing a comma remains searchable, while retaining legacy
        # comma-delimited entities as additional exact candidates.
        return list(dict.fromkeys([full_value, *displayed]))
    return []


def _case_conflict_entities(record: BusinessRecord) -> list[str]:
    data = record.data or {}
    values = [record.customer.strip()] if record.customer.strip() else []
    for fields in (CASE_PLAINTIFF_FIELDS, CASE_DEFENDANT_FIELDS, CASE_THIRD_PARTY_FIELDS):
        for value in _case_party_match_values(data, fields):
            if value not in values:
                values.append(value)
    return values


def _case_is_for_allocation_customer(record: BusinessRecord, customer: BusinessRecord | None, customer_title: str) -> bool:
    """Require the claimed customer to be the party in its stored litigation role."""
    if not _record_belongs_to_customer(record, customer, customer_title):
        return False
    data = record.data or {}
    role = str(data.get("client_position") or "").strip()
    if "原告" in role or "申请人" in role or "上诉人" in role:
        party_values = _case_party_values(data, CASE_PLAINTIFF_FIELDS)
    elif "被告" in role or "被申请人" in role or "被上诉人" in role:
        party_values = _case_party_values(data, CASE_DEFENDANT_FIELDS)
    elif "第三人" in role:
        party_values = _case_party_values(data, CASE_THIRD_PARTY_FIELDS)
    else:
        return True
    if not party_values:
        return True
    expected = _normalize_customer_name(customer_title)
    return any(_normalize_customer_name(value) == expected for value in party_values)


def _case_filing_date(record: BusinessRecord) -> date | None:
    raw_value = str((record.data or {}).get("filing_date") or "").strip()
    if not raw_value:
        return None
    try:
        return date.fromisoformat(raw_value[:10])
    except ValueError:
        return None


async def _require_customer_conflict_permission(identity: dict, db: AsyncSession) -> None:
    if identity.get("role") == "admin":
        return
    permission = await _permission_payload_for_identity(identity, db)
    if "customer-conflict" not in set(permission.get("menu_keys", [])):
        raise HTTPException(status_code=403, detail="当前角色没有客户利益检索权限")


async def _conflict_customer_managers(entity_name: str, db: AsyncSession) -> list[str]:
    normalized_name = _normalize_conflict_entity(entity_name)
    customers = list((await db.scalars(
        select(BusinessRecord).where(BusinessRecord.module == "customer")
    )).all())
    matching_customers = [
        customer for customer in customers
        if normalized_name in {
            _normalize_conflict_entity(customer.title),
            _normalize_conflict_entity(customer.customer),
        }
    ]
    if not matching_customers:
        return []
    # A current customer record wins over a recycled historical copy; within
    # the same lifecycle class the most recently updated row, then id, wins.
    matching_customers.sort(
        key=lambda customer: (
            customer.status != "已回收",
            customer.updated_at or customer.created_at,
            customer.id,
        ),
        reverse=True,
    )
    customer = matching_customers[0]
    manager_tokens = _conflict_entity_tokens((customer.data or {}).get("customer_managers"))
    if not manager_tokens and customer.owner:
        manager_tokens = [customer.owner]
    if not manager_tokens:
        return []
    users = list((await db.scalars(select(User).where(User.is_active.is_(True), User.username.in_(manager_tokens)))).all())
    display_names = {user.username: user.display_name or user.username for user in users}
    return [display_names.get(manager, manager) for manager in manager_tokens]


def _empty_customer_conflict_result(query: str) -> dict:
    return {
        "found": False, "query": query, "enterprise_name": query,
        "latest_case_no": "", "latest_case_date": "",
        "plaintiffs": [], "defendants": [], "third_parties": [],
        "our_customer": "", "customer_managers": [],
    }


@app.get(f"{settings.api_prefix}/customers/conflicts")
async def customer_conflicts(
    name: str = Query(min_length=1, max_length=100),
    identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db),
):
    """Return the latest case containing one exact, normalized enterprise party."""
    await _require_customer_conflict_permission(identity, db)
    query = name.strip()
    if not query:
        raise HTTPException(status_code=422, detail="企业名称不能为空")
    needle = _normalize_conflict_entity(query)

    # Conflict checking deliberately spans the whole firm.  Only the minimum
    # original-page disclosure is returned and no source record id is exposed.
    cases = list((await db.scalars(
        select(BusinessRecord).where(BusinessRecord.module == "case")
    )).all())
    matching_cases = cases if not needle else [
        case_record for case_record in cases
        if any(_normalize_conflict_entity(entity) == needle for entity in _case_conflict_entities(case_record))
    ]
    if not matching_cases:
        return _empty_customer_conflict_result(query)
    latest_case = max(
        matching_cases,
        key=lambda case_record: (_case_filing_date(case_record) or date.min, case_record.id),
    )
    data = latest_case.data or {}
    filing_date = _case_filing_date(latest_case)
    plaintiffs = _case_party_values(data, CASE_PLAINTIFF_FIELDS) or _conflict_entity_tokens(latest_case.customer)
    return {
        "found": True,
        "query": query,
        "enterprise_name": query,
        "latest_case_no": latest_case.serial_no,
        "latest_case_date": filing_date.isoformat() if filing_date else "",
        "plaintiffs": plaintiffs,
        "defendants": _case_party_values(data, CASE_DEFENDANT_FIELDS),
        "third_parties": _case_party_values(data, CASE_THIRD_PARTY_FIELDS),
        "our_customer": latest_case.customer,
        "customer_managers": await _conflict_customer_managers(query, db),
    }


async def _customer_or_404(customer_id: int, identity: dict, db: AsyncSession) -> BusinessRecord:
    try:
        return await _ensure_record_module(customer_id, "customer", identity, db)
    except HTTPException as exc:
        if exc.status_code == 404:
            raise HTTPException(status_code=404, detail="客户不存在或无权访问") from exc
        raise


async def _locked_customer_or_404(customer_id: int, identity: dict, db: AsyncSession) -> BusinessRecord:
    """Lock a visible customer and refresh it after waiting for a concurrent writer."""
    conditions = [
        BusinessRecord.id == customer_id,
        BusinessRecord.module == "customer",
        *(await _record_scope_conditions(identity, db)),
    ]
    customer = await db.scalar(
        select(BusinessRecord)
        .where(*conditions)
        .with_for_update()
        .execution_options(populate_existing=True)
    )
    if not customer:
        raise HTTPException(status_code=404, detail="客户不存在或无权访问")
    return customer


def _customer_event(customer: BusinessRecord, action: str, identity: dict, comment: str, from_status: str | None = None) -> WorkflowEvent:
    _mark_customer_modified(customer, identity)
    return WorkflowEvent(record_id=customer.id, action=action, from_status=from_status or customer.status, to_status=customer.status, operator=identity["username"], comment=comment)


async def _customer_by_guid(customer_guid: str, identity: dict, db: AsyncSession) -> BusinessRecord:
    guid = str(customer_guid or "").strip()
    if not guid:
        raise HTTPException(status_code=422, detail="客户 Guid 不能为空")
    customers = (await db.scalars(select(BusinessRecord).where(BusinessRecord.module == "customer"))).all()
    customer = next((item for item in customers if _customer_guid(item) == guid), None)
    if not customer:
        raise HTTPException(status_code=404, detail="客户不存在或无权访问")
    return await _customer_or_404(customer.id, identity, db)


