@app.post(f"{settings.api_prefix}/hr/{{employee_id}}/transition")
async def transition_employee(employee_id: int, body: HrTransitionInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    if identity.get("role") not in {"admin", "manager"}: raise HTTPException(status_code=403, detail="只有管理员或部门负责人可以办理人事状态")
    item = await _ensure_record_module(employee_id, "hr", identity, db)
    allowed = WORKFLOW_TRANSITIONS["hr"].get(item.status, [])
    if body.to_status not in allowed: raise HTTPException(status_code=409, detail=f"不能从“{item.status}”办理到“{body.to_status}”")
    reason = body.reason.strip()
    if body.to_status in {"离职", "停用"} and len(reason) < 2: raise HTTPException(status_code=422, detail="离职或停用必须填写原因")
    if body.effective_date < date(2000, 1, 1): raise HTTPException(status_code=422, detail="办理日期无效")
    previous = item.status; data = dict(item.data or {})
    if body.to_status == "在职":
        if previous == "试用":
            data.update({"regularized_at": str(body.effective_date), "regularized_by": identity["username"]}); action = "试用转正"
        else:
            data.update({"reactivated_at": str(body.effective_date), "reactivated_by": identity["username"]}); action = "恢复在职"
    elif body.to_status == "离职":
        data.update({"offboard_date": str(body.effective_date), "offboard_reason": reason, "handover_to": body.handover_to.strip(), "offboard_by": identity["username"]}); action = "办理离职"
    else:
        data.update({"disabled_at": str(body.effective_date), "disabled_reason": reason, "disabled_by": identity["username"]}); action = "停用员工"
    # The dedicated HR lifecycle is the authoritative employment switch for a
    # linked employee login.  Every non-administrator employee account,
    # including manager and auditor accounts, must be synchronized.  The
    # separately protected administrator account is never altered here.
    linked_username = str(data.get("username") or item.owner or "").strip().lower()
    linked_user = await db.scalar(select(User).where(User.username == linked_username)) if linked_username else None
    if linked_user and linked_user.role != "admin":
        login_enabled = body.to_status == "在职"
        linked_user.is_active = login_enabled
        data["is_active"] = login_enabled
        data["login_account_synced_at"] = datetime.now().isoformat()
        data["login_account_sync"] = "已启用" if login_enabled else "已停用"
    item.status = body.to_status; item.data = data
    db.add(WorkflowEvent(record_id=item.id, action=action, from_status=previous, to_status=item.status, operator=identity["username"], comment=body.comment or reason))
    await db.commit(); await db.refresh(item); return _record_dict(item, await _allowed_field_keys(identity, db))


def _warehouse_evidence_status(item: BusinessRecord) -> str:
    data = item.data or {}
    explicit = str(data.get("evidence_status") or "").strip()
    if explicit:
        return explicit
    return {"在库": "已入库", "借出": "已出库", "归还中": "已出库", "报废": "已销毁"}.get(item.status, "未入库")


async def _resolve_warehouse_location(
    body: WarehouseEvidenceInput | WarehouseEvidenceCheckInInput | WarehouseEvidenceRecheckInInput | ClueCollectionInput | NotaryCertificateInput,
    db: AsyncSession,
) -> tuple[Warehouse, WarehouseStorageLocation]:
    """Resolve one active location from catalog master data, never free text."""
    location: WarehouseStorageLocation | None = None
    if body.storage_location_id:
        location = await db.get(WarehouseStorageLocation, body.storage_location_id)
    else:
        warehouse_name = body.warehouse.strip()
        location_name = body.location.strip()
        if warehouse_name and location_name:
            location = await db.scalar(
                select(WarehouseStorageLocation)
                .join(Warehouse, Warehouse.id == WarehouseStorageLocation.warehouse_id)
                .where(Warehouse.name == warehouse_name, WarehouseStorageLocation.name == location_name)
                .order_by(WarehouseStorageLocation.id)
            )
    if not location:
        raise HTTPException(status_code=422, detail="请从仓库库位主数据选择有效库位")
    warehouse = await db.get(Warehouse, location.warehouse_id)
    if not warehouse or not warehouse.is_active or not location.is_active:
        raise HTTPException(status_code=422, detail="所选仓库或库位已停用")
    if body.warehouse_id and body.warehouse_id != warehouse.id:
        raise HTTPException(status_code=422, detail="仓库与库位不属于同一层级")
    return warehouse, location


def _warehouse_location_data(warehouse: Warehouse, location: WarehouseStorageLocation) -> dict[str, object]:
    return {
        "warehouse_id": warehouse.id,
        "warehouse_no": warehouse.warehouse_no,
        "warehouse": warehouse.name,
        "storage_location_id": location.id,
        "storage_location_no": location.storage_location_no,
        "location": location.name,
    }


def _warehouse_location_display(warehouse: Warehouse, location: WarehouseStorageLocation) -> str:
    return f"{warehouse.name} / {location.name}"


async def _set_warehouse_evidence_location(
    record_id: int,
    warehouse: Warehouse,
    location: WarehouseStorageLocation,
    username: str,
    db: AsyncSession,
) -> WarehouseEvidenceLocation:
    binding = await db.scalar(select(WarehouseEvidenceLocation).where(WarehouseEvidenceLocation.record_id == record_id))
    if not binding:
        binding = WarehouseEvidenceLocation(
            record_id=record_id,
            warehouse_id=warehouse.id,
            storage_location_id=location.id,
            assigned_by=username,
        )
        db.add(binding)
        return binding
    binding.warehouse_id = warehouse.id
    binding.storage_location_id = location.id
    binding.assigned_by = username
    binding.assigned_at = datetime.now(timezone.utc)
    return binding


async def _sync_case_notary_warehouse_evidence(
    case_record: BusinessRecord,
    locations: list[tuple[Warehouse, WarehouseStorageLocation]],
    notary_nos: str,
    username: str,
    db: AsyncSession,
) -> None:
    """Keep the case's physical notary evidence visible in the warehouse tree.

    Case details store the human-readable location summary, while warehouse
    counts and filtered rows are driven by ``warehouse_evidence_locations``.
    The two records therefore have to be updated in one transaction.
    """
    related = list((await db.scalars(
        select(BusinessRecord)
        .where(
            BusinessRecord.module == "warehouse",
            or_(
                BusinessRecord.data["case_record_id"].as_integer() == case_record.id,
                BusinessRecord.data["case_id"].as_integer() == case_record.id,
                BusinessRecord.data["case_no"].as_string() == case_record.serial_no,
            ),
        )
        .order_by(BusinessRecord.id)
    )).all())
    case_data = dict(case_record.data or {})
    for index, (warehouse, location) in enumerate(locations):
        if index < len(related):
            evidence = related[index]
        else:
            evidence = BusinessRecord(
                module="warehouse",
                serial_no=f"CKZ-{case_record.id}-{index + 1}",
                title=f"{case_record.title}—公证证物",
                customer=case_record.customer,
                status="在库",
                owner=str(case_data.get("investigator") or case_record.owner or username),
                department=case_record.department,
                description="由案件公证信息维护的实体证物",
            )
            db.add(evidence)
            await db.flush()
            related.append(evidence)
        evidence_data = dict(evidence.data or {})
        evidence.title = case_record.title or evidence.title
        evidence.customer = case_record.customer
        evidence.owner = str(case_data.get("investigator") or evidence.owner or case_record.owner or username)
        evidence.department = case_record.department
        evidence.status = "在库"
        evidence.data = {
            **evidence_data,
            "source": "案件公证信息",
            "case_record_id": case_record.id,
            "case_id": case_record.id,
            "case_no": case_record.serial_no,
            "notary_no": notary_nos,
            "shop_name": case_record.title,
            "rights_holder": case_record.customer,
            "investigator": str(case_data.get("investigator") or case_record.owner or username),
            "evidence_status": "已入库",
            "case_notary_evidence": True,
            **_warehouse_location_data(warehouse, location),
        }
        await _set_warehouse_evidence_location(evidence.id, warehouse, location, username, db)

    # A case can have more pre-existing warehouse rows than selected locations.
    # Move every related physical record into the currently selected locations so
    # the former location never keeps an obsolete count after a successful edit.
    for index, evidence in enumerate(related[len(locations):], start=len(locations)):
        warehouse, location = locations[index % len(locations)]
        evidence.data = {
            **dict(evidence.data or {}),
            "source": "案件公证信息",
            "case_record_id": case_record.id,
            "case_id": case_record.id,
            "case_no": case_record.serial_no,
            "notary_no": notary_nos,
            "evidence_status": "已入库",
            "case_notary_evidence": True,
            **_warehouse_location_data(warehouse, location),
        }
        await _set_warehouse_evidence_location(evidence.id, warehouse, location, username, db)


def _warehouse_evidence_location_statement(identity_conditions: list):
    return (
        select(BusinessRecord, WarehouseEvidenceLocation, Warehouse, WarehouseStorageLocation)
        .select_from(BusinessRecord)
        .outerjoin(WarehouseEvidenceLocation, WarehouseEvidenceLocation.record_id == BusinessRecord.id)
        .outerjoin(Warehouse, Warehouse.id == WarehouseEvidenceLocation.warehouse_id)
        .outerjoin(WarehouseStorageLocation, WarehouseStorageLocation.id == WarehouseEvidenceLocation.storage_location_id)
        # Evidence created by the investigation collection flow keeps its
        # canonical ``evidence`` module, but a warehouse binding makes it a
        # warehouse-visible record.  Restricting this query to ``warehouse``
        # hid those bound evidence records from the warehouse overview.
        .where(
            or_(
                BusinessRecord.module == "warehouse",
                and_(
                    BusinessRecord.module == "evidence",
                    WarehouseEvidenceLocation.id.is_not(None),
                ),
            ),
            *identity_conditions,
        )
    )


def _warehouse_evidence_dict(
    item: BusinessRecord,
    binding: WarehouseEvidenceLocation | None,
    warehouse: Warehouse | None,
    location: WarehouseStorageLocation | None,
) -> dict[str, object]:
    data = dict(item.data or {})
    canonical_notary_no = str(
        data.get("notary_no")
        or data.get("notary_nos")
        or data.get("certificate_no")
        or data.get("notarization_no")
        or ""
    ).strip()
    if canonical_notary_no:
        data["notary_no"] = canonical_notary_no
    if warehouse and location:
        data.update(_warehouse_location_data(warehouse, location))
    return {
        "id": item.id,
        "serial_no": item.serial_no,
        "title": item.title,
        "customer": item.customer,
        "status": item.status,
        "owner": item.owner,
        "department": item.department,
        "description": item.description,
        "data": data,
        "warehouse_binding_id": binding.id if binding else None,
        "created_at": item.created_at,
        "updated_at": item.updated_at,
    }


@app.get(f"{settings.api_prefix}/warehouse/catalog")
async def warehouse_catalog(
    include_inactive: bool = True,
    identity: dict = Depends(current_identity),
    db: AsyncSession = Depends(get_db),
):
    await _require_record_module_menu("warehouse", identity, db, action="查看")
    warehouse_statement = select(Warehouse)
    location_statement = select(WarehouseStorageLocation)
    if not include_inactive:
        warehouse_statement = warehouse_statement.where(Warehouse.is_active.is_(True))
        location_statement = location_statement.where(WarehouseStorageLocation.is_active.is_(True))
    warehouses = list((await db.scalars(warehouse_statement.order_by(Warehouse.sort_order, Warehouse.warehouse_no, Warehouse.id))).all())
    locations = list((await db.scalars(location_statement.order_by(WarehouseStorageLocation.sort_order, WarehouseStorageLocation.storage_location_no, WarehouseStorageLocation.id))).all())
    counts = dict((await db.execute(
        select(WarehouseEvidenceLocation.storage_location_id, func.count(WarehouseEvidenceLocation.id))
        .group_by(WarehouseEvidenceLocation.storage_location_id)
    )).all())
    locations_by_warehouse: dict[int, list[dict[str, object]]] = {}
    for location in locations:
        locations_by_warehouse.setdefault(location.warehouse_id, []).append({
            "id": location.id,
            "storage_location_no": location.storage_location_no,
            "name": location.name,
            "address": location.address,
            "is_active": location.is_active,
            "sort_order": location.sort_order,
            "goods_count": int(counts.get(location.id, 0)),
        })
    return {
        "items": [
            {
                "id": warehouse.id,
                "warehouse_no": warehouse.warehouse_no,
                "name": warehouse.name,
                "address": warehouse.address,
                "is_active": warehouse.is_active,
                "sort_order": warehouse.sort_order,
                "goods_count": sum(int(location["goods_count"]) for location in locations_by_warehouse.get(warehouse.id, [])),
                "locations": locations_by_warehouse.get(warehouse.id, []),
            }
            for warehouse in warehouses
        ],
        "total": len(warehouses),
        "location_total": len(locations),
    }


@app.get(f"{settings.api_prefix}/warehouse/evidence")
async def list_warehouse_evidence(
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=15, ge=1, le=200),
    warehouse_id: int | None = Query(default=None, gt=0),
    storage_location_id: int | None = Query(default=None, gt=0),
    keyword: str = "",
    rights_holder: str = "",
    evidence_status: str = "",
    case_no: str = "",
    shop_name: str = "",
    investigator: str = "",
    notary_no: str = "",
    evidence_date_from: str = "",
    evidence_date_to: str = "",
    identity: dict = Depends(current_identity),
    db: AsyncSession = Depends(get_db),
):
    await _require_record_module_menu("warehouse", identity, db, action="查看")
    conditions = list(await _record_scope_conditions(identity, db))
    if warehouse_id:
        conditions.append(WarehouseEvidenceLocation.warehouse_id == warehouse_id)
    if storage_location_id:
        conditions.append(WarehouseEvidenceLocation.storage_location_id == storage_location_id)
    if keyword.strip():
        term = f"%{keyword.strip()}%"
        conditions.append(or_(
            BusinessRecord.serial_no.ilike(term),
            BusinessRecord.title.ilike(term),
            BusinessRecord.customer.ilike(term),
            BusinessRecord.data["legacy_evidence_no"].as_string().ilike(term),
            BusinessRecord.data["clue_no"].as_string().ilike(term),
            BusinessRecord.data["case_no"].as_string().ilike(term),
        ))
    def data_like(key: str, value: str):
        return BusinessRecord.data[key].as_string().ilike(f"%{value.strip()}%") if value.strip() else None

    filter_conditions = [
        data_like("rights_holder", rights_holder),
        data_like("evidence_status", evidence_status),
        data_like("case_no", case_no),
        data_like("shop_name", shop_name),
        data_like("investigator", investigator),
    ]
    conditions.extend(condition for condition in filter_conditions if condition is not None)
    if notary_no.strip():
        term = f"%{notary_no.strip()}%"
        conditions.append(or_(
            BusinessRecord.data["notary_no"].as_string().ilike(term),
            BusinessRecord.data["notary_nos"].as_string().ilike(term),
            BusinessRecord.data["certificate_no"].as_string().ilike(term),
            BusinessRecord.data["notarization_no"].as_string().ilike(term),
        ))
    if evidence_date_from.strip():
        conditions.append(BusinessRecord.data["evidence_date"].as_string() >= evidence_date_from.strip())
    if evidence_date_to.strip():
        conditions.append(BusinessRecord.data["evidence_date"].as_string() <= evidence_date_to.strip())
    statement = _warehouse_evidence_location_statement(conditions)
    total = int(await db.scalar(select(func.count()).select_from(statement.subquery())) or 0)
    rows = (await db.execute(statement.order_by(BusinessRecord.created_at.desc(), BusinessRecord.id.desc()).offset((page - 1) * page_size).limit(page_size))).all()
    return {
        "items": [_warehouse_evidence_dict(*row) for row in rows],
        "total": total,
        "page": page,
        "page_size": page_size,
    }


@app.post(f"{settings.api_prefix}/warehouse/evidence", status_code=status.HTTP_201_CREATED)
async def create_warehouse_evidence(body: WarehouseEvidenceInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    if identity.get("role") not in {"admin", "manager"}:
        raise HTTPException(status_code=403, detail="只有管理员或部门负责人可以登记证物")
    if await db.scalar(select(BusinessRecord.id).where(BusinessRecord.serial_no == body.serial_no.strip())):
        raise HTTPException(status_code=409, detail="线索编号已存在")
    department = "上海分所"
    if identity.get("role") != "admin":
        user = await db.scalar(select(User).where(User.username == identity["username"]))
        if not user:
            raise HTTPException(status_code=401, detail="当前用户不存在")
        department = user.department
    warehouse, location = await _resolve_warehouse_location(body, db)
    evidence_data = body.model_dump(mode="json", exclude={"serial_no", "description", "warehouse_id", "storage_location_id", "warehouse", "location"})
    evidence_data.update(_warehouse_location_data(warehouse, location))
    evidence_data.update({
        "category": "证物",
        "quantity": 1,
        "unit": "件",
        "evidence_status": "未入库",
        "registered_at": str(date.today()),
        "registered_by": identity["username"],
    })
    item = BusinessRecord(
        module="warehouse",
        serial_no=body.serial_no.strip(),
        title=body.shop_name.strip(),
        customer=body.rights_holder.strip(),
        status="在库",
        owner=body.investigator.strip(),
        department=department,
        description=body.description.strip(),
        data=evidence_data,
    )
    db.add(item)
    await db.flush()
    await _set_warehouse_evidence_location(item.id, warehouse, location, identity["username"], db)
    db.add(WorkflowEvent(record_id=item.id, action="证物登记", to_status="未入库", operator=identity["username"], comment=body.description.strip()))
    await db.commit()
    await db.refresh(item)
    return _record_dict(item, await _allowed_field_keys(identity, db))


@app.patch(f"{settings.api_prefix}/warehouse/evidence/{{item_id}}")
async def update_warehouse_evidence(item_id: int, body: WarehouseEvidenceInput, identity: dict = Depends(current_identity), db: AsyncSession = Depends(get_db)):
    if identity.get("role") not in {"admin", "manager"}:
        raise HTTPException(status_code=403, detail="只有管理员或部门负责人可以修改证物资料")
    item = await _ensure_record_module(item_id, "warehouse", identity, db)
    evidence_status = _warehouse_evidence_status(item)
    if evidence_status in {"已出库", "已销毁"}:
        raise HTTPException(status_code=409, detail="已出库或已销毁的证物不能修改资料")
    duplicate = await db.scalar(select(BusinessRecord.id).where(BusinessRecord.serial_no == body.serial_no.strip(), BusinessRecord.id != item.id))
    if duplicate:
        raise HTTPException(status_code=409, detail="线索编号已存在")
    warehouse, location = await _resolve_warehouse_location(body, db)
    process_fields = {
        key: value for key, value in (item.data or {}).items()
        if key in {
            "category", "quantity", "unit", "evidence_status", "registered_at", "registered_by",
            "checked_in_at", "checked_in_by", "checked_out_at", "checked_out_by", "recipient",
            "checkout_purpose", "rechecked_in_at", "rechecked_in_by", "return_condition",
            "destroyed_at", "destroyed_by", "destroy_reason",
        }
    }
    evidence_data = body.model_dump(mode="json", exclude={"serial_no", "description", "warehouse_id", "storage_location_id", "warehouse", "location"})
    evidence_data.update(_warehouse_location_data(warehouse, location))
    evidence_data.update(process_fields)
    item.serial_no = body.serial_no.strip()
    item.title = body.shop_name.strip()
    item.customer = body.rights_holder.strip()
    item.owner = body.investigator.strip()
    item.description = body.description.strip()
    item.data = evidence_data
    await _set_warehouse_evidence_location(item.id, warehouse, location, identity["username"], db)
    db.add(WorkflowEvent(record_id=item.id, action="修改证物资料", from_status=evidence_status, to_status=evidence_status, operator=identity["username"], comment=body.description.strip()))
    await db.commit()
    await db.refresh(item)
    return _record_dict(item, await _allowed_field_keys(identity, db))


